import type { BankQuestion } from "@/lib/bank";

/** Data Interpretation (Quantitative Aptitude): 208 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-data-interpretation-1","question":"Sales (₹ lakh) of a company — 2019: 40, 2020: 50, 2021: 45, 2022: 60. What is the percentage increase in sales from 2019 to 2020?","options":["10%","50%","20%","25%"],"answer":3,"explanation":"Increase = 50 − 40 = 10 on a base of 40: 10/40 × 100 = 25%. 20% wrongly uses 50 as the base.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"एक कंपनी की बिक्री (₹ लाख में) — 2019: 40, 2020: 50, 2021: 45, 2022: 60। 2019 से 2020 तक बिक्री में प्रतिशत वृद्धि कितनी है?","optionsHi":["10%","50%","20%","25%"],"explanationHi":"वृद्धि = 50 − 40 = 10, आधार 40 पर: 10/40 × 100 = 25%। 20% गलती से 50 को आधार मान लेने पर आता है।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-2","question":"Marks of a student — Maths: 80, Science: 70, English: 60, Hindi: 90. What is the average mark?","options":["70","72.5","80","75"],"answer":3,"explanation":"Total = 80 + 70 + 60 + 90 = 300, so the average is 300/4 = 75. 70 and 80 are single subjects' marks, and 72.5 comes from a slip in the total.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"एक विद्यार्थी के अंक — गणित: 80, विज्ञान: 70, अंग्रेज़ी: 60, हिंदी: 90। औसत अंक कितने हैं?","optionsHi":["70","72.5","80","75"],"explanationHi":"कुल = 80 + 70 + 60 + 90 = 300, अतः औसत 300/4 = 75 है। 70 और 80 अलग-अलग विषयों के अंक हैं, और 72.5 कुल जोड़ में चूक से आता है।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-3","question":"Students in a school — Class VI: 120, Class VII: 150, Class VIII: 130. What is the ratio of students in Class VI to Class VII?","options":["6 : 5","5 : 4","4 : 5","12 : 13"],"answer":2,"explanation":"120 : 150 = 4 : 5 after dividing both by 30. 5 : 4 inverts the order asked (VI to VII), and 12 : 13 wrongly compares VI with VIII.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"एक विद्यालय में विद्यार्थी — कक्षा VI: 120, कक्षा VII: 150, कक्षा VIII: 130। कक्षा VI और कक्षा VII के विद्यार्थियों का अनुपात कितना है?","optionsHi":["6 : 5","5 : 4","4 : 5","12 : 13"],"explanationHi":"दोनों को 30 से भाग देने पर 120 : 150 = 4 : 5। 5 : 4 पूछे गए क्रम (VI से VII) को उलट देता है, और 12 : 13 गलती से VI की तुलना VIII से करता है।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-4","question":"Rice production (tonnes) — January: 200, February: 250, March: 300. By what percent is March production more than January production?","options":["100%","33.33%","25%","50%"],"answer":3,"explanation":"(300 − 200)/200 × 100 = 50%. 33.33% would be the figure with March as the base.","difficulty":"easy","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"चावल का उत्पादन (टन में) — जनवरी: 200, फरवरी: 250, मार्च: 300। मार्च का उत्पादन जनवरी के उत्पादन से कितने प्रतिशत अधिक है?","optionsHi":["100%","33.33%","25%","50%"],"explanationHi":"(300 − 200)/200 × 100 = 50%। 33.33% वह मान होता जब मार्च को आधार लिया जाता।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-5","question":"Monthly expenditure of a family (₹) — Food: 12,000, Rent: 8,000, Education: 6,000, Others: 4,000. What percent of the total is spent on rent?","options":["25%","20%","36.36%","26.67%"],"answer":3,"explanation":"Total = 12,000 + 8,000 + 6,000 + 4,000 = ₹30,000, so rent is 8,000/30,000 = 26.67%. 25% assumes four equal shares, 20% uses a wrong base of 40,000, and 36.36% divides rent by the other expenses (22,000) instead of the total.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक परिवार का मासिक व्यय (₹) — भोजन: 12,000, किराया: 8,000, शिक्षा: 6,000, अन्य: 4,000। कुल व्यय का कितना प्रतिशत किराये पर खर्च होता है?","optionsHi":["25%","20%","36.36%","26.67%"],"explanationHi":"कुल = 12,000 + 8,000 + 6,000 + 4,000 = ₹30,000, अतः किराया 8,000/30,000 = 26.67% है। 25% चार बराबर हिस्से मानने पर आता है, 20% में गलत आधार 40,000 लिया गया है, और 36.36% में किराये को कुल की जगह अन्य खर्चों (22,000) से भाग दिया गया है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-6","question":"In a pie chart of a ₹72,000 monthly budget, the sector for Transport has a central angle of 60°. How much is spent on transport?","options":["₹6,000","₹12,000","₹14,400","₹10,000"],"answer":1,"explanation":"60° is 60/360 = 1/6 of the pie, so transport = 72,000/6 = ₹12,000. ₹6,000 halves this by using 1/12, and ₹14,400 treats 60° as 20%.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"₹72,000 के मासिक बजट के एक पाई चार्ट में परिवहन वाले खंड का केंद्रीय कोण 60° है। परिवहन पर कितना खर्च होता है?","optionsHi":["₹6,000","₹12,000","₹14,400","₹10,000"],"explanationHi":"60° पाई का 60/360 = 1/6 है, अतः परिवहन = 72,000/6 = ₹12,000। ₹6,000 में 1/12 लेकर इसे आधा कर दिया गया है, और ₹14,400 में 60° को 20% मान लिया गया है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-7","question":"Profit (₹ crore) — 2018: 24, 2019: 30, 2020: 27, 2021: 36. In which year was the percentage increase over the previous year the highest?","options":["Equal in 2019 and 2021","2020","2021","2019"],"answer":2,"explanation":"2019: 6/24 = 25%; 2020: −3/30 = −10%; 2021: 9/27 = 33.33%. The highest rise is in 2021, even though the absolute rise (9) is what most people check.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"लाभ (₹ करोड़ में) — 2018: 24, 2019: 30, 2020: 27, 2021: 36। किस वर्ष में पिछले वर्ष की तुलना में प्रतिशत वृद्धि सबसे अधिक रही?","optionsHi":["2019 और 2021 में समान","2020","2021","2019"],"explanationHi":"2019: 6/24 = 25%; 2020: −3/30 = −10%; 2021: 9/27 = 33.33%। सबसे अधिक वृद्धि 2021 में है, जबकि अधिकतर लोग निरपेक्ष वृद्धि (9) देखते हैं।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-8","question":"Cars sold — Company A: 2020: 300, 2021: 360; Company B: 2020: 400, 2021: 440. What is the ratio of A’s percentage growth to B’s percentage growth?","options":["2 : 1","9 : 11","1 : 2","3 : 2"],"answer":0,"explanation":"A grew 60/300 = 20%; B grew 40/400 = 10%; ratio 20 : 10 = 2 : 1.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"बेची गई कारें — कंपनी A: 2020: 300, 2021: 360; कंपनी B: 2020: 400, 2021: 440। A की प्रतिशत वृद्धि और B की प्रतिशत वृद्धि का अनुपात कितना है?","optionsHi":["2 : 1","9 : 11","1 : 2","3 : 2"],"explanationHi":"A की वृद्धि 60/300 = 20%; B की वृद्धि 40/400 = 10%; अनुपात 20 : 10 = 2 : 1।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-9","question":"Exports (₹ crore) — 2017: 120, 2018: 135, 2019: 150, 2020: 110, 2021: 160. What is the average annual export over the five years?","options":["₹137 crore","₹140 crore","₹130 crore","₹135 crore"],"answer":3,"explanation":"Sum = 120 + 135 + 150 + 110 + 160 = 675; average = 675/5 = ₹135 crore.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"निर्यात (₹ करोड़ में) — 2017: 120, 2018: 135, 2019: 150, 2020: 110, 2021: 160। पाँच वर्षों का औसत वार्षिक निर्यात कितना है?","optionsHi":["₹137 करोड़","₹140 करोड़","₹130 करोड़","₹135 करोड़"],"explanationHi":"योग = 120 + 135 + 150 + 110 + 160 = 675; औसत = 675/5 = ₹135 करोड़।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-10","question":"Population of a town (thousand) — 2000: 80, 2010: 100, 2020: 125. What is the overall percentage increase from 2000 to 2020?","options":["62.5%","45%","56.25%","50%"],"answer":2,"explanation":"(125 − 80)/80 × 100 = 45/80 × 100 = 56.25%. Adding the two 25% decade rises to get 50% ignores compounding.","difficulty":"moderate","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक कस्बे की जनसंख्या (हज़ार में) — 2000: 80, 2010: 100, 2020: 125। 2000 से 2020 तक कुल प्रतिशत वृद्धि कितनी है?","optionsHi":["62.5%","45%","56.25%","50%"],"explanationHi":"(125 − 80)/80 × 100 = 45/80 × 100 = 56.25%। दोनों दशकों की 25% वृद्धियों को जोड़कर 50% निकालना चक्रवृद्धि की अनदेखी है।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-11","question":"Employees by department — HR: 40, IT: 120, Sales: 90, Finance: 50. What is the central angle of the IT sector in a pie chart?","options":["150°","120°","144°","108°"],"answer":2,"explanation":"Total = 40 + 120 + 90 + 50 = 300; IT's angle = 120/300 × 360° = 144°. 120° reads the head-count as degrees, ignoring the 300 total.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"विभागवार कर्मचारी — HR: 40, IT: 120, बिक्री: 90, वित्त: 50। पाई चार्ट में IT खंड का केंद्रीय कोण कितना होगा?","optionsHi":["150°","120°","144°","108°"],"explanationHi":"कुल = 40 + 120 + 90 + 50 = 300; IT का कोण = 120/300 × 360° = 144°। 120° में कर्मचारियों की संख्या को ही अंश मान लिया गया है और कुल 300 की अनदेखी की गई है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-12","question":"Books sold by a shop — Monday: 45, Tuesday: 60, Wednesday: 55, Thursday: 70, Friday: 50. On how many days were the sales above the five-day average?","options":["1","2","3","4"],"answer":1,"explanation":"Average = 280/5 = 56. Only Tuesday (60) and Thursday (70) exceed it.","difficulty":"moderate","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"एक दुकान द्वारा बेची गई पुस्तकें — सोमवार: 45, मंगलवार: 60, बुधवार: 55, गुरुवार: 70, शुक्रवार: 50। कितने दिनों में बिक्री पाँच दिन के औसत से अधिक रही?","optionsHi":["1","2","3","4"],"explanationHi":"औसत = 280/5 = 56। केवल मंगलवार (60) और गुरुवार (70) इससे अधिक हैं।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-13","question":"Production (thousand units) — Factory P: 2019: 64, 2020: 80, 2021: 72; Factory Q: 2019: 48, 2020: 60, 2021: 90. Q’s total production over the three years is what percent of P’s?","options":["90%","109.09%","91.67%","88.5%"],"answer":2,"explanation":"P = 216, Q = 198; 198/216 × 100 = 91.67%. 109.09% is P as a percent of Q.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"उत्पादन (हज़ार इकाइयाँ) — कारखाना P: 2019: 64, 2020: 80, 2021: 72; कारखाना Q: 2019: 48, 2020: 60, 2021: 90। तीन वर्षों में Q का कुल उत्पादन P के कुल उत्पादन का कितना प्रतिशत है?","optionsHi":["90%","109.09%","91.67%","88.5%"],"explanationHi":"P = 216, Q = 198; 198/216 × 100 = 91.67%। 109.09% Q के सापेक्ष P का प्रतिशत है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-14","question":"Income and expenditure (₹ lakh) — 2020: 150 and 120; 2021: 180 and 140; 2022: 210 and 175. In which year was the profit as a percentage of expenditure the highest?","options":["2020 and 2021 equally","2020","2021","2022"],"answer":2,"explanation":"2020: 30/120 = 25%; 2021: 40/140 = 28.57%; 2022: 35/175 = 20%. 2021 is highest.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"आय और व्यय (₹ लाख में) — 2020: 150 और 120; 2021: 180 और 140; 2022: 210 और 175। किस वर्ष में व्यय के प्रतिशत के रूप में लाभ सबसे अधिक था?","optionsHi":["2020 और 2021 में समान","2020","2021","2022"],"explanationHi":"2020: 30/120 = 25%; 2021: 40/140 = 28.57%; 2022: 35/175 = 20%। 2021 सबसे अधिक है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-15","question":"Marks out of 100 in four subjects — Student A: 72, 84, 66, 78; Student B: 80, 75, 90, 63. Which statement about their average marks is correct?","options":["B’s average is higher by 2","A’s average is higher by 2","B’s average is higher by 8","Both averages are equal"],"answer":0,"explanation":"A: 300/4 = 75; B: 308/4 = 77. B’s average is 2 marks higher (8 is the difference in totals).","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"चार विषयों में 100 में से प्राप्तांक — विद्यार्थी A: 72, 84, 66, 78; विद्यार्थी B: 80, 75, 90, 63। उनके औसत अंकों के बारे में कौन-सा कथन सही है?","optionsHi":["B का औसत 2 अधिक है","A का औसत 2 अधिक है","B का औसत 8 अधिक है","दोनों औसत बराबर हैं"],"explanationHi":"A: 300/4 = 75; B: 308/4 = 77। B का औसत 2 अंक अधिक है (8 कुल योगों का अंतर है)।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-16","question":"Exports (₹ crore) — 2018: 250, 2019: 300, 2020: 270, 2021: 324. Exports in 2021 are what percent more than in 2019?","options":["8%","10%","29.6%","20%"],"answer":0,"explanation":"(324 − 300)/300 × 100 = 8%. The 20% figure is the rise over 2020, not 2019.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"निर्यात (₹ करोड़ में) — 2018: 250, 2019: 300, 2020: 270, 2021: 324। 2021 का निर्यात 2019 से कितने प्रतिशत अधिक है?","optionsHi":["8%","10%","29.6%","20%"],"explanationHi":"(324 − 300)/300 × 100 = 8%। 20% की वृद्धि 2020 की तुलना में है, 2019 की नहीं।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-17","question":"A company spends ₹2.4 crore: Salary 35%, Raw material 25%, Marketing 15%, Rent 10%, Others 15%. How much more is spent on salary than on marketing?","options":["₹24 lakh","₹48 lakh","₹60 lakh","₹36 lakh"],"answer":1,"explanation":"Difference = 35% − 15% = 20% of ₹2.4 crore = ₹0.48 crore = ₹48 lakh.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक कंपनी ₹2.4 करोड़ खर्च करती है: वेतन 35%, कच्चा माल 25%, विपणन 15%, किराया 10%, अन्य 15%। वेतन पर विपणन से कितना अधिक खर्च होता है?","optionsHi":["₹24 लाख","₹48 लाख","₹60 लाख","₹36 लाख"],"explanationHi":"अंतर = 35% − 15% = ₹2.4 करोड़ का 20% = ₹0.48 करोड़ = ₹48 लाख।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-18","question":"Students appeared and passed — School X: 400 and 320; School Y: 500 and 375; School Z: 250 and 210. Which school has the highest pass percentage?","options":["Y","X","Z","X and Z equally"],"answer":2,"explanation":"X: 80%; Y: 75%; Z: 210/250 = 84%. Z is highest although it has the fewest passes.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"परीक्षा में बैठे और उत्तीर्ण विद्यार्थी — विद्यालय X: 400 और 320; विद्यालय Y: 500 और 375; विद्यालय Z: 250 और 210। किस विद्यालय का उत्तीर्ण प्रतिशत सबसे अधिक है?","optionsHi":["Y","X","Z","X और Z समान रूप से"],"explanationHi":"X: 80%; Y: 75%; Z: 210/250 = 84%। Z सबसे अधिक है, यद्यपि उसके उत्तीर्ण विद्यार्थी सबसे कम हैं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-19","question":"Employees and male : female ratio — Department A: 120 employees, 3 : 1; Department B: 150, 2 : 3; Department C: 90, 4 : 5. What is the total number of female employees?","options":["170","190","160","180"],"answer":0,"explanation":"Females: A = 120 × 1/4 = 30; B = 150 × 3/5 = 90; C = 90 × 5/9 = 50. Total = 170.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"कर्मचारी और पुरुष : महिला अनुपात — विभाग A: 120 कर्मचारी, 3 : 1; विभाग B: 150, 2 : 3; विभाग C: 90, 4 : 5। कुल महिला कर्मचारियों की संख्या कितनी है?","optionsHi":["170","190","160","180"],"explanationHi":"महिलाएँ: A = 120 × 1/4 = 30; B = 150 × 3/5 = 90; C = 90 × 5/9 = 50। कुल = 170।","subtopic":"tables"},
  {"id":"quant-data-interpretation-20","question":"Monthly sales (units) — April: 240, May: 300, June: 270, July: 360. The average sales of May, June and July is what percent more than the April sales?","options":["33.33%","29.17%","30%","25%"],"answer":1,"explanation":"Average = (300 + 270 + 360)/3 = 310; (310 − 240)/240 × 100 = 70/240 × 100 = 29.17%.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"मासिक बिक्री (इकाइयाँ) — अप्रैल: 240, मई: 300, जून: 270, जुलाई: 360। मई, जून और जुलाई की औसत बिक्री अप्रैल की बिक्री से कितने प्रतिशत अधिक है?","optionsHi":["33.33%","29.17%","30%","25%"],"explanationHi":"औसत = (300 + 270 + 360)/3 = 310; (310 − 240)/240 × 100 = 70/240 × 100 = 29.17%।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-21","question":"Visitors to a museum (thousand) — 2019: 50, 2020: 20, 2021: 35, 2022: 56. By what percent did visitors in 2022 rise over 2020?","options":["60%","180%","12%","280%"],"answer":1,"explanation":"(56 − 20)/20 × 100 = 180%. 280% is 56 as a percent of 20, not the rise.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक संग्रहालय के आगंतुक (हज़ार में) — 2019: 50, 2020: 20, 2021: 35, 2022: 56। 2022 में आगंतुक 2020 की तुलना में कितने प्रतिशत बढ़े?","optionsHi":["60%","180%","12%","280%"],"explanationHi":"(56 − 20)/20 × 100 = 180%। 280% में 56 को 20 के प्रतिशत के रूप में लिया गया है, वृद्धि के रूप में नहीं।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-22","question":"Revenue (₹ crore) — 2020: A 45, B 60; 2021: A 54, B 72; 2022: A 63, B 70. What is the ratio of A’s total revenue to B’s total revenue over the three years?","options":["4 : 5","9 : 11","81 : 101","101 : 81"],"answer":2,"explanation":"A = 45 + 54 + 63 = 162; B = 60 + 72 + 70 = 202; 162 : 202 = 81 : 101.","difficulty":"hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"राजस्व (₹ करोड़ में) — 2020: A 45, B 60; 2021: A 54, B 72; 2022: A 63, B 70। तीन वर्षों में A के कुल राजस्व और B के कुल राजस्व का अनुपात कितना है?","optionsHi":["4 : 5","9 : 11","81 : 101","101 : 81"],"explanationHi":"A = 45 + 54 + 63 = 162; B = 60 + 72 + 70 = 202; 162 : 202 = 81 : 101।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-23","question":"Price (₹ per kg) — 2021: Rice 40, Wheat 30, Sugar 45; 2022: Rice 46, Wheat 33, Sugar 48. Which item had the highest percentage price increase?","options":["Wheat","Sugar","Rice","Rice and Wheat equally"],"answer":2,"explanation":"Rice 6/40 = 15%; Wheat 3/30 = 10%; Sugar 3/45 = 6.67%. Rice leads.","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"कीमत (₹ प्रति किग्रा) — 2021: चावल 40, गेहूँ 30, चीनी 45; 2022: चावल 46, गेहूँ 33, चीनी 48। किस वस्तु की कीमत में प्रतिशत वृद्धि सबसे अधिक रही?","optionsHi":["गेहूँ","चीनी","चावल","चावल और गेहूँ समान रूप से"],"explanationHi":"चावल 6/40 = 15%; गेहूँ 3/30 = 10%; चीनी 3/45 = 6.67%। चावल सबसे आगे है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-24","question":"In a class of 80 students, the percentage scoring above 60 is — Maths: 45%, Science: 60%, English: 35%. How many more students scored above 60 in Science than in English?","options":["25","20","12","28"],"answer":1,"explanation":"The gap is 60% − 35% = 25% of 80 = 20 students (25 is the percentage, not the count).","difficulty":"hard","source":"SSC CGL · SSC CHSL · IBPS Clerk","questionHi":"80 विद्यार्थियों की एक कक्षा में 60 से अधिक अंक पाने वालों का प्रतिशत है — गणित: 45%, विज्ञान: 60%, अंग्रेज़ी: 35%। विज्ञान में अंग्रेज़ी की तुलना में कितने अधिक विद्यार्थियों ने 60 से अधिक अंक पाए?","optionsHi":["25","20","12","28"],"explanationHi":"अंतर = 60% − 35% = 80 का 25% = 20 विद्यार्थी (25 प्रतिशत है, संख्या नहीं)।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-25","question":"Sales (₹ crore) and profit as a percentage of sales — 2019: 200, 10%; 2020: 250, 12%; 2021: 300, 9%; 2022: 320, 12.5%. In which year was the profit highest, and by what percent did it exceed the 2020 profit?","options":["2022; 33.33%","2022; 25%","2022; 30%","2020; 20%"],"answer":0,"explanation":"Profits: 20, 30, 27, 40 (₹ crore). 2022 is highest; (40 − 30)/30 × 100 = 33.33%. The highest margin is not the same as the highest profit: 2021 has the biggest sales but only 27.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"बिक्री (₹ करोड़ में) और बिक्री के प्रतिशत के रूप में लाभ — 2019: 200, 10%; 2020: 250, 12%; 2021: 300, 9%; 2022: 320, 12.5%। किस वर्ष में लाभ सबसे अधिक था, और वह 2020 के लाभ से कितने प्रतिशत अधिक था?","optionsHi":["2022; 33.33%","2022; 25%","2022; 30%","2020; 20%"],"explanationHi":"लाभ: 20, 30, 27, 40 (₹ करोड़)। 2022 सबसे अधिक है; (40 − 30)/30 × 100 = 33.33%। सर्वाधिक लाभ-प्रतिशत और सर्वाधिक लाभ एक नहीं हैं: 2021 में बिक्री सबसे अधिक है पर लाभ केवल 27।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-26","question":"Units sold — Monday: 120, Tuesday: 150, Wednesday: x, Thursday: 180, Friday: 140. The average for the five days is 150. Wednesday’s sales are what percent more than Monday’s?","options":["40%","33.33%","25%","30%"],"answer":1,"explanation":"Total = 5 × 150 = 750, so x = 750 − 590 = 160. (160 − 120)/120 × 100 = 33.33%.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"बेची गई इकाइयाँ — सोमवार: 120, मंगलवार: 150, बुधवार: x, गुरुवार: 180, शुक्रवार: 140। पाँच दिनों का औसत 150 है। बुधवार की बिक्री सोमवार की बिक्री से कितने प्रतिशत अधिक है?","optionsHi":["40%","33.33%","25%","30%"],"explanationHi":"कुल = 5 × 150 = 750, अतः x = 750 − 590 = 160। (160 − 120)/120 × 100 = 33.33%।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-27","question":"A ₹3,60,000 budget is shown in a pie chart — Food: 120°, Rent: 90°, Education: 60°, Savings: 54°, Others: 36°. Next year food spending rises by 10% and everything else stays the same. What is the new central angle for food, to the nearest degree?","options":["132°","126°","128°","130°"],"answer":2,"explanation":"Food = 120/360 × 3,60,000 = 1,20,000 → 1,32,000; new total = 3,72,000. Angle = 1,32,000/3,72,000 × 360 ≈ 127.7° ≈ 128°. 132° forgets that the total also grows.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"₹3,60,000 का एक बजट पाई चार्ट में दिखाया गया है — भोजन: 120°, किराया: 90°, शिक्षा: 60°, बचत: 54°, अन्य: 36°। अगले वर्ष भोजन पर खर्च 10% बढ़ जाता है और बाकी सब वही रहता है। भोजन का नया केंद्रीय कोण निकटतम अंश तक कितना होगा?","optionsHi":["132°","126°","128°","130°"],"explanationHi":"भोजन = 120/360 × 3,60,000 = 1,20,000 → 1,32,000; नया कुल = 3,72,000। कोण = 1,32,000/3,72,000 × 360 ≈ 127.7° ≈ 128°। 132° में यह भूल जाया गया है कि कुल भी बढ़ता है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-28","question":"Students and boys : girls ratio — College P: 1,200, 7 : 5; College Q: 1,500, 3 : 2; College R: 900, 4 : 5. What percent of all the girls are in College R?","options":["33.33%","37.5%","28.5%","31.25%"],"answer":3,"explanation":"Girls: P = 1,200 × 5/12 = 500; Q = 1,500 × 2/5 = 600; R = 900 × 5/9 = 500. Total 1,600, so R’s share = 500/1,600 = 31.25%.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"विद्यार्थी और लड़के : लड़कियाँ अनुपात — कॉलेज P: 1,200, 7 : 5; कॉलेज Q: 1,500, 3 : 2; कॉलेज R: 900, 4 : 5। सभी लड़कियों का कितना प्रतिशत कॉलेज R में है?","optionsHi":["33.33%","37.5%","28.5%","31.25%"],"explanationHi":"लड़कियाँ: P = 1,200 × 5/12 = 500; Q = 1,500 × 2/5 = 600; R = 900 × 5/9 = 500। कुल 1,600, अतः R का हिस्सा = 500/1,600 = 31.25%।","subtopic":"tables"},
  {"id":"quant-data-interpretation-29","question":"Wheat production (thousand tonnes), 2021 and 2022 — State A: 120, 138; B: 150, 165; C: 80, 100; D: 200, 210. What is the combined percentage increase of all four states from 2021 to 2022?","options":["10.25%","11.45%","13.75%","12.5%"],"answer":1,"explanation":"Totals: 550 → 613, a rise of 63; 63/550 × 100 ≈ 11.45%. 13.75% is the simple average of the four state rates (15, 10, 25, 5), which ignores their different sizes.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"गेहूँ का उत्पादन (हज़ार टन में), 2021 और 2022 — राज्य A: 120, 138; B: 150, 165; C: 80, 100; D: 200, 210। 2021 से 2022 तक चारों राज्यों की संयुक्त प्रतिशत वृद्धि कितनी है?","optionsHi":["10.25%","11.45%","13.75%","12.5%"],"explanationHi":"कुल: 550 → 613, यानी 63 की वृद्धि; 63/550 × 100 ≈ 11.45%। 13.75% चारों राज्यों की दरों (15, 10, 25, 5) का साधारण औसत है, जिसमें उनके अलग-अलग आकार की अनदेखी होती है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-30","question":"A shop’s sales (₹ thousand) — 2020: 80; 2021 was 25% more than 2020; 2022 was 20% less than 2021; 2023 was 50% more than 2022. What is the average annual sales over 2020–2023?","options":["₹92.5 thousand","₹90 thousand","₹95 thousand","₹100 thousand"],"answer":2,"explanation":"2021 = 100, 2022 = 80, 2023 = 120. Total = 80 + 100 + 80 + 120 = 380; average = 95.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक दुकान की बिक्री (₹ हज़ार में) — 2020: 80; 2021 में यह 2020 से 25% अधिक थी; 2022 में यह 2021 से 20% कम थी; 2023 में यह 2022 से 50% अधिक थी। 2020–2023 की औसत वार्षिक बिक्री कितनी है?","optionsHi":["₹92.5 हज़ार","₹90 हज़ार","₹95 हज़ार","₹100 हज़ार"],"explanationHi":"2021 = 100, 2022 = 80, 2023 = 120। कुल = 80 + 100 + 80 + 120 = 380; औसत = 95।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-31","question":"Marks out of 50 — Ravi: Maths 42, Science 38, English 35; Sita: 45, 32, 40; Arjun: 36, 44, 39. How many of these statements are true? I. Arjun has the highest total. II. Sita’s average is 39. III. The highest score in Science is 44. IV. Ravi’s overall percentage is more than 80%.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"Totals: Ravi 115, Sita 117, Arjun 119. I, II (117/3 = 39) and III are true. IV is false: 115/150 = 76.67%.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"50 में से प्राप्तांक — रवि: गणित 42, विज्ञान 38, अंग्रेज़ी 35; सीता: 45, 32, 40; अर्जुन: 36, 44, 39। इनमें से कितने कथन सत्य हैं? I. अर्जुन का कुल योग सबसे अधिक है। II. सीता का औसत 39 है। III. विज्ञान में सर्वाधिक अंक 44 हैं। IV. रवि का कुल प्रतिशत 80% से अधिक है।","optionsHi":["केवल एक","केवल दो","केवल तीन","सभी चारों"],"explanationHi":"योग: रवि 115, सीता 117, अर्जुन 119। I, II (117/3 = 39) और III सत्य हैं। IV असत्य है: 115/150 = 76.67%।","subtopic":"tables"},
  {"id":"quant-data-interpretation-32","question":"A company’s revenue grew from ₹400 crore in 2020 to ₹484 crore in 2022 at a constant annual percentage rate. What was its revenue in 2021?","options":["₹436 crore","₹444 crore","₹440 crore","₹442 crore"],"answer":2,"explanation":"484/400 = 1.21 = 1.1², so the rate is 10% a year and 2021 revenue = 400 × 1.1 = ₹440 crore. ₹442 crore is the simple midpoint.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक कंपनी का राजस्व एक स्थिर वार्षिक प्रतिशत दर से 2020 में ₹400 करोड़ से बढ़कर 2022 में ₹484 करोड़ हो गया। 2021 में उसका राजस्व कितना था?","optionsHi":["₹436 करोड़","₹444 करोड़","₹440 करोड़","₹442 करोड़"],"explanationHi":"484/400 = 1.21 = 1.1², अतः दर 10% प्रतिवर्ष है और 2021 का राजस्व = 400 × 1.1 = ₹440 करोड़। ₹442 करोड़ साधारण मध्य-बिंदु है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-33","question":"Exports and imports (₹ crore) — 2019: 300 and 360; 2020: 330 and 330; 2021: 390 and 325; 2022: 420 and 350. In how many years was the export-to-import ratio more than 1?","options":["3","2","1","4"],"answer":1,"explanation":"Ratios: 2019 = 0.83, 2020 = 1 (not more than 1), 2021 = 1.2, 2022 = 1.2. So 2 years.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"निर्यात और आयात (₹ करोड़ में) — 2019: 300 और 360; 2020: 330 और 330; 2021: 390 और 325; 2022: 420 और 350। कितने वर्षों में निर्यात-आयात अनुपात 1 से अधिक था?","optionsHi":["3","2","1","4"],"explanationHi":"अनुपात: 2019 = 0.83, 2020 = 1 (1 से अधिक नहीं), 2021 = 1.2, 2022 = 1.2। अतः 2 वर्ष।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-34","question":"Departments with (number of employees, average monthly salary in ₹ thousand) — A: (20, 30), B: (30, 25), C: (25, 40), D: (15, 36), E: (10, 45). What is the overall average salary of all employees?","options":["₹34,600","₹33,400","₹35,200","₹32,000"],"answer":1,"explanation":"Total salary = 600 + 750 + 1,000 + 540 + 450 = 3,340 thousand for 100 employees, giving ₹33,400. ₹35,200 is the unweighted mean of the five averages.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"विभाग और उनके (कर्मचारियों की संख्या, औसत मासिक वेतन ₹ हज़ार में) — A: (20, 30), B: (30, 25), C: (25, 40), D: (15, 36), E: (10, 45)। सभी कर्मचारियों का समग्र औसत वेतन कितना है?","optionsHi":["₹34,600","₹33,400","₹35,200","₹32,000"],"explanationHi":"कुल वेतन = 600 + 750 + 1,000 + 540 + 450 = 3,340 हज़ार, 100 कर्मचारियों के लिए, अर्थात् ₹33,400। ₹35,200 पाँचों औसतों का भारित न किया गया माध्य है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-35","question":"Favourite sport of 1,800 students — Cricket: 40%, Football: 20%, Hockey: 15%, Tennis: 10%, Others: 15%. By how many students do cricket fans outnumber hockey and tennis fans together?","options":["360","180","270","450"],"answer":2,"explanation":"Work in percentages first: 40% − (15% + 10%) = 15%, and 15% of 1,800 = 270. 450 is the hockey-plus-tennis group itself (25%), and 360 subtracts football's 20% instead.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"1,800 विद्यार्थियों का पसंदीदा खेल — क्रिकेट: 40%, फुटबॉल: 20%, हॉकी: 15%, टेनिस: 10%, अन्य: 15%। क्रिकेट पसंद करने वाले विद्यार्थी हॉकी और टेनिस पसंद करने वालों के कुल योग से कितने अधिक हैं?","optionsHi":["360","180","270","450"],"explanationHi":"पहले प्रतिशत में काम करें: 40% − (15% + 10%) = 15%, और 1,800 का 15% = 270। 450 स्वयं हॉकी और टेनिस वाला समूह (25%) है, और 360 में फुटबॉल का 20% घटा दिया गया है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-36","question":"Units sold — Shop A: January 120, February 150, March 180; Shop B: January 160, February 140, March 200. What is the ratio of A’s total to B’s total, and what percent of combined March sales came from A?","options":["9 : 10; 52.63%","10 : 9; 47.37%","9 : 10; 45%","9 : 10; 47.37%"],"answer":3,"explanation":"A = 450, B = 500, ratio 9 : 10. March combined = 380, so A’s share = 180/380 ≈ 47.37% (52.63% is B’s share).","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"बेची गई इकाइयाँ — दुकान A: जनवरी 120, फरवरी 150, मार्च 180; दुकान B: जनवरी 160, फरवरी 140, मार्च 200। A के कुल और B के कुल का अनुपात क्या है, और मार्च की संयुक्त बिक्री का कितना प्रतिशत A से आया?","optionsHi":["9 : 10; 52.63%","10 : 9; 47.37%","9 : 10; 45%","9 : 10; 47.37%"],"explanationHi":"A = 450, B = 500, अनुपात 9 : 10। मार्च की संयुक्त बिक्री = 380, अतः A का हिस्सा = 180/380 ≈ 47.37% (52.63% B का हिस्सा है)।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-37","question":"Literacy rate of a district — 2011: 60%, 2021: 72%; population — 2011: 5 lakh, 2021: 6 lakh. By what percent did the number of literate people increase?","options":["44%","32%","20%","12%"],"answer":0,"explanation":"Literates rose from 3 lakh to 4.32 lakh: 1.32/3 × 100 = 44%. 12 is the rise in percentage points and 20% the rise in the rate alone; both ignore population growth.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक जिले की साक्षरता दर — 2011: 60%, 2021: 72%; जनसंख्या — 2011: 5 लाख, 2021: 6 लाख। साक्षर लोगों की संख्या में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["44%","32%","20%","12%"],"explanationHi":"साक्षर लोग 3 लाख से बढ़कर 4.32 लाख हो गए: 1.32/3 × 100 = 44%। 12 प्रतिशत अंकों की वृद्धि है और 20% केवल दर की वृद्धि है; दोनों में जनसंख्या वृद्धि की अनदेखी हुई है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-38","question":"In 2022 the production of items A, B and C was in the ratio 3 : 4 : 5, totalling 2,400 units. In 2023 A rose by 20%, B fell by 10% and C rose by 10%. What was the total production in 2023?","options":["2,600","2,520","2,480","2,540"],"answer":3,"explanation":"2022: A = 600, B = 800, C = 1,000. 2023: 720 + 720 + 1,100 = 2,540.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"2022 में वस्तुओं A, B और C का उत्पादन 3 : 4 : 5 के अनुपात में था, जो कुल 2,400 इकाइयाँ था। 2023 में A में 20% की वृद्धि हुई, B में 10% की कमी हुई और C में 10% की वृद्धि हुई। 2023 में कुल उत्पादन कितना था?","optionsHi":["2,600","2,520","2,480","2,540"],"explanationHi":"2022: A = 600, B = 800, C = 1,000। 2023: 720 + 720 + 1,100 = 2,540।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-39","question":"Runs scored by a batsman in six matches — 45, 72, 38, x, 90, 55. His average is 60. In how many matches did he score more than his average?","options":["2","3","1","4"],"answer":0,"explanation":"Total = 6 × 60 = 360, so x = 360 − 300 = 60. Only 72 and 90 are above 60; x equals the average and does not count.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"एक बल्लेबाज़ द्वारा छह मैचों में बनाए गए रन — 45, 72, 38, x, 90, 55। उसका औसत 60 है। कितने मैचों में उसने अपने औसत से अधिक रन बनाए?","optionsHi":["2","3","1","4"],"explanationHi":"कुल = 6 × 60 = 360, अतः x = 360 − 300 = 60। केवल 72 और 90, 60 से ऊपर हैं; x औसत के बराबर है और गिना नहीं जाएगा।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-40","question":"Cost price and marked price (₹) — Item P: 400 and 560; Item Q: 600 and 750; Item R: 500 and 700. Each is sold at a 10% discount on its marked price. What is the overall profit percentage?","options":["20.6%","22%","18.5%","25%"],"answer":0,"explanation":"Selling prices: 504 + 675 + 630 = 1,809; total cost = 1,500. Profit = 309/1,500 × 100 = 20.6%.","difficulty":"very-hard","source":"IBPS PO · SBI PO · IBPS Clerk","questionHi":"क्रय मूल्य और अंकित मूल्य (₹) — वस्तु P: 400 और 560; वस्तु Q: 600 और 750; वस्तु R: 500 और 700। प्रत्येक को उसके अंकित मूल्य पर 10% छूट पर बेचा जाता है। समग्र लाभ प्रतिशत कितना है?","optionsHi":["20.6%","22%","18.5%","25%"],"explanationHi":"विक्रय मूल्य: 504 + 675 + 630 = 1,809; कुल क्रय मूल्य = 1,500। लाभ = 309/1,500 × 100 = 20.6%।","subtopic":"tables"},
  {"id":"quant-data-interpretation-41","question":"Revenue and expenditure (₹ crore) of a company — 2019: 250 and 200; 2020: 300 and 250; 2021: 280 and 245; 2022: 350 and 275; 2023: 420 and 350. In which year was the profit the lowest, and what was the profit as a percentage of revenue in that year?","options":["2020, 16.7%","2021, 14.3%","2021, 12.5%","2019, 20%"],"answer":2,"explanation":"Profits: 50, 50, 35, 75, 70, so the lowest is ₹35 crore in 2021, and 35/280 = 12.5% of revenue. 14.3% divides by expenditure (245) instead of revenue.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"एक कंपनी का राजस्व और व्यय (₹ करोड़ में) — 2019: 250 और 200; 2020: 300 और 250; 2021: 280 और 245; 2022: 350 और 275; 2023: 420 और 350। किस वर्ष में लाभ सबसे कम था, और उस वर्ष लाभ राजस्व का कितना प्रतिशत था?","optionsHi":["2020, 16.7%","2021, 14.3%","2021, 12.5%","2019, 20%"],"explanationHi":"लाभ: 50, 50, 35, 75, 70, अतः सबसे कम 2021 में ₹35 करोड़ है, और 35/280 = राजस्व का 12.5%। 14.3% में राजस्व की जगह व्यय (245) से भाग दिया गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-42","question":"Revenue and expenditure (₹ crore) of a company — 2019: 250 and 200; 2020: 300 and 250; 2021: 280 and 245; 2022: 350 and 275; 2023: 420 and 350. The total profit over the five years is what percent of the total revenue?","options":["15%","17.5%","21.2%","20%"],"answer":1,"explanation":"Total profit = 50 + 50 + 35 + 75 + 70 = ₹280 crore; total revenue = ₹1,600 crore; 280/1,600 = 17.5%. 21.2% divides by total expenditure (₹1,320 crore).","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक कंपनी का राजस्व और व्यय (₹ करोड़ में) — 2019: 250 और 200; 2020: 300 और 250; 2021: 280 और 245; 2022: 350 और 275; 2023: 420 और 350। पाँच वर्षों का कुल लाभ कुल राजस्व का कितना प्रतिशत है?","optionsHi":["15%","17.5%","21.2%","20%"],"explanationHi":"कुल लाभ = 50 + 50 + 35 + 75 + 70 = ₹280 करोड़; कुल राजस्व = ₹1,600 करोड़; 280/1,600 = 17.5%। 21.2% में कुल व्यय (₹1,320 करोड़) से भाग दिया गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-43","question":"Revenue and expenditure (₹ crore) of a company — 2019: 250 and 200; 2020: 300 and 250; 2021: 280 and 245; 2022: 350 and 275; 2023: 420 and 350. In how many of the years 2020–2023 did revenue grow by a higher percentage over the previous year than expenditure did?","options":["None","Three","Only one","Two"],"answer":2,"explanation":"2020: revenue +20%, expenditure +25%. 2021: −6.7% vs −2%. 2022: +25% vs +12.2%. 2023: +20% vs +27.3%. Only 2022 qualifies.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक कंपनी का राजस्व और व्यय (₹ करोड़ में) — 2019: 250 और 200; 2020: 300 और 250; 2021: 280 और 245; 2022: 350 और 275; 2023: 420 और 350। वर्ष 2020–2023 में से कितने वर्षों में राजस्व में पिछले वर्ष की तुलना में प्रतिशत वृद्धि व्यय की प्रतिशत वृद्धि से अधिक रही?","optionsHi":["एक भी नहीं","तीन","केवल एक","दो"],"explanationHi":"2020: राजस्व +20%, व्यय +25%। 2021: −6.7% बनाम −2%। 2022: +25% बनाम +12.2%। 2023: +20% बनाम +27.3%। केवल 2022 इस शर्त को पूरा करता है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-44","question":"Revenue and expenditure (₹ crore) of a company — 2019: 250 and 200; 2020: 300 and 250; 2021: 280 and 245; 2022: 350 and 275; 2023: 420 and 350. If revenue in 2024 grows by the same percentage as it did in 2023, and profit as a fraction of revenue stays at its 2023 level, what will the 2024 profit be?","options":["₹90 crore","₹80.5 crore","₹84 crore","₹70 crore"],"answer":2,"explanation":"2023 growth = 420/350 = 1.2, so 2024 revenue = ₹504 crore. 2023 margin = 70/420 = 1/6, so 2024 profit = 504/6 = ₹84 crore.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक कंपनी का राजस्व और व्यय (₹ करोड़ में) — 2019: 250 और 200; 2020: 300 और 250; 2021: 280 और 245; 2022: 350 और 275; 2023: 420 और 350। यदि 2024 में राजस्व उतने ही प्रतिशत से बढ़ता है जितना 2023 में बढ़ा था, और राजस्व के अंश के रूप में लाभ 2023 के स्तर पर रहता है, तो 2024 का लाभ कितना होगा?","optionsHi":["₹90 करोड़","₹80.5 करोड़","₹84 करोड़","₹70 करोड़"],"explanationHi":"2023 की वृद्धि = 420/350 = 1.2, अतः 2024 का राजस्व = ₹504 करोड़। 2023 का लाभ-अंश = 70/420 = 1/6, अतः 2024 का लाभ = 504/6 = ₹84 करोड़।","subtopic":"tables"},
  {"id":"quant-data-interpretation-45","question":"Students in five colleges and the percentage of them who are female — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%. How many female students are there in college R?","options":["576","540","500","960"],"answer":1,"explanation":"Females in R = 36% of 1,500 = 540. 960 is the 64% who are male, and 576 wrongly applies 36% to 1,600.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"पाँच कॉलेजों में विद्यार्थी और उनमें महिलाओं का प्रतिशत — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%। कॉलेज R में कितनी महिला विद्यार्थी हैं?","optionsHi":["576","540","500","960"],"explanationHi":"R में महिलाएँ = 1,500 का 36% = 540। 960 पुरुषों का 64% है, और 576 में गलती से 36% को 1,600 पर लगाया गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-46","question":"Students in five colleges and the percentage of them who are female — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%. What is the ratio of male students in P to male students in S?","options":["18 : 11","12 : 11","3 : 2","11 : 18"],"answer":0,"explanation":"Males in P = 60% of 1,200 = 720; in S = 55% of 800 = 440. 720 : 440 = 18 : 11. 3 : 2 compares total strengths.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"पाँच कॉलेजों में विद्यार्थी और उनमें महिलाओं का प्रतिशत — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%। P के पुरुष विद्यार्थियों और S के पुरुष विद्यार्थियों का अनुपात कितना है?","optionsHi":["18 : 11","12 : 11","3 : 2","11 : 18"],"explanationHi":"P में पुरुष = 1,200 का 60% = 720; S में = 800 का 55% = 440। 720 : 440 = 18 : 11। 3 : 2 कुल संख्याओं की तुलना है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-47","question":"Students in five colleges and the percentage of them who are female — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%. Female students of all five colleges together form approximately what percent of all the students?","options":["47.2%","48.5%","45.0%","46.1%"],"answer":3,"explanation":"Females = 480 + 495 + 540 + 360 + 660 = 2,535 out of 5,500 = 46.1%. The simple average of the five percentages (47.2%) ignores the different college sizes.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"पाँच कॉलेजों में विद्यार्थी और उनमें महिलाओं का प्रतिशत — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%। पाँचों कॉलेजों की महिला विद्यार्थी मिलकर सभी विद्यार्थियों का लगभग कितना प्रतिशत हैं?","optionsHi":["47.2%","48.5%","45.0%","46.1%"],"explanationHi":"महिलाएँ = 480 + 495 + 540 + 360 + 660 = 2,535, कुल 5,500 में से = 46.1%। पाँचों प्रतिशतों का साधारण औसत (47.2%) कॉलेजों के अलग-अलग आकार की अनदेखी करता है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-48","question":"Students in five colleges and the percentage of them who are female — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%. In how many colleges is the number of male students more than the average number of male students per college?","options":["Two","Four","Three","One"],"answer":0,"explanation":"Males: P 720, Q 405, R 960, S 440, T 440; total 2,965, average 593. Only P and R exceed it.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"पाँच कॉलेजों में विद्यार्थी और उनमें महिलाओं का प्रतिशत — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%। कितने कॉलेजों में पुरुष विद्यार्थियों की संख्या प्रति कॉलेज पुरुष विद्यार्थियों के औसत से अधिक है?","optionsHi":["दो","चार","तीन","एक"],"explanationHi":"पुरुष: P 720, Q 405, R 960, S 440, T 440; कुल 2,965, औसत 593। केवल P और R इससे अधिक हैं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-49","question":"Students in five colleges and the percentage of them who are female — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%. By approximately what percent does the total number of male students exceed the total number of female students?","options":["14.5%","8.6%","17%","15%"],"answer":2,"explanation":"Males = 2,965 and females = 2,535; the excess 430 is 430/2,535 ≈ 17% of the females. 14.5% divides by the males instead.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"पाँच कॉलेजों में विद्यार्थी और उनमें महिलाओं का प्रतिशत — P: 1,200, 40%; Q: 900, 55%; R: 1,500, 36%; S: 800, 45%; T: 1,100, 60%। पुरुष विद्यार्थियों की कुल संख्या महिला विद्यार्थियों की कुल संख्या से लगभग कितने प्रतिशत अधिक है?","optionsHi":["14.5%","8.6%","17%","15%"],"explanationHi":"पुरुष = 2,965 और महिलाएँ = 2,535; अधिकता 430 है, जो महिलाओं का 430/2,535 ≈ 17% है। 14.5% में पुरुषों की संख्या से भाग दिया गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-50","question":"Production (units) of three items — Item X: January 120, February 150, March 135, April 180; Item Y: 200, 180, 220, 240; Item Z: 80, 100, 90, 110. What was the total production in March?","options":["430","455","530","445"],"answer":3,"explanation":"March is the third figure in each row: 135 + 220 + 90 = 445 units. 430 and 455 come from reading one item's February or April figure by mistake.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"तीन वस्तुओं का उत्पादन (इकाइयाँ) — वस्तु X: जनवरी 120, फरवरी 150, मार्च 135, अप्रैल 180; वस्तु Y: 200, 180, 220, 240; वस्तु Z: 80, 100, 90, 110। मार्च में कुल उत्पादन कितना था?","optionsHi":["430","455","530","445"],"explanationHi":"मार्च प्रत्येक पंक्ति में तीसरा आँकड़ा है: 135 + 220 + 90 = 445 इकाइयाँ। 430 और 455 किसी वस्तु का फरवरी या अप्रैल का आँकड़ा गलती से पढ़ लेने पर आते हैं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-51","question":"Production (units) of three items — Item X: January 120, February 150, March 135, April 180; Item Y: 200, 180, 220, 240; Item Z: 80, 100, 90, 110. By what percent did the production of Y increase from February to April?","options":["25%","33 1/3%","20%","60%"],"answer":1,"explanation":"Increase = 240 − 180 = 60 on 180, i.e. 33 1/3%. 25% divides by the April figure.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"तीन वस्तुओं का उत्पादन (इकाइयाँ) — वस्तु X: जनवरी 120, फरवरी 150, मार्च 135, अप्रैल 180; वस्तु Y: 200, 180, 220, 240; वस्तु Z: 80, 100, 90, 110। फरवरी से अप्रैल तक Y के उत्पादन में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["25%","33 1/3%","20%","60%"],"explanationHi":"वृद्धि = 240 − 180 = 60, 180 पर, अर्थात् 33 1/3%। 25% में अप्रैल के आँकड़े से भाग दिया गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-52","question":"Production (units) of three items — Item X: January 120, February 150, March 135, April 180; Item Y: 200, 180, 220, 240; Item Z: 80, 100, 90, 110. In which month was the share of item Y in that month's total production the highest?","options":["February","April","January","March"],"answer":2,"explanation":"Y's share: January 200/400 = 50%; February 180/430 ≈ 41.9%; March 220/445 ≈ 49.4%; April 240/530 ≈ 45.3%. April has the largest Y output but not the largest share.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"तीन वस्तुओं का उत्पादन (इकाइयाँ) — वस्तु X: जनवरी 120, फरवरी 150, मार्च 135, अप्रैल 180; वस्तु Y: 200, 180, 220, 240; वस्तु Z: 80, 100, 90, 110। किस महीने में उस महीने के कुल उत्पादन में वस्तु Y का हिस्सा सबसे अधिक था?","optionsHi":["फरवरी","अप्रैल","जनवरी","मार्च"],"explanationHi":"Y का हिस्सा: जनवरी 200/400 = 50%; फरवरी 180/430 ≈ 41.9%; मार्च 220/445 ≈ 49.4%; अप्रैल 240/530 ≈ 45.3%। अप्रैल में Y का उत्पादन सबसे अधिक है, पर हिस्सा सबसे अधिक नहीं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-53","question":"Production (units) of three items — Item X: January 120, February 150, March 135, April 180; Item Y: 200, 180, 220, 240; Item Z: 80, 100, 90, 110. Each unit of X sells for ₹50, of Y for ₹30 and of Z for ₹80. In which month was the sales revenue the highest, and how much was it?","options":["April, ₹25,000","March, ₹20,550","February, ₹20,900","April, ₹24,000"],"answer":0,"explanation":"Revenue: January 6,000 + 6,000 + 6,400 = ₹18,400; February ₹20,900; March ₹20,550; April 9,000 + 7,200 + 8,800 = ₹25,000.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"तीन वस्तुओं का उत्पादन (इकाइयाँ) — वस्तु X: जनवरी 120, फरवरी 150, मार्च 135, अप्रैल 180; वस्तु Y: 200, 180, 220, 240; वस्तु Z: 80, 100, 90, 110। X की प्रत्येक इकाई ₹50 में, Y की ₹30 में और Z की ₹80 में बिकती है। किस महीने में बिक्री राजस्व सबसे अधिक था, और कितना था?","optionsHi":["अप्रैल, ₹25,000","मार्च, ₹20,550","फरवरी, ₹20,900","अप्रैल, ₹24,000"],"explanationHi":"राजस्व: जनवरी 6,000 + 6,000 + 6,400 = ₹18,400; फरवरी ₹20,900; मार्च ₹20,550; अप्रैल 9,000 + 7,200 + 8,800 = ₹25,000।","subtopic":"tables"},
  {"id":"quant-data-interpretation-54","question":"The use of a family's monthly income of ₹60,000 is shown in a pie chart — Rent 25%, Food 30%, Education 15%, Transport 10%, Savings 12%, Others 8%. What is the central angle of the Food sector?","options":["90°","120°","100°","108°"],"answer":3,"explanation":"Each 1% of a pie is 3.6°, so Food's 30% = 108°. 90° is Rent's 25% sector, and 120° treats 30% as one-third of the circle.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"एक परिवार की ₹60,000 की मासिक आय का उपयोग पाई चार्ट में दिखाया गया है — किराया 25%, भोजन 30%, शिक्षा 15%, परिवहन 10%, बचत 12%, अन्य 8%। भोजन वाले खंड का केंद्रीय कोण कितना है?","optionsHi":["90°","120°","100°","108°"],"explanationHi":"पाई के प्रत्येक 1% का कोण 3.6° होता है, अतः भोजन का 30% = 108°। 90° किराये के 25% वाले खंड का है, और 120° में 30% को वृत्त का एक-तिहाई मान लिया गया है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-55","question":"The use of a family's monthly income of ₹60,000 is shown in a pie chart — Rent 25%, Food 30%, Education 15%, Transport 10%, Savings 12%, Others 8%. How much more is spent on rent than on transport each month?","options":["₹9,000","₹15,000","₹10,000","₹6,000"],"answer":0,"explanation":"The difference is 25% − 10% = 15% of ₹60,000 = ₹9,000. ₹15,000 is the rent itself.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"एक परिवार की ₹60,000 की मासिक आय का उपयोग पाई चार्ट में दिखाया गया है — किराया 25%, भोजन 30%, शिक्षा 15%, परिवहन 10%, बचत 12%, अन्य 8%। प्रत्येक माह किराये पर परिवहन से कितना अधिक खर्च होता है?","optionsHi":["₹9,000","₹15,000","₹10,000","₹6,000"],"explanationHi":"अंतर = 25% − 10% = ₹60,000 का 15% = ₹9,000। ₹15,000 स्वयं किराया है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-56","question":"The use of a family's monthly income of ₹60,000 is shown in a pie chart — Rent 25%, Food 30%, Education 15%, Transport 10%, Savings 12%, Others 8%. What is the ratio of savings to spending on food?","options":["3 : 5","5 : 2","2 : 3","2 : 5"],"answer":3,"explanation":"Savings : Food = 12% : 30% = 2 : 5; the income figure is not needed. 5 : 2 reverses the order asked, and 2 : 3 or 3 : 5 come from wrong cancelling.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"एक परिवार की ₹60,000 की मासिक आय का उपयोग पाई चार्ट में दिखाया गया है — किराया 25%, भोजन 30%, शिक्षा 15%, परिवहन 10%, बचत 12%, अन्य 8%। बचत और भोजन पर खर्च का अनुपात कितना है?","optionsHi":["3 : 5","5 : 2","2 : 3","2 : 5"],"explanationHi":"बचत : भोजन = 12% : 30% = 2 : 5; आय की राशि की आवश्यकता नहीं है। 5 : 2 पूछे गए क्रम को उलट देता है, और 2 : 3 या 3 : 5 गलत कटौती से आते हैं।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-57","question":"The use of a family's monthly income of ₹60,000 is shown in a pie chart — Rent 25%, Food 30%, Education 15%, Transport 10%, Savings 12%, Others 8%. What is the combined central angle of the Education and Transport sectors?","options":["100°","36°","54°","90°"],"answer":3,"explanation":"Education + Transport = 15% + 10% = 25% of 360° = 90°. 54° is Education alone and 36° is Transport alone.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक परिवार की ₹60,000 की मासिक आय का उपयोग पाई चार्ट में दिखाया गया है — किराया 25%, भोजन 30%, शिक्षा 15%, परिवहन 10%, बचत 12%, अन्य 8%। शिक्षा और परिवहन खंडों का संयुक्त केंद्रीय कोण कितना है?","optionsHi":["100°","36°","54°","90°"],"explanationHi":"शिक्षा + परिवहन = 15% + 10% = 360° का 25% = 90°। 54° केवल शिक्षा का है और 36° केवल परिवहन का।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-58","question":"The use of a family's monthly income of ₹60,000 is shown in a pie chart — Rent 25%, Food 30%, Education 15%, Transport 10%, Savings 12%, Others 8%. Next month the income rises by 20%, while the rupee amounts of all the other heads stay the same. Savings then become what percent of the new income?","options":["24%","32%","14.4%","26 2/3%"],"answer":3,"explanation":"Spending on the other heads = 88% of 60,000 = ₹52,800. New income = ₹72,000, so savings = ₹19,200 = 19,200/72,000 = 26 2/3%. Adding 20 points to 12% (32%) ignores the new base.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक परिवार की ₹60,000 की मासिक आय का उपयोग पाई चार्ट में दिखाया गया है — किराया 25%, भोजन 30%, शिक्षा 15%, परिवहन 10%, बचत 12%, अन्य 8%। अगले महीने आय 20% बढ़ जाती है, जबकि अन्य सभी मदों की रुपये में राशि वही रहती है। तब बचत नई आय का कितना प्रतिशत होगी?","optionsHi":["24%","32%","14.4%","26 2/3%"],"explanationHi":"अन्य मदों पर खर्च = 60,000 का 88% = ₹52,800। नई आय = ₹72,000, अतः बचत = ₹19,200 = 19,200/72,000 = 26 2/3%। 12% में 20 अंक जोड़ना (32%) नए आधार की अनदेखी करता है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-59","question":"Cars sold by two dealers — Dealer A: January 140, February 160, March 120, April 180, May 200; Dealer B: 150, 130, 170, 160, 190. How many cars did Dealer A sell in the five months together?","options":["800","780","760","820"],"answer":0,"explanation":"Dealer A's row: 140 + 160 + 120 + 180 + 200 = 800. 780, 760 and 820 are addition slips or a figure read from Dealer B's row.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"दो डीलरों द्वारा बेची गई कारें — डीलर A: जनवरी 140, फरवरी 160, मार्च 120, अप्रैल 180, मई 200; डीलर B: 150, 130, 170, 160, 190। डीलर A ने पाँच महीनों में कुल कितनी कारें बेचीं?","optionsHi":["800","780","760","820"],"explanationHi":"डीलर A की पंक्ति: 140 + 160 + 120 + 180 + 200 = 800। 780, 760 और 820 जोड़ने की चूक हैं या डीलर B की पंक्ति से कोई आँकड़ा लेने पर आते हैं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-60","question":"Cars sold by two dealers — Dealer A: January 140, February 160, March 120, April 150, May 180; Dealer B: 150, 130, 170, 160, 190. In how many months did Dealer A sell more cars than Dealer B?","options":["Three","Four","Two","One"],"answer":3,"explanation":"Dealer A sold more than Dealer B only in February (160 > 130). In January (140 < 150), March (120 < 170), April (150 < 160) and May (180 < 190) Dealer B sold more.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"दो डीलरों द्वारा बेची गई कारें — डीलर A: जनवरी 140, फरवरी 160, मार्च 120, अप्रैल 150, मई 180; डीलर B: 150, 130, 170, 160, 190। कितने महीनों में डीलर A ने डीलर B से अधिक कारें बेचीं?","optionsHi":["तीन","चार","दो","एक"],"explanationHi":"डीलर A ने डीलर B से अधिक केवल फरवरी में बेचीं (160 > 130)। जनवरी (140 < 150), मार्च (120 < 170), अप्रैल (150 < 160) और मई (180 < 190) में डीलर B ने अधिक बेचीं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-61","question":"Cars sold by two dealers — Dealer A: January 140, February 160, March 120, April 180, May 200; Dealer B: 150, 130, 170, 160, 190. In which month did Dealer B record the highest percentage increase in sales over the previous month?","options":["May","March","February","April"],"answer":1,"explanation":"B: February fell, March 130 → 170 (+30.8%), April fell, May 160 → 190 (+18.75%). May has the largest sales but a smaller rise.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"दो डीलरों द्वारा बेची गई कारें — डीलर A: जनवरी 140, फरवरी 160, मार्च 120, अप्रैल 180, मई 200; डीलर B: 150, 130, 170, 160, 190। किस महीने में डीलर B की बिक्री में पिछले महीने की तुलना में प्रतिशत वृद्धि सबसे अधिक रही?","optionsHi":["मई","मार्च","फरवरी","अप्रैल"],"explanationHi":"B: फरवरी में गिरावट, मार्च 130 → 170 (+30.8%), अप्रैल में गिरावट, मई 160 → 190 (+18.75%)। मई में बिक्री सबसे अधिक है पर वृद्धि कम है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-62","question":"Cars sold by two dealers — Dealer A: January 140, February 160, March 120, April 180, May 200; Dealer B: 150, 130, 170, 160, 190. How many of these statements are true? I. The two dealers sold the same number of cars in total. II. Dealer B's sales were lowest in January. III. Dealer A's sales rose every month. IV. Their combined sales were highest in May.","options":["Only one","All four","Only two","Only three"],"answer":2,"explanation":"I: both total 800, true. II: false, B's lowest month is February (130), not January (150). III: A fell from 160 to 120 in March, false. IV: May's combined 390 is the highest, true. So two are true.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"दो डीलरों द्वारा बेची गई कारें — डीलर A: जनवरी 140, फरवरी 160, मार्च 120, अप्रैल 180, मई 200; डीलर B: 150, 130, 170, 160, 190। इनमें से कितने कथन सत्य हैं? I. दोनों डीलरों ने कुल मिलाकर समान संख्या में कारें बेचीं। II. डीलर B की बिक्री जनवरी में सबसे कम थी। III. डीलर A की बिक्री हर महीने बढ़ी। IV. उनकी संयुक्त बिक्री मई में सबसे अधिक थी।","optionsHi":["केवल एक","सभी चारों","केवल दो","केवल तीन"],"explanationHi":"I: दोनों का कुल 800 है, सत्य। II: असत्य, B का सबसे कम महीना फरवरी (130) है, जनवरी (150) नहीं। III: मार्च में A की बिक्री 160 से गिरकर 120 हो गई, असत्य। IV: मई की संयुक्त बिक्री 390 सबसे अधिक है, सत्य। अतः दो सत्य हैं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-63","question":"Cars sold by two dealers — Dealer A: January 140, February 160, March 120, April 180, May 200; Dealer B: 150, 130, 170, 160, 190. Considering only the months in which Dealer A outsold Dealer B, what was the average combined monthly sales of the two dealers?","options":["360","330","340","320"],"answer":2,"explanation":"Those months are February (290), April (340) and May (390); average = 1,020/3 = 340.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"दो डीलरों द्वारा बेची गई कारें — डीलर A: जनवरी 140, फरवरी 160, मार्च 120, अप्रैल 180, मई 200; डीलर B: 150, 130, 170, 160, 190। केवल उन महीनों को लेते हुए जिनमें डीलर A ने डीलर B से अधिक बेचीं, दोनों डीलरों की औसत संयुक्त मासिक बिक्री कितनी थी?","optionsHi":["360","330","340","320"],"explanationHi":"वे महीने फरवरी (290), अप्रैल (340) और मई (390) हैं; औसत = 1,020/3 = 340।","subtopic":"tables"},
  {"id":"quant-data-interpretation-64","question":"Mode of commute of 2,400 employees, with the percentage of each group that is female — Car 25% (30% female), Metro 35% (50% female), Bus 20% (40% female), Two-wheeler 15% (20% female), Walk 5% (60% female). How many female employees commute by metro?","options":["350","420","840","480"],"answer":1,"explanation":"Metro users = 35% of 2,400 = 840, and 50% of them are female: 420. 840 forgets the female share, and 480 uses 20% instead of 35%.","difficulty":"moderate","source":"RRB NTPC · SSC CGL","questionHi":"2,400 कर्मचारियों के आने-जाने का साधन, और प्रत्येक समूह में महिलाओं का प्रतिशत — कार 25% (30% महिलाएँ), मेट्रो 35% (50% महिलाएँ), बस 20% (40% महिलाएँ), दोपहिया 15% (20% महिलाएँ), पैदल 5% (60% महिलाएँ)। कितनी महिला कर्मचारी मेट्रो से आती-जाती हैं?","optionsHi":["350","420","840","480"],"explanationHi":"मेट्रो उपयोगकर्ता = 2,400 का 35% = 840, और उनमें 50% महिलाएँ हैं: 420। 840 में महिलाओं का हिस्सा भूल गया है, और 480 में 35% की जगह 20% लिया गया है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-65","question":"Mode of commute of 2,400 employees, with the percentage of each group that is female — Car 25% (30% female), Metro 35% (50% female), Bus 20% (40% female), Two-wheeler 15% (20% female), Walk 5% (60% female). What percent of all the employees are female?","options":["40%","36%","39%","42%"],"answer":2,"explanation":"Females = 180 + 420 + 192 + 72 + 72 = 936, and 936/2,400 = 39%. Averaging the five female percentages (40%) ignores the group sizes.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"2,400 कर्मचारियों के आने-जाने का साधन, और प्रत्येक समूह में महिलाओं का प्रतिशत — कार 25% (30% महिलाएँ), मेट्रो 35% (50% महिलाएँ), बस 20% (40% महिलाएँ), दोपहिया 15% (20% महिलाएँ), पैदल 5% (60% महिलाएँ)। सभी कर्मचारियों का कितना प्रतिशत महिलाएँ हैं?","optionsHi":["40%","36%","39%","42%"],"explanationHi":"महिलाएँ = 180 + 420 + 192 + 72 + 72 = 936, और 936/2,400 = 39%। पाँचों महिला प्रतिशतों का औसत (40%) समूहों के आकार की अनदेखी करता है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-66","question":"Mode of commute of 2,400 employees, with the percentage of each group that is female — Car 25% (30% female), Metro 35% (50% female), Bus 20% (40% female), Two-wheeler 15% (20% female), Walk 5% (60% female). What is the ratio of male bus users to female two-wheeler users?","options":["4 : 1","8 : 3","3 : 1","2 : 1"],"answer":0,"explanation":"Male bus users = 60% of 480 = 288; female two-wheeler users = 20% of 360 = 72. 288 : 72 = 4 : 1.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"2,400 कर्मचारियों के आने-जाने का साधन, और प्रत्येक समूह में महिलाओं का प्रतिशत — कार 25% (30% महिलाएँ), मेट्रो 35% (50% महिलाएँ), बस 20% (40% महिलाएँ), दोपहिया 15% (20% महिलाएँ), पैदल 5% (60% महिलाएँ)। पुरुष बस उपयोगकर्ताओं और महिला दोपहिया उपयोगकर्ताओं का अनुपात कितना है?","optionsHi":["4 : 1","8 : 3","3 : 1","2 : 1"],"explanationHi":"पुरुष बस उपयोगकर्ता = 480 का 60% = 288; महिला दोपहिया उपयोगकर्ता = 360 का 20% = 72। 288 : 72 = 4 : 1।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-67","question":"Mode of commute of 2,400 employees, with the percentage of each group that is female — Car 25% (30% female), Metro 35% (50% female), Bus 20% (40% female), Two-wheeler 15% (20% female), Walk 5% (60% female). By what percent do male metro users outnumber male car users?","options":["They outnumber them by 66.7%","They are equal in number","They outnumber them by 16.7%","They outnumber them by 40%"],"answer":1,"explanation":"Male metro users = 50% of 840 = 420; male car users = 70% of 600 = 420. The groups are equal, although metro users as a whole are 40% more than car users.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"2,400 कर्मचारियों के आने-जाने का साधन, और प्रत्येक समूह में महिलाओं का प्रतिशत — कार 25% (30% महिलाएँ), मेट्रो 35% (50% महिलाएँ), बस 20% (40% महिलाएँ), दोपहिया 15% (20% महिलाएँ), पैदल 5% (60% महिलाएँ)। पुरुष मेट्रो उपयोगकर्ता पुरुष कार उपयोगकर्ताओं से कितने प्रतिशत अधिक हैं?","optionsHi":["वे उनसे 66.7% अधिक हैं","वे संख्या में बराबर हैं","वे उनसे 16.7% अधिक हैं","वे उनसे 40% अधिक हैं"],"explanationHi":"पुरुष मेट्रो उपयोगकर्ता = 840 का 50% = 420; पुरुष कार उपयोगकर्ता = 600 का 70% = 420। दोनों समूह बराबर हैं, यद्यपि कुल मिलाकर मेट्रो उपयोगकर्ता कार उपयोगकर्ताओं से 40% अधिक हैं।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-68","question":"Mode of commute of 2,400 employees, with the percentage of each group that is female — Car 25% (30% female), Metro 35% (50% female), Bus 20% (40% female), Two-wheeler 15% (20% female), Walk 5% (60% female). If one-fourth of the car users switch to the metro, what percent of all employees will then use the metro?","options":["41.0%","43.75%","41.25%","60%"],"answer":2,"explanation":"A quarter of 600 = 150 switch, so metro users become 840 + 150 = 990, i.e. 990/2,400 = 41.25%. 60% wrongly moves all the car users.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"2,400 कर्मचारियों के आने-जाने का साधन, और प्रत्येक समूह में महिलाओं का प्रतिशत — कार 25% (30% महिलाएँ), मेट्रो 35% (50% महिलाएँ), बस 20% (40% महिलाएँ), दोपहिया 15% (20% महिलाएँ), पैदल 5% (60% महिलाएँ)। यदि कार उपयोगकर्ताओं का एक-चौथाई हिस्सा मेट्रो पर चला जाए, तो तब सभी कर्मचारियों का कितना प्रतिशत मेट्रो का उपयोग करेगा?","optionsHi":["41.0%","43.75%","41.25%","60%"],"explanationHi":"600 का एक-चौथाई = 150 बदलते हैं, अतः मेट्रो उपयोगकर्ता 840 + 150 = 990 हो जाते हैं, यानी 990/2,400 = 41.25%। 60% में गलती से सभी कार उपयोगकर्ताओं को स्थानांतरित कर दिया गया है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-69","question":"A shop sold 1,200 phones of three brands X, Y and Z in a year. Brand X accounted for 40% of the phones, and Brand Y sold 50 more phones than Brand Z. How many Brand Y phones were sold?","options":["410","385","335","360"],"answer":1,"explanation":"X = 480, so Y + Z = 720 and Y − Z = 50, giving Y = 385 and Z = 335.","difficulty":"hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक दुकान ने एक वर्ष में तीन ब्रांड X, Y और Z के 1,200 फोन बेचे। कुल फोनों में ब्रांड X का हिस्सा 40% था, और ब्रांड Y ने ब्रांड Z से 50 फोन अधिक बेचे। ब्रांड Y के कितने फोन बिके?","optionsHi":["410","385","335","360"],"explanationHi":"X = 480, अतः Y + Z = 720 और Y − Z = 50, जिससे Y = 385 और Z = 335।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-70","question":"A shop sold 1,200 phones of three brands X, Y and Z in a year. Brand X accounted for 40% of the phones, and Brand Y sold 50 more phones than Brand Z. The average selling prices are ₹15,000 for X, ₹12,000 for Y and ₹18,000 for Z. Brand Z's revenue is what percent of Brand X's revenue?","options":["120%","69.8%","93.75%","83.75%"],"answer":3,"explanation":"X: 480 × 15,000 = ₹72 lakh; Z: 335 × 18,000 = ₹60.3 lakh. 60.3/72 = 83.75%. Comparing prices alone (18/15 = 120%) ignores the number sold.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक दुकान ने एक वर्ष में तीन ब्रांड X, Y और Z के 1,200 फोन बेचे। कुल फोनों में ब्रांड X का हिस्सा 40% था, और ब्रांड Y ने ब्रांड Z से 50 फोन अधिक बेचे। औसत विक्रय मूल्य X के लिए ₹15,000, Y के लिए ₹12,000 और Z के लिए ₹18,000 हैं। ब्रांड Z का राजस्व ब्रांड X के राजस्व का कितना प्रतिशत है?","optionsHi":["120%","69.8%","93.75%","83.75%"],"explanationHi":"X: 480 × 15,000 = ₹72 लाख; Z: 335 × 18,000 = ₹60.3 लाख। 60.3/72 = 83.75%। केवल कीमतों की तुलना (18/15 = 120%) बिकी हुई संख्या की अनदेखी करती है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-71","question":"800 employees are divided among HR, Finance, Sales and IT in the ratio 5 : 3 : 4 : 8. The percentage of graduates in these departments is 60%, 75%, 45% and 85% respectively. How many graduates work in IT?","options":["320","255","272","240"],"answer":2,"explanation":"IT has 8/20 × 800 = 320 employees, and 85% of 320 = 272. 320 is the department's strength.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"800 कर्मचारी HR, वित्त, बिक्री और IT विभागों में 5 : 3 : 4 : 8 के अनुपात में बँटे हैं। इन विभागों में स्नातकों का प्रतिशत क्रमशः 60%, 75%, 45% और 85% है। IT में कितने स्नातक कार्यरत हैं?","optionsHi":["320","255","272","240"],"explanationHi":"IT में 8/20 × 800 = 320 कर्मचारी हैं, और 320 का 85% = 272। 320 विभाग की कुल संख्या है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-72","question":"800 employees are divided among HR, Finance, Sales and IT in the ratio 5 : 3 : 4 : 8. The percentage of graduates in these departments is 60%, 75%, 45% and 85% respectively. Non-graduates in Sales form approximately what percent of all the non-graduates?","options":["55.0%","32.5%","35.8%","40.0%"],"answer":2,"explanation":"Non-graduates: HR 80, Finance 30, Sales 88, IT 48, total 246. Sales share = 88/246 ≈ 35.8%. 55% is the non-graduate percentage within Sales itself.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"800 कर्मचारी HR, वित्त, बिक्री और IT विभागों में 5 : 3 : 4 : 8 के अनुपात में बँटे हैं। इन विभागों में स्नातकों का प्रतिशत क्रमशः 60%, 75%, 45% और 85% है। बिक्री विभाग के अस्नातक सभी अस्नातकों का लगभग कितना प्रतिशत हैं?","optionsHi":["55.0%","32.5%","35.8%","40.0%"],"explanationHi":"अस्नातक: HR 80, वित्त 30, बिक्री 88, IT 48, कुल 246। बिक्री का हिस्सा = 88/246 ≈ 35.8%। 55% स्वयं बिक्री विभाग के भीतर अस्नातकों का प्रतिशत है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-73","question":"800 employees are divided among HR, Finance, Sales and IT in the ratio 5 : 3 : 4 : 8. The percentage of graduates in these departments is 60%, 75%, 45% and 85% respectively. If 20 non-graduates in each department complete their degrees, what will the overall percentage of graduates become?","options":["71.75%","79.25%","72.25%","81.75%"],"answer":1,"explanation":"Graduates now = 120 + 90 + 72 + 272 = 554. That is 69.25% now; adding 4 × 20 = 80 gives 634, and 634/800 = 79.25%. Adding only 20 graduates in all gives 71.75%.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"800 कर्मचारी HR, वित्त, बिक्री और IT विभागों में 5 : 3 : 4 : 8 के अनुपात में बँटे हैं। इन विभागों में स्नातकों का प्रतिशत क्रमशः 60%, 75%, 45% और 85% है। यदि प्रत्येक विभाग के 20 अस्नातक अपनी डिग्री पूरी कर लें, तो स्नातकों का समग्र प्रतिशत कितना हो जाएगा?","optionsHi":["71.75%","79.25%","72.25%","81.75%"],"explanationHi":"अभी स्नातक = 120 + 90 + 72 + 272 = 554। यह अभी 69.25% है; 4 × 20 = 80 जोड़ने पर 634 होता है, और 634/800 = 79.25%। कुल मिलाकर केवल 20 स्नातक जोड़ने पर 71.75% आता है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-74","question":"A city's population was 5,00,000 in 2020. Its annual growth rates were — 2021: +4%, 2022: +5%, 2023: −2%, 2024: +10%. What was the population in 2022?","options":["5,50,000","5,46,000","5,45,000","5,40,000"],"answer":1,"explanation":"5,00,000 × 1.04 × 1.05 = 5,46,000. 5,45,000 adds 9% simply instead of compounding.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"2020 में एक शहर की जनसंख्या 5,00,000 थी। उसकी वार्षिक वृद्धि दरें थीं — 2021: +4%, 2022: +5%, 2023: −2%, 2024: +10%। 2022 में जनसंख्या कितनी थी?","optionsHi":["5,50,000","5,46,000","5,45,000","5,40,000"],"explanationHi":"5,00,000 × 1.04 × 1.05 = 5,46,000। 5,45,000 में चक्रवृद्धि करने की जगह 9% साधारण रूप से जोड़ा गया है।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-75","question":"A city's population was 5,00,000 in 2020. Its annual growth rates were — 2021: +4%, 2022: +5%, 2023: −2%, 2024: +10%. What was the population in 2024?","options":["5,90,000","5,88,588","5,85,000","5,86,040"],"answer":1,"explanation":"5,46,000 × 0.98 = 5,35,080 (2023); × 1.10 = 5,88,588 (2024). Adding the rates simply (+17%) gives 5,85,000.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"2020 में एक शहर की जनसंख्या 5,00,000 थी। उसकी वार्षिक वृद्धि दरें थीं — 2021: +4%, 2022: +5%, 2023: −2%, 2024: +10%। 2024 में जनसंख्या कितनी थी?","optionsHi":["5,90,000","5,88,588","5,85,000","5,86,040"],"explanationHi":"5,46,000 × 0.98 = 5,35,080 (2023); × 1.10 = 5,88,588 (2024)। दरों को साधारण रूप से जोड़ने (+17%) पर 5,85,000 आता है।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-76","question":"A city's population was 5,00,000 in 2020. Its annual growth rates were — 2021: +4%, 2022: +5%, 2023: −2%, 2024: +10%. The absolute increase in population in 2022 was what percent of the absolute increase in 2021?","options":["105%","125%","130%","120%"],"answer":2,"explanation":"2021 increase = 20,000; 2022 increase = 5% of 5,20,000 = 26,000; 26,000/20,000 = 130%. 125% compares only the rates (5/4), ignoring the larger base in 2022.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"2020 में एक शहर की जनसंख्या 5,00,000 थी। उसकी वार्षिक वृद्धि दरें थीं — 2021: +4%, 2022: +5%, 2023: −2%, 2024: +10%। 2022 में जनसंख्या की निरपेक्ष वृद्धि, 2021 की निरपेक्ष वृद्धि का कितना प्रतिशत थी?","optionsHi":["105%","125%","130%","120%"],"explanationHi":"2021 की वृद्धि = 20,000; 2022 की वृद्धि = 5,20,000 का 5% = 26,000; 26,000/20,000 = 130%। 125% केवल दरों की तुलना (5/4) है, जिसमें 2022 के बड़े आधार की अनदेखी होती है।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-77","question":"Candidates who appeared and passed in an examination — 2020: 1,500 and 900; 2021: 1,800 and 1,170; 2022: 2,000 and 1,200; 2023: 2,400 and 1,680. What was the pass percentage in 2021?","options":["65%","62.5%","70%","60%"],"answer":0,"explanation":"Pass % in 2021 = 1,170/1,800 × 100 = 65%. 60% is the 2020 and 2022 rate, and 70% is 2023's rate, so read the right row.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"एक परीक्षा में बैठे और उत्तीर्ण अभ्यर्थी — 2020: 1,500 और 900; 2021: 1,800 और 1,170; 2022: 2,000 और 1,200; 2023: 2,400 और 1,680। 2021 में उत्तीर्ण प्रतिशत कितना था?","optionsHi":["65%","62.5%","70%","60%"],"explanationHi":"2021 में उत्तीर्ण % = 1,170/1,800 × 100 = 65%। 60% 2020 और 2022 की दर है, और 70% 2023 की दर है, इसलिए सही पंक्ति पढ़ें।","subtopic":"tables"},
  {"id":"quant-data-interpretation-78","question":"Candidates who appeared and passed in an examination — 2020: 1,500 and 900; 2021: 1,800 and 1,170; 2022: 2,000 and 1,200; 2023: 2,400 and 1,680. How many candidates failed in all over the four years?","options":["2,850","4,950","2,650","2,750"],"answer":3,"explanation":"Failed = 600 + 630 + 800 + 720 = 2,750. 4,950 is the number who passed.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक परीक्षा में बैठे और उत्तीर्ण अभ्यर्थी — 2020: 1,500 और 900; 2021: 1,800 और 1,170; 2022: 2,000 और 1,200; 2023: 2,400 और 1,680। चार वर्षों में कुल कितने अभ्यर्थी अनुत्तीर्ण हुए?","optionsHi":["2,850","4,950","2,650","2,750"],"explanationHi":"अनुत्तीर्ण = 600 + 630 + 800 + 720 = 2,750। 4,950 उत्तीर्ण होने वालों की संख्या है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-79","question":"Candidates who appeared and passed in an examination — 2020: 1,500 and 900; 2021: 1,800 and 1,170; 2022: 2,000 and 1,200; 2023: 2,400 and 1,680. How many of these statements are true? I. The pass percentage was highest in 2023. II. From 2020 to 2021, the number passing rose by the same percentage as the number appearing. III. The pass percentage in 2022 equalled that in 2021. IV. More than 5,000 candidates passed over the four years.","options":["Only one","Only two","All four","Only three"],"answer":0,"explanation":"Pass %: 60, 65, 60, 70, so only I is true. II is false (appeared +20%, passed +30%). III is false: 2022's 60% differs from 2021's 65%. IV is false: 900 + 1,170 + 1,200 + 1,680 = 4,950, below 5,000.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक परीक्षा में बैठे और उत्तीर्ण अभ्यर्थी — 2020: 1,500 और 900; 2021: 1,800 और 1,170; 2022: 2,000 और 1,200; 2023: 2,400 और 1,680। इनमें से कितने कथन सत्य हैं? I. उत्तीर्ण प्रतिशत 2023 में सबसे अधिक था। II. 2020 से 2021 तक उत्तीर्ण होने वालों की संख्या उतने ही प्रतिशत बढ़ी जितनी बैठने वालों की। III. 2022 का उत्तीर्ण प्रतिशत 2021 के बराबर था। IV. चार वर्षों में 5,000 से अधिक अभ्यर्थी उत्तीर्ण हुए।","optionsHi":["केवल एक","केवल दो","सभी चारों","केवल तीन"],"explanationHi":"उत्तीर्ण %: 60, 65, 60, 70, अतः केवल I सत्य है। II असत्य है (बैठने वाले +20%, उत्तीर्ण +30%)। III असत्य है: 2022 का 60%, 2021 के 65% से भिन्न है। IV असत्य है: 900 + 1,170 + 1,200 + 1,680 = 4,950, जो 5,000 से कम है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-80","question":"Imports (₹ crore) of four commodities in 2022 and 2023 — Oil: 1,200 and 1,380; Gold: 800 and 720; Electronics: 600 and 750; Fertiliser: 400 and 460. By approximately how many percentage points did oil's share of total imports change from 2022 to 2023?","options":["It rose by about 1.7 points","It fell by about 1.7 points","It did not change","It rose by about 15 points"],"answer":0,"explanation":"Oil's share: 2022 = 1,200/3,000 = 40%; 2023 = 1,380/3,310 ≈ 41.7%. A rise of about 1.7 percentage points; 15% is oil's own growth, not the change in share.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"2022 और 2023 में चार वस्तुओं का आयात (₹ करोड़ में) — तेल: 1,200 और 1,380; सोना: 800 और 720; इलेक्ट्रॉनिक्स: 600 और 750; उर्वरक: 400 और 460। 2022 से 2023 तक कुल आयात में तेल का हिस्सा लगभग कितने प्रतिशत अंकों से बदला?","optionsHi":["यह लगभग 1.7 अंक बढ़ा","यह लगभग 1.7 अंक घटा","इसमें कोई परिवर्तन नहीं हुआ","यह लगभग 15 अंक बढ़ा"],"explanationHi":"तेल का हिस्सा: 2022 = 1,200/3,000 = 40%; 2023 = 1,380/3,310 ≈ 41.7%। लगभग 1.7 प्रतिशत अंकों की वृद्धि; 15% तेल की अपनी वृद्धि है, हिस्से में परिवर्तन नहीं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-81","question":"Imports (₹ crore) of four commodities in 2022 and 2023 — Oil: 1,200 and 1,380; Gold: 800 and 720; Electronics: 600 and 750; Fertiliser: 400 and 460. For how many of the four commodities did the share in total imports fall from 2022 to 2023?","options":["Two","None","Three","One"],"answer":3,"explanation":"Total rose from 3,000 to 3,310 (+10.3%). Only gold grew slower than that (it fell 10%); oil +15%, electronics +25% and fertiliser +15% all gained share.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"2022 और 2023 में चार वस्तुओं का आयात (₹ करोड़ में) — तेल: 1,200 और 1,380; सोना: 800 और 720; इलेक्ट्रॉनिक्स: 600 और 750; उर्वरक: 400 और 460। चार वस्तुओं में से कितनी वस्तुओं का कुल आयात में हिस्सा 2022 से 2023 तक घटा?","optionsHi":["दो","एक भी नहीं","तीन","एक"],"explanationHi":"कुल आयात 3,000 से बढ़कर 3,310 हो गया (+10.3%)। केवल सोना इससे धीमा बढ़ा (वह 10% घटा); तेल +15%, इलेक्ट्रॉनिक्स +25% और उर्वरक +15% तीनों का हिस्सा बढ़ा।","subtopic":"tables"},
  {"id":"quant-data-interpretation-82","question":"Imports (₹ crore) of four commodities in 2022 and 2023 — Oil: 1,200 and 1,380; Gold: 800 and 720; Electronics: 600 and 750; Fertiliser: 400 and 460. In 2024, oil imports grow by the same percentage as in 2023, gold imports return to their 2022 level, and the other two stay at their 2023 values. What are the total imports in 2024?","options":["₹3,597 crore","₹3,641 crore","₹3,517 crore","₹3,390 crore"],"answer":0,"explanation":"Oil = 1,380 × 1.15 = 1,587; gold = 800; electronics = 750; fertiliser = 460. Total = ₹3,597 crore.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"2022 और 2023 में चार वस्तुओं का आयात (₹ करोड़ में) — तेल: 1,200 और 1,380; सोना: 800 और 720; इलेक्ट्रॉनिक्स: 600 और 750; उर्वरक: 400 और 460। 2024 में तेल का आयात उतने ही प्रतिशत बढ़ता है जितना 2023 में बढ़ा था, सोने का आयात अपने 2022 के स्तर पर लौट आता है, और अन्य दो अपने 2023 के मानों पर रहते हैं। 2024 में कुल आयात कितना है?","optionsHi":["₹3,597 करोड़","₹3,641 करोड़","₹3,517 करोड़","₹3,390 करोड़"],"explanationHi":"तेल = 1,380 × 1.15 = 1,587; सोना = 800; इलेक्ट्रॉनिक्स = 750; उर्वरक = 460। कुल = ₹3,597 करोड़।","subtopic":"tables"},
  {"id":"quant-data-interpretation-83","question":"Number of students and average marks of four sections — A: 30 students, 60; B: 20 students, 70; C: 40 students, 55; D: 10 students, 80. What is the average mark of all 100 students?","options":["63","62","66.25","61"],"answer":1,"explanation":"Total = 1,800 + 1,400 + 2,200 + 800 = 6,200, so the average = 62. 66.25 is the simple average of the four section averages.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"चार वर्गों के विद्यार्थियों की संख्या और औसत अंक — A: 30 विद्यार्थी, 60; B: 20 विद्यार्थी, 70; C: 40 विद्यार्थी, 55; D: 10 विद्यार्थी, 80। सभी 100 विद्यार्थियों के औसत अंक कितने हैं?","optionsHi":["63","62","66.25","61"],"explanationHi":"कुल = 1,800 + 1,400 + 2,200 + 800 = 6,200, अतः औसत = 62। 66.25 चारों वर्गों के औसतों का साधारण औसत है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-84","question":"Number of students and average marks of four sections — A: 30 students, 60; B: 20 students, 70; C: 40 students, 55; D: 10 students, 80. If section D is left out, what is the average mark of the remaining students?","options":["60","62","54","61.67"],"answer":0,"explanation":"Total = 1,800 + 1,400 + 2,200 = 5,400 for 90 students (without D), an average of 60. 62 includes D, 54 still divides by 100 students, and 61.67 averages the three section averages without weights.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"चार वर्गों के विद्यार्थियों की संख्या और औसत अंक — A: 30 विद्यार्थी, 60; B: 20 विद्यार्थी, 70; C: 40 विद्यार्थी, 55; D: 10 विद्यार्थी, 80। यदि वर्ग D को छोड़ दिया जाए, तो शेष विद्यार्थियों के औसत अंक कितने हैं?","optionsHi":["60","62","54","61.67"],"explanationHi":"कुल = 1,800 + 1,400 + 2,200 = 5,400, 90 विद्यार्थियों के लिए (D के बिना), अर्थात् औसत 60। 62 में D शामिल है, 54 में अब भी 100 विद्यार्थियों से भाग दिया गया है, और 61.67 तीनों वर्गों के औसतों का बिना भार के औसत है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-85","question":"Number of students and average marks of four sections — A: 30 students, 60; B: 20 students, 70; C: 40 students, 55; D: 10 students, 80. Five students of section B, whose average mark is 82, are moved to section C. What are the new averages of B and C respectively?","options":["66 and 58","70 and 55","66 and 57.5","67 and 57"],"answer":0,"explanation":"B: (1,400 − 410)/15 = 990/15 = 66. C: (2,200 + 410)/45 = 2,610/45 = 58. B's average falls and C's rises, yet C's is still below B's.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"चार वर्गों के विद्यार्थियों की संख्या और औसत अंक — A: 30 विद्यार्थी, 60; B: 20 विद्यार्थी, 70; C: 40 विद्यार्थी, 55; D: 10 विद्यार्थी, 80। वर्ग B के पाँच विद्यार्थियों को, जिनके औसत अंक 82 हैं, वर्ग C में भेज दिया जाता है। B और C के नए औसत क्रमशः कितने हैं?","optionsHi":["66 और 58","70 और 55","66 और 57.5","67 और 57"],"explanationHi":"B: (1,400 − 410)/15 = 990/15 = 66। C: (2,200 + 410)/45 = 2,610/45 = 58। B का औसत घटता है और C का बढ़ता है, फिर भी C का औसत B से कम रहता है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-86","question":"Phones sold (thousand) — Company: 2021, 2022, 2023 / Alpha: 120, 150, 180 / Beta: 90, 108, 135 / Gamma: 150, 135, 162 / Delta: 60, 84, 105. How many phones (thousand) did the four companies sell in all in 2022?","options":["467","487","477","457"],"answer":2,"explanation":"150 + 108 + 135 + 84 = 477. Add in pairs (150 + 84 = 234, 108 + 135 = 243) to avoid slips.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"बेचे गए फोन (हज़ार में) — कंपनी: 2021, 2022, 2023 / अल्फा: 120, 150, 180 / बीटा: 90, 108, 135 / गामा: 150, 135, 162 / डेल्टा: 60, 84, 105। 2022 में चारों कंपनियों ने कुल कितने फोन (हज़ार में) बेचे?","optionsHi":["467","487","477","457"],"explanationHi":"150 + 108 + 135 + 84 = 477। चूक से बचने के लिए जोड़ियों में जोड़ें (150 + 84 = 234, 108 + 135 = 243)।","subtopic":"tables"},
  {"id":"quant-data-interpretation-87","question":"Phones sold (thousand) — Company: 2021, 2022, 2023 / Alpha: 120, 150, 180 / Beta: 90, 108, 135 / Gamma: 150, 135, 162 / Delta: 60, 84, 105. By what percent did Beta's sales rise from 2022 to 2023?","options":["20%","27%","22.5%","25%"],"answer":3,"explanation":"Rise = 27 on a base of 108, and 27/108 = 1/4 = 25%. 20% is the trap of dividing by the 2023 figure, 135.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"बेचे गए फोन (हज़ार में) — कंपनी: 2021, 2022, 2023 / अल्फा: 120, 150, 180 / बीटा: 90, 108, 135 / गामा: 150, 135, 162 / डेल्टा: 60, 84, 105। 2022 से 2023 तक बीटा की बिक्री कितने प्रतिशत बढ़ी?","optionsHi":["20%","27%","22.5%","25%"],"explanationHi":"वृद्धि = 27, आधार 108 पर, और 27/108 = 1/4 = 25%। 20% 2023 के आँकड़े 135 से भाग देने की भूल है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-88","question":"Phones sold (thousand) — Company: 2021, 2022, 2023 / Alpha: 120, 150, 180 / Beta: 90, 108, 135 / Gamma: 150, 135, 162 / Delta: 60, 84, 105. Which company had the highest percentage growth in sales from 2021 to 2023?","options":["Delta","Alpha","Beta","Gamma"],"answer":0,"explanation":"Growth: Alpha 60/120 = 50%, Beta 45/90 = 50%, Gamma 12/150 = 8%, Delta 45/60 = 75%. Alpha has the largest absolute rise, but Delta's small base gives the biggest percentage.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"बेचे गए फोन (हज़ार में) — कंपनी: 2021, 2022, 2023 / अल्फा: 120, 150, 180 / बीटा: 90, 108, 135 / गामा: 150, 135, 162 / डेल्टा: 60, 84, 105। 2021 से 2023 तक किस कंपनी की बिक्री में प्रतिशत वृद्धि सबसे अधिक रही?","optionsHi":["डेल्टा","अल्फा","बीटा","गामा"],"explanationHi":"वृद्धि: अल्फा 60/120 = 50%, बीटा 45/90 = 50%, गामा 12/150 = 8%, डेल्टा 45/60 = 75%। अल्फा की निरपेक्ष वृद्धि सबसे अधिक है, पर डेल्टा का छोटा आधार उसे सबसे अधिक प्रतिशत देता है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-89","question":"Phones sold (thousand) — Company: 2021, 2022, 2023 / Alpha: 120, 150, 180 / Beta: 90, 108, 135 / Gamma: 150, 135, 162 / Delta: 60, 84, 105. If in 2024 each of Alpha and Delta grows at the same percentage rate as it did from 2022 to 2023, by how many thousand will Alpha's 2024 sales exceed Delta's?","options":["75","84.75","81.25","90"],"answer":1,"explanation":"Alpha grew 30/150 = 20%, so 2024 = 180 × 1.2 = 216. Delta grew 21/84 = 25%, so 2024 = 105 × 1.25 = 131.25. Difference = 84.75 thousand.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"बेचे गए फोन (हज़ार में) — कंपनी: 2021, 2022, 2023 / अल्फा: 120, 150, 180 / बीटा: 90, 108, 135 / गामा: 150, 135, 162 / डेल्टा: 60, 84, 105। यदि 2024 में अल्फा और डेल्टा प्रत्येक उसी प्रतिशत दर से बढ़ें जिस दर से वे 2022 से 2023 तक बढ़े थे, तो अल्फा की 2024 की बिक्री डेल्टा की बिक्री से कितने हज़ार अधिक होगी?","optionsHi":["75","84.75","81.25","90"],"explanationHi":"अल्फा 30/150 = 20% बढ़ा, अतः 2024 = 180 × 1.2 = 216। डेल्टा 21/84 = 25% बढ़ा, अतः 2024 = 105 × 1.25 = 131.25। अंतर = 84.75 हज़ार।","subtopic":"tables"},
  {"id":"quant-data-interpretation-90","question":"Phones sold (thousand) — Company: 2021, 2022, 2023 / Alpha: 120, 150, 180 / Beta: 90, 108, 135 / Gamma: 150, 135, 162 / Delta: 60, 84, 105. Beta's average selling price per phone was ₹12,000 in 2021 and rose by 10% every year. By what percent was Beta's sales revenue in 2023 higher than in 2021?","options":["71.5%","50%","81.5%","65%"],"answer":2,"explanation":"Revenue ratio = (135/90) × 1.1² = 1.5 × 1.21 = 1.815, an 81.5% rise. The ₹12,000 is not needed; 50% ignores the price rise and 65% adds 50% + 15% instead of multiplying.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"बेचे गए फोन (हज़ार में) — कंपनी: 2021, 2022, 2023 / अल्फा: 120, 150, 180 / बीटा: 90, 108, 135 / गामा: 150, 135, 162 / डेल्टा: 60, 84, 105। बीटा का प्रति फोन औसत विक्रय मूल्य 2021 में ₹12,000 था और हर वर्ष 10% बढ़ा। 2023 में बीटा का बिक्री राजस्व 2021 की तुलना में कितने प्रतिशत अधिक था?","optionsHi":["71.5%","50%","81.5%","65%"],"explanationHi":"राजस्व अनुपात = (135/90) × 1.1² = 1.5 × 1.21 = 1.815, अर्थात् 81.5% की वृद्धि। ₹12,000 की आवश्यकता नहीं है; 50% में मूल्य वृद्धि की अनदेखी है और 65% में गुणा करने की जगह 50% + 15% जोड़ा गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-91","question":"The monthly expenditure of ₹48 lakh of an engineering college is shown in a pie chart — Salaries 35%, Infrastructure 20%, Lab equipment 15%, Library 8%, Transport 12%, Others 10%. What is the central angle of the Lab equipment sector?","options":["60°","48°","36°","54°"],"answer":3,"explanation":"Each 1% of a pie is 3.6°, so 15% = 54°; the ₹48 lakh total is not needed. 36° is the 10% Others sector, and 48° borrows the budget figure as degrees.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक इंजीनियरिंग कॉलेज का ₹48 लाख का मासिक व्यय पाई चार्ट में दिखाया गया है — वेतन 35%, आधारभूत संरचना 20%, प्रयोगशाला उपकरण 15%, पुस्तकालय 8%, परिवहन 12%, अन्य 10%। प्रयोगशाला उपकरण वाले खंड का केंद्रीय कोण कितना है?","optionsHi":["60°","48°","36°","54°"],"explanationHi":"पाई के प्रत्येक 1% का कोण 3.6° होता है, अतः 15% = 54°; कुल ₹48 लाख की आवश्यकता नहीं है। 36° 10% वाले अन्य खंड का है, और 48° में बजट की राशि को ही अंश मान लिया गया है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-92","question":"The monthly expenditure of ₹48 lakh of an engineering college is shown in a pie chart — Salaries 35%, Infrastructure 20%, Lab equipment 15%, Library 8%, Transport 12%, Others 10%. By how much does the spending on Salaries exceed the combined spending on Library and Transport?","options":["₹7.2 lakh","₹9.6 lakh","₹6 lakh","₹4.8 lakh"],"answer":0,"explanation":"Work in percentages first: 35% − (8% + 12%) = 15%. 15% of ₹48 lakh = ₹7.2 lakh.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक इंजीनियरिंग कॉलेज का ₹48 लाख का मासिक व्यय पाई चार्ट में दिखाया गया है — वेतन 35%, आधारभूत संरचना 20%, प्रयोगशाला उपकरण 15%, पुस्तकालय 8%, परिवहन 12%, अन्य 10%। वेतन पर खर्च पुस्तकालय और परिवहन के संयुक्त खर्च से कितना अधिक है?","optionsHi":["₹7.2 लाख","₹9.6 लाख","₹6 लाख","₹4.8 लाख"],"explanationHi":"पहले प्रतिशत में काम करें: 35% − (8% + 12%) = 15%। ₹48 लाख का 15% = ₹7.2 लाख।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-93","question":"The monthly expenditure of ₹48 lakh of an engineering college is shown in a pie chart — Salaries 35%, Infrastructure 20%, Lab equipment 15%, Library 8%, Transport 12%, Others 10%. Next month the total budget rises by 25% but the amount spent on Salaries stays the same. What percentage of the new budget goes to Salaries?","options":["35%","28%","30%","26.25%"],"answer":1,"explanation":"Salaries = 35% of 48 = ₹16.8 lakh; new budget = 48 × 1.25 = ₹60 lakh; share = 16.8/60 = 28%. Shortcut: 35% ÷ 1.25 = 28%.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक इंजीनियरिंग कॉलेज का ₹48 लाख का मासिक व्यय पाई चार्ट में दिखाया गया है — वेतन 35%, आधारभूत संरचना 20%, प्रयोगशाला उपकरण 15%, पुस्तकालय 8%, परिवहन 12%, अन्य 10%। अगले महीने कुल बजट 25% बढ़ जाता है, परंतु वेतन पर खर्च की राशि वही रहती है। नए बजट का कितना प्रतिशत वेतन पर जाता है?","optionsHi":["35%","28%","30%","26.25%"],"explanationHi":"वेतन = 48 का 35% = ₹16.8 लाख; नया बजट = 48 × 1.25 = ₹60 लाख; हिस्सा = 16.8/60 = 28%। शॉर्टकट: 35% ÷ 1.25 = 28%।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-94","question":"The monthly expenditure of ₹48 lakh of an engineering college is shown in a pie chart — Salaries 35%, Infrastructure 20%, Lab equipment 15%, Library 8%, Transport 12%, Others 10%. Infrastructure spending is cut by 25%, and the money saved is shared between Library and Lab equipment in the ratio 1 : 2, the total budget staying the same. What is the new central angle of the Lab equipment sector?","options":["60°","63°","66°","72°"],"answer":2,"explanation":"The cut is 25% of 20% = 5% of the budget; Lab gets 2/3 of it = 10/3%. New Lab share = 15 + 10/3 = 55/3%, and 55/3 × 3.6° = 66°. 72° wrongly hands the Lab 5% more.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक इंजीनियरिंग कॉलेज का ₹48 लाख का मासिक व्यय पाई चार्ट में दिखाया गया है — वेतन 35%, आधारभूत संरचना 20%, प्रयोगशाला उपकरण 15%, पुस्तकालय 8%, परिवहन 12%, अन्य 10%। आधारभूत संरचना पर खर्च में 25% की कटौती की जाती है, और बची हुई राशि पुस्तकालय और प्रयोगशाला उपकरण में 1 : 2 के अनुपात में बाँटी जाती है, कुल बजट वही रहता है। प्रयोगशाला उपकरण खंड का नया केंद्रीय कोण कितना है?","optionsHi":["60°","63°","66°","72°"],"explanationHi":"कटौती 20% का 25% = बजट का 5% है; प्रयोगशाला को इसका 2/3 = 10/3% मिलता है। प्रयोगशाला का नया हिस्सा = 15 + 10/3 = 55/3%, और 55/3 × 3.6° = 66°। 72° में प्रयोगशाला को गलती से 5% अधिक दे दिया गया है।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-95","question":"Home loans disbursed by a bank branch — Year: 2020, 2021, 2022, 2023 / Number of loans: 80, 96, 120, 150 / Average loan size (₹ lakh): 25, 30, 28, 32. What was the total amount disbursed in 2022?","options":["₹336 crore","₹3.36 crore","₹28.8 crore","₹33.6 crore"],"answer":3,"explanation":"120 × ₹28 lakh = ₹3,360 lakh = ₹33.6 crore (100 lakh = 1 crore). ₹28.8 crore is the 2021 figure (96 × 30).","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक बैंक शाखा द्वारा वितरित गृह ऋण — वर्ष: 2020, 2021, 2022, 2023 / ऋणों की संख्या: 80, 96, 120, 150 / औसत ऋण राशि (₹ लाख में): 25, 30, 28, 32। 2022 में वितरित कुल राशि कितनी थी?","optionsHi":["₹336 करोड़","₹3.36 करोड़","₹28.8 करोड़","₹33.6 करोड़"],"explanationHi":"120 × ₹28 लाख = ₹3,360 लाख = ₹33.6 करोड़ (100 लाख = 1 करोड़)। ₹28.8 करोड़ 2021 का आँकड़ा है (96 × 30)।","subtopic":"tables"},
  {"id":"quant-data-interpretation-96","question":"Home loans disbursed by a bank branch — Year: 2020, 2021, 2022, 2023 / Number of loans: 80, 96, 120, 150 / Average loan size (₹ lakh): 25, 30, 28, 32. By what percent did the total amount disbursed increase from 2020 to 2023?","options":["140%","87.5%","28%","120%"],"answer":0,"explanation":"Amount 2020 = 80 × 25 = 2,000 lakh; 2023 = 150 × 32 = 4,800 lakh. Increase = 2,800/2,000 = 140%. 87.5% is only the growth in the number of loans.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक बैंक शाखा द्वारा वितरित गृह ऋण — वर्ष: 2020, 2021, 2022, 2023 / ऋणों की संख्या: 80, 96, 120, 150 / औसत ऋण राशि (₹ लाख में): 25, 30, 28, 32। 2020 से 2023 तक वितरित कुल राशि में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["140%","87.5%","28%","120%"],"explanationHi":"2020 की राशि = 80 × 25 = 2,000 लाख; 2023 = 150 × 32 = 4,800 लाख। वृद्धि = 2,800/2,000 = 140%। 87.5% केवल ऋणों की संख्या की वृद्धि है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-97","question":"Home loans disbursed by a bank branch — Year: 2020, 2021, 2022, 2023 / Number of loans: 80, 96, 120, 150 / Average loan size (₹ lakh): 25, 30, 28, 32. In which year was the percentage increase in the total amount disbursed, over the previous year, the highest?","options":["2023","2021","2022","Both 2021 and 2023"],"answer":1,"explanation":"Amounts (₹ lakh): 2,000, 2,880, 3,360, 4,800. Growth: 2021 = 880/2,000 = 44%, 2022 ≈ 16.7%, 2023 = 1,440/3,360 ≈ 42.9%. 2023 has the bigger absolute jump, but 2021 has the higher percentage.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक बैंक शाखा द्वारा वितरित गृह ऋण — वर्ष: 2020, 2021, 2022, 2023 / ऋणों की संख्या: 80, 96, 120, 150 / औसत ऋण राशि (₹ लाख में): 25, 30, 28, 32। किस वर्ष में वितरित कुल राशि में पिछले वर्ष की तुलना में प्रतिशत वृद्धि सबसे अधिक रही?","optionsHi":["2023","2021","2022","2021 और 2023 दोनों"],"explanationHi":"राशियाँ (₹ लाख): 2,000, 2,880, 3,360, 4,800। वृद्धि: 2021 = 880/2,000 = 44%, 2022 ≈ 16.7%, 2023 = 1,440/3,360 ≈ 42.9%। 2023 में निरपेक्ष उछाल बड़ा है, पर प्रतिशत 2021 का अधिक है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-98","question":"Home loans disbursed by a bank branch — Year: 2020, 2021, 2022, 2023 / Number of loans: 80, 96, 120, 150 / Average loan size (₹ lakh): 25, 30, 28, 32. In 2023, 20% of the loans (by number) had an average size of ₹50 lakh. What was the average size of the remaining loans that year?","options":["₹28 lakh","₹25 lakh","₹27.5 lakh","₹30 lakh"],"answer":2,"explanation":"Total = 150 × 32 = 4,800 lakh. 30 loans × 50 = 1,500 lakh, leaving 3,300 lakh over 120 loans = ₹27.5 lakh.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक बैंक शाखा द्वारा वितरित गृह ऋण — वर्ष: 2020, 2021, 2022, 2023 / ऋणों की संख्या: 80, 96, 120, 150 / औसत ऋण राशि (₹ लाख में): 25, 30, 28, 32। 2023 में 20% ऋणों (संख्या के आधार पर) की औसत राशि ₹50 लाख थी। उस वर्ष शेष ऋणों की औसत राशि कितनी थी?","optionsHi":["₹28 लाख","₹25 लाख","₹27.5 लाख","₹30 लाख"],"explanationHi":"कुल = 150 × 32 = 4,800 लाख। 30 ऋण × 50 = 1,500 लाख, शेष 3,300 लाख 120 ऋणों पर = ₹27.5 लाख।","subtopic":"tables"},
  {"id":"quant-data-interpretation-99","question":"Students enrolled and percentage selected at a coaching institute — SSC: 600, 15%; Banking: 800, 12%; Railways: 500, 20%; Defence: 400, 25%. How many Banking students were selected?","options":["120","100","80","96"],"answer":3,"explanation":"Banking selections = 12% of 800 = 96. 120 applies SSC's 15% to the Banking figure, and 80 uses 10%.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक कोचिंग संस्थान में नामांकित विद्यार्थी और चयनित प्रतिशत — SSC: 600, 15%; बैंकिंग: 800, 12%; रेलवे: 500, 20%; रक्षा: 400, 25%। बैंकिंग के कितने विद्यार्थी चयनित हुए?","optionsHi":["120","100","80","96"],"explanationHi":"बैंकिंग के चयन = 800 का 12% = 96। 120 में बैंकिंग के आँकड़े पर SSC का 15% लगाया गया है, और 80 में 10% लिया गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-100","question":"Students enrolled and percentage selected at a coaching institute — SSC: 600, 15%; Banking: 800, 12%; Railways: 500, 20%; Defence: 400, 25%. What is the overall selection percentage of the institute (correct to two decimals)?","options":["16.78%","18%","17.25%","15.5%"],"answer":0,"explanation":"Selected = 90 + 96 + 100 + 100 = 386 out of 2,300, i.e. 16.78%. 18% is the trap of averaging the four percentages without weighting.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक कोचिंग संस्थान में नामांकित विद्यार्थी और चयनित प्रतिशत — SSC: 600, 15%; बैंकिंग: 800, 12%; रेलवे: 500, 20%; रक्षा: 400, 25%। संस्थान का समग्र चयन प्रतिशत कितना है (दो दशमलव स्थानों तक सही)?","optionsHi":["16.78%","18%","17.25%","15.5%"],"explanationHi":"चयनित = 90 + 96 + 100 + 100 = 386, कुल 2,300 में से, अर्थात् 16.78%। 18% चारों प्रतिशतों का बिना भार के औसत लेने की भूल है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-101","question":"Students enrolled and percentage selected at a coaching institute — SSC: 600, 15%; Banking: 800, 12%; Railways: 500, 20%; Defence: 400, 25%. What is the ratio of SSC students not selected to Defence students not selected?","options":["3 : 2","17 : 10","3 : 5","9 : 10"],"answer":1,"explanation":"Not selected: SSC 85% of 600 = 510, Defence 75% of 400 = 300. 510 : 300 = 17 : 10. 3 : 2 compares the enrolments, 3 : 5 the selection rates.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक कोचिंग संस्थान में नामांकित विद्यार्थी और चयनित प्रतिशत — SSC: 600, 15%; बैंकिंग: 800, 12%; रेलवे: 500, 20%; रक्षा: 400, 25%। SSC के अचयनित विद्यार्थियों और रक्षा के अचयनित विद्यार्थियों का अनुपात कितना है?","optionsHi":["3 : 2","17 : 10","3 : 5","9 : 10"],"explanationHi":"अचयनित: SSC 600 का 85% = 510, रक्षा 400 का 75% = 300। 510 : 300 = 17 : 10। 3 : 2 नामांकनों की तुलना है, 3 : 5 चयन दरों की।","subtopic":"tables"},
  {"id":"quant-data-interpretation-102","question":"Students enrolled and percentage selected at a coaching institute — SSC: 600, 15%; Banking: 800, 12%; Railways: 500, 20%; Defence: 400, 25%. Next year enrolment in every stream rises by 25%. Selections stay the same in every stream except Railways, where they double. What is the new overall selection percentage (correct to two decimals)?","options":["21.13%","16.78%","16.90%","13.43%"],"answer":2,"explanation":"Selected = 90 + 96 + 200 + 100 = 486; enrolled = 2,300 × 1.25 = 2,875. 486/2,875 = 16.90%. 21.13% forgets the enrolment rise; 13.43% forgets the Railways doubling.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कोचिंग संस्थान में नामांकित विद्यार्थी और चयनित प्रतिशत — SSC: 600, 15%; बैंकिंग: 800, 12%; रेलवे: 500, 20%; रक्षा: 400, 25%। अगले वर्ष हर वर्ग में नामांकन 25% बढ़ जाता है। रेलवे को छोड़कर हर वर्ग में चयन वही रहते हैं, रेलवे में वे दुगुने हो जाते हैं। नया समग्र चयन प्रतिशत कितना है (दो दशमलव स्थानों तक सही)?","optionsHi":["21.13%","16.78%","16.90%","13.43%"],"explanationHi":"चयनित = 90 + 96 + 200 + 100 = 486; नामांकित = 2,300 × 1.25 = 2,875। 486/2,875 = 16.90%। 21.13% में नामांकन की वृद्धि भूल गई है; 13.43% में रेलवे के चयन का दुगुना होना भूल गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-103","question":"A factory made 4,800 units of products P, Q and R in the ratio 5 : 4 : 3. The defective rates were P 4%, Q 5% and R 10%. Good units sell at ₹500 (P), ₹800 (Q) and ₹1,200 (R); every defective unit is sold at 40% of its product's price. Defective units make up what percentage of the total production (correct to two decimals)?","options":["6.33%","19%","5.5%","5.83%"],"answer":3,"explanation":"P = 2,000, Q = 1,600, R = 1,200. Defectives = 80 + 80 + 120 = 280, and 280/4,800 = 5.83%. 6.33% is the unweighted average of 4%, 5% and 10%.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक कारखाने ने उत्पादों P, Q और R की 4,800 इकाइयाँ 5 : 4 : 3 के अनुपात में बनाईं। दोषपूर्ण इकाइयों की दरें P 4%, Q 5% और R 10% थीं। अच्छी इकाइयाँ ₹500 (P), ₹800 (Q) और ₹1,200 (R) में बिकती हैं; प्रत्येक दोषपूर्ण इकाई अपने उत्पाद के मूल्य के 40% पर बिकती है। दोषपूर्ण इकाइयाँ कुल उत्पादन का कितना प्रतिशत हैं (दो दशमलव स्थानों तक सही)?","optionsHi":["6.33%","19%","5.5%","5.83%"],"explanationHi":"P = 2,000, Q = 1,600, R = 1,200। दोषपूर्ण = 80 + 80 + 120 = 280, और 280/4,800 = 5.83%। 6.33% 4%, 5% और 10% का बिना भार का औसत है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-104","question":"A factory made 4,800 units of products P, Q and R in the ratio 5 : 4 : 3. The defective rates were P 4%, Q 5% and R 10%. Good units sell at ₹500 (P), ₹800 (Q) and ₹1,200 (R); every defective unit is sold at 40% of its product's price. What is the total revenue from product Q?","options":["₹12.416 lakh","₹12.8 lakh","₹12.16 lakh","₹12.544 lakh"],"answer":0,"explanation":"Q = 1,600 units: 1,520 good × ₹800 = ₹12,16,000 and 80 defective × ₹320 = ₹25,600. Total ₹12,41,600 = ₹12.416 lakh. ₹12.544 lakh is the trap of selling defectives at a 40% discount (₹480).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कारखाने ने उत्पादों P, Q और R की 4,800 इकाइयाँ 5 : 4 : 3 के अनुपात में बनाईं। दोषपूर्ण इकाइयों की दरें P 4%, Q 5% और R 10% थीं। अच्छी इकाइयाँ ₹500 (P), ₹800 (Q) और ₹1,200 (R) में बिकती हैं; प्रत्येक दोषपूर्ण इकाई अपने उत्पाद के मूल्य के 40% पर बिकती है। उत्पाद Q से कुल राजस्व कितना है?","optionsHi":["₹12.416 लाख","₹12.8 लाख","₹12.16 लाख","₹12.544 लाख"],"explanationHi":"Q = 1,600 इकाइयाँ: 1,520 अच्छी × ₹800 = ₹12,16,000 और 80 दोषपूर्ण × ₹320 = ₹25,600। कुल ₹12,41,600 = ₹12.416 लाख। ₹12.544 लाख दोषपूर्ण इकाइयों को 40% की छूट पर (₹480) बेचने की भूल से आता है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-105","question":"A factory made 4,800 units of products P, Q and R in the ratio 5 : 4 : 3. The defective rates were P 4%, Q 5% and R 10%. Good units sell at ₹500 (P), ₹800 (Q) and ₹1,200 (R); every defective unit is sold at 40% of its product's price. How much revenue does the factory lose in all because of defective units, compared with selling every unit at full price?","options":["₹99,200","₹1,48,800","₹2,48,000","₹1,24,000"],"answer":1,"explanation":"Full value of the defectives = 80 × 500 + 80 × 800 + 120 × 1,200 = ₹2,48,000, and each loses 60% of its price: 0.6 × 2,48,000 = ₹1,48,800. ₹99,200 is the 40% actually recovered.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कारखाने ने उत्पादों P, Q और R की 4,800 इकाइयाँ 5 : 4 : 3 के अनुपात में बनाईं। दोषपूर्ण इकाइयों की दरें P 4%, Q 5% और R 10% थीं। अच्छी इकाइयाँ ₹500 (P), ₹800 (Q) और ₹1,200 (R) में बिकती हैं; प्रत्येक दोषपूर्ण इकाई अपने उत्पाद के मूल्य के 40% पर बिकती है। हर इकाई को पूरे मूल्य पर बेचने की तुलना में, दोषपूर्ण इकाइयों के कारण कारखाने को कुल कितने राजस्व की हानि होती है?","optionsHi":["₹99,200","₹1,48,800","₹2,48,000","₹1,24,000"],"explanationHi":"दोषपूर्ण इकाइयों का पूरा मूल्य = 80 × 500 + 80 × 800 + 120 × 1,200 = ₹2,48,000, और प्रत्येक अपने मूल्य का 60% खोती है: 0.6 × 2,48,000 = ₹1,48,800। ₹99,200 वह 40% है जो वास्तव में वसूल होता है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-106","question":"Passengers (lakh) handled by four airports in the first half (H1) and second half (H2) of 2023 — Delhi: 340, 380; Mumbai: 300, 330; Bengaluru: 180, 216; Chennai: 120, 132. Bengaluru's total passengers for 2023 are what percentage of Mumbai's (correct to two decimals)?","options":["60%","65.45%","62.86%","54.55%"],"answer":2,"explanation":"Bengaluru = 180 + 216 = 396; Mumbai = 300 + 330 = 630. 396/630 = 22/35 = 62.86%.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"2023 के पहले छमाही (H1) और दूसरे छमाही (H2) में चार हवाई अड्डों द्वारा संभाले गए यात्री (लाख में) — दिल्ली: 340, 380; मुंबई: 300, 330; बेंगलुरु: 180, 216; चेन्नई: 120, 132। 2023 के लिए बेंगलुरु के कुल यात्री मुंबई के कुल यात्रियों का कितना प्रतिशत हैं (दो दशमलव स्थानों तक सही)?","optionsHi":["60%","65.45%","62.86%","54.55%"],"explanationHi":"बेंगलुरु = 180 + 216 = 396; मुंबई = 300 + 330 = 630। 396/630 = 22/35 = 62.86%।","subtopic":"tables"},
  {"id":"quant-data-interpretation-107","question":"Passengers (lakh) handled by four airports in the first half (H1) and second half (H2) of 2023 — Delhi: 340, 380; Mumbai: 300, 330; Bengaluru: 180, 216; Chennai: 120, 132. By what percentage did the combined passenger count of the four airports rise from H1 to H2 (correct to two decimals)?","options":["12.94%","11.15%","14%","12.55%"],"answer":3,"explanation":"H1 total = 940, H2 total = 1,058, rise = 118/940 = 12.55%. 12.94% is the simple average of the four individual growth rates, which ignores airport size.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"2023 के पहले छमाही (H1) और दूसरे छमाही (H2) में चार हवाई अड्डों द्वारा संभाले गए यात्री (लाख में) — दिल्ली: 340, 380; मुंबई: 300, 330; बेंगलुरु: 180, 216; चेन्नई: 120, 132। H1 से H2 तक चारों हवाई अड्डों की संयुक्त यात्री संख्या कितने प्रतिशत बढ़ी (दो दशमलव स्थानों तक सही)?","optionsHi":["12.94%","11.15%","14%","12.55%"],"explanationHi":"H1 का कुल = 940, H2 का कुल = 1,058, वृद्धि = 118/940 = 12.55%। 12.94% चारों व्यक्तिगत वृद्धि दरों का साधारण औसत है, जिसमें हवाई अड्डों के आकार की अनदेखी होती है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-108","question":"Passengers (lakh) handled by four airports in the first half (H1) and second half (H2) of 2023 — Delhi: 340, 380; Mumbai: 300, 330; Bengaluru: 180, 216; Chennai: 120, 132. Delhi's H2 passengers were domestic and international in the ratio 15 : 4. A user fee of ₹200 is charged per domestic passenger and ₹600 per international passenger. What was the total fee collected at Delhi in H2?","options":["₹1,080 crore","₹1,200 crore","₹960 crore","₹10.8 crore"],"answer":0,"explanation":"380 lakh split 15 : 4 gives 300 lakh domestic and 80 lakh international. Fee = 300 lakh × 200 + 80 lakh × 600 = 60,000 lakh + 48,000 lakh = 1,08,000 lakh = ₹1,080 crore.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"2023 के पहले छमाही (H1) और दूसरे छमाही (H2) में चार हवाई अड्डों द्वारा संभाले गए यात्री (लाख में) — दिल्ली: 340, 380; मुंबई: 300, 330; बेंगलुरु: 180, 216; चेन्नई: 120, 132। दिल्ली के H2 के यात्री घरेलू और अंतरराष्ट्रीय में 15 : 4 के अनुपात में थे। प्रत्येक घरेलू यात्री पर ₹200 और प्रत्येक अंतरराष्ट्रीय यात्री पर ₹600 का उपयोगकर्ता शुल्क लगता है। H2 में दिल्ली में कुल कितना शुल्क एकत्र हुआ?","optionsHi":["₹1,080 करोड़","₹1,200 करोड़","₹960 करोड़","₹10.8 करोड़"],"explanationHi":"380 लाख को 15 : 4 में बाँटने पर 300 लाख घरेलू और 80 लाख अंतरराष्ट्रीय होते हैं। शुल्क = 300 लाख × 200 + 80 लाख × 600 = 60,000 लाख + 48,000 लाख = 1,08,000 लाख = ₹1,080 करोड़।","subtopic":"tables"},
  {"id":"quant-data-interpretation-109","question":"A school's board results, with some cells missing — Class IX: appeared 240, passed 210; Class X: appeared ?, passed 216, pass rate 90%; Class XI: appeared 200, passed ?, pass rate 85%; Class XII: appeared 180, passed 153. What is the overall pass percentage of the four classes (correct to two decimals)?","options":["87.5%","87.09%","86.88%","88.4%"],"answer":1,"explanation":"Class X appeared = 216/0.9 = 240; Class XI passed = 85% of 200 = 170. Passed 749 out of 860 = 87.09%. 86.88% averages the four pass rates without weighting.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक विद्यालय के बोर्ड परिणाम, कुछ खाने छूटे हुए हैं — कक्षा IX: बैठे 240, उत्तीर्ण 210; कक्षा X: बैठे ?, उत्तीर्ण 216, उत्तीर्ण दर 90%; कक्षा XI: बैठे 200, उत्तीर्ण ?, उत्तीर्ण दर 85%; कक्षा XII: बैठे 180, उत्तीर्ण 153। चारों कक्षाओं का समग्र उत्तीर्ण प्रतिशत कितना है (दो दशमलव स्थानों तक सही)?","optionsHi":["87.5%","87.09%","86.88%","88.4%"],"explanationHi":"कक्षा X में बैठे = 216/0.9 = 240; कक्षा XI में उत्तीर्ण = 200 का 85% = 170। उत्तीर्ण 749, कुल 860 में से = 87.09%। 86.88% चारों उत्तीर्ण दरों का बिना भार का औसत है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-110","question":"A school's board results, with some cells missing — Class IX: appeared 240, passed 210; Class X: appeared ?, passed 216, pass rate 90%; Class XI: appeared 200, passed ?, pass rate 85%; Class XII: appeared 180, passed 153. The failed students of Classes X and XII take a re-test and two-thirds of them pass. What is the new overall pass percentage (correct to two decimals)?","options":["90.93%","89.53%","91.05%","92.5%"],"answer":2,"explanation":"Failed: X = 240 − 216 = 24, XII = 180 − 153 = 27, total 51; two-thirds = 34 pass. Passed = 749 + 34 = 783 out of 860 = 91.05%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक विद्यालय के बोर्ड परिणाम, कुछ खाने छूटे हुए हैं — कक्षा IX: बैठे 240, उत्तीर्ण 210; कक्षा X: बैठे ?, उत्तीर्ण 216, उत्तीर्ण दर 90%; कक्षा XI: बैठे 200, उत्तीर्ण ?, उत्तीर्ण दर 85%; कक्षा XII: बैठे 180, उत्तीर्ण 153। कक्षा X और XII के अनुत्तीर्ण विद्यार्थी पुनः परीक्षा देते हैं और उनमें से दो-तिहाई उत्तीर्ण हो जाते हैं। नया समग्र उत्तीर्ण प्रतिशत कितना है (दो दशमलव स्थानों तक सही)?","optionsHi":["90.93%","89.53%","91.05%","92.5%"],"explanationHi":"अनुत्तीर्ण: X = 240 − 216 = 24, XII = 180 − 153 = 27, कुल 51; दो-तिहाई = 34 उत्तीर्ण। उत्तीर्ण = 749 + 34 = 783, कुल 860 में से = 91.05%।","subtopic":"tables"},
  {"id":"quant-data-interpretation-111","question":"In a pie chart of the sales of five soap brands, Brand A's sector has a central angle of 72°. If Brand A sold 3,600 cartons, how many cartons did the five brands sell in all?","options":["15,000","25,920","12,960","18,000"],"answer":3,"explanation":"72° is 72/360 = 1/5 of the pie, so the total is 5 × 3,600 = 18,000 cartons.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"पाँच साबुन ब्रांडों की बिक्री के एक पाई चार्ट में ब्रांड A के खंड का केंद्रीय कोण 72° है। यदि ब्रांड A ने 3,600 कार्टन बेचे, तो पाँचों ब्रांडों ने कुल कितने कार्टन बेचे?","optionsHi":["15,000","25,920","12,960","18,000"],"explanationHi":"72° पाई का 72/360 = 1/5 है, अतः कुल = 5 × 3,600 = 18,000 कार्टन।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-112","question":"Sugarcane output of a state (lakh tonnes) — 2019: 50, 2020: 60, 2021: 54, 2022: 63, 2023: 70. In how many of these years was the output above the five-year average?","options":["3","2","4","1"],"answer":0,"explanation":"Average = 297/5 = 59.4 lakh tonnes. 2020 (60), 2022 (63) and 2023 (70) are above it: 3 years. 60 is easy to miss because it is only just above.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक राज्य का गन्ना उत्पादन (लाख टन में) — 2019: 50, 2020: 60, 2021: 54, 2022: 63, 2023: 70। इनमें से कितने वर्षों में उत्पादन पाँच वर्ष के औसत से अधिक था?","optionsHi":["3","2","4","1"],"explanationHi":"औसत = 297/5 = 59.4 लाख टन। 2020 (60), 2022 (63) और 2023 (70) इससे अधिक हैं: 3 वर्ष। 60 को चूकना आसान है क्योंकि वह औसत से केवल थोड़ा ही ऊपर है।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-113","question":"The price index of an item (base year 2020 = 100) — 2021: 110, 2022: 121, 2023: 133.1. If the item cost ₹2,662 in 2023, what did it cost in 2021?","options":["₹2,129.6","₹2,200","₹2,420","₹2,000"],"answer":1,"explanation":"Prices move in proportion to the index: 2,662 × 110/133.1 = 2,662/1.21 = ₹2,200. ₹2,000 is the 2020 price, and ₹2,129.6 wrongly subtracts 20% from the 2023 price.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक वस्तु का मूल्य सूचकांक (आधार वर्ष 2020 = 100) — 2021: 110, 2022: 121, 2023: 133.1। यदि 2023 में वस्तु की कीमत ₹2,662 थी, तो 2021 में उसकी कीमत क्या थी?","optionsHi":["₹2,129.6","₹2,200","₹2,420","₹2,000"],"explanationHi":"कीमतें सूचकांक के अनुपात में चलती हैं: 2,662 × 110/133.1 = 2,662/1.21 = ₹2,200। ₹2,000 2020 की कीमत है, और ₹2,129.6 में 2023 की कीमत में से गलती से 20% घटा दिया गया है।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-114","question":"Of a district's 2,50,000 voters, 40% are under 30. In an election 70% of the under-30 voters and 60% of the other voters cast their votes. What percentage of the votes cast came from under-30 voters?","options":["40%","46.67%","43.75%","70%"],"answer":2,"explanation":"Under-30 votes = 0.7 × 1,00,000 = 70,000; others = 0.6 × 1,50,000 = 90,000. Share = 70,000/1,60,000 = 43.75%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक जिले के 2,50,000 मतदाताओं में से 40% की आयु 30 वर्ष से कम है। एक चुनाव में 30 वर्ष से कम आयु के 70% मतदाताओं और अन्य मतदाताओं के 60% ने मतदान किया। डाले गए मतों का कितना प्रतिशत 30 वर्ष से कम आयु के मतदाताओं से आया?","optionsHi":["40%","46.67%","43.75%","70%"],"explanationHi":"30 वर्ष से कम आयु के मत = 0.7 × 1,00,000 = 70,000; अन्य = 0.6 × 1,50,000 = 90,000। हिस्सा = 70,000/1,60,000 = 43.75%।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-115","question":"Marks of 200 candidates — 0–20: 18, 20–40: 34, 40–60: 62, 60–80: 56, 80–100: 30. Assume half of the 40–60 group scored 50 or more. If the qualifying cut-off is lowered from 60 to 50 marks, by what percentage does the number of qualifying candidates increase (correct to two decimals)?","options":["31%","26.5%","15.5%","36.05%"],"answer":3,"explanation":"At 60: 56 + 30 = 86 qualify. Lowering to 50 adds half of 62 = 31. Increase = 31/86 = 36.05%. 26.5% divides by the new count and 15.5% by all 200.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"200 अभ्यर्थियों के अंक — 0–20: 18, 20–40: 34, 40–60: 62, 60–80: 56, 80–100: 30। मान लें कि 40–60 वाले समूह के आधे अभ्यर्थियों ने 50 या अधिक अंक प्राप्त किए। यदि अर्हता कट-ऑफ 60 अंक से घटाकर 50 अंक कर दिया जाए, तो अर्हता प्राप्त करने वाले अभ्यर्थियों की संख्या में कितने प्रतिशत की वृद्धि होगी (दो दशमलव स्थानों तक सही)?","optionsHi":["31%","26.5%","15.5%","36.05%"],"explanationHi":"60 पर: 56 + 30 = 86 अर्हता प्राप्त करते हैं। 50 करने पर 62 का आधा = 31 और जुड़ते हैं। वृद्धि = 31/86 = 36.05%। 26.5% में नई संख्या से भाग दिया गया है और 15.5% में कुल 200 से।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-116","question":"Two-wheelers sold by a showroom — January: 120, February: 140, March: 175, April: 210. In which month was the percentage increase in sales over the previous month the highest?","options":["March","April","February","Both March and April"],"answer":0,"explanation":"February: 20/120 = 16.7%; March: 35/140 = 25%; April: 35/175 = 20%. March and April have the same absolute rise, but March's smaller base gives the higher percentage.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक शोरूम द्वारा बेचे गए दोपहिया वाहन — जनवरी: 120, फरवरी: 140, मार्च: 175, अप्रैल: 210। किस महीने में बिक्री में पिछले महीने की तुलना में प्रतिशत वृद्धि सबसे अधिक रही?","optionsHi":["मार्च","अप्रैल","फरवरी","मार्च और अप्रैल दोनों"],"explanationHi":"फरवरी: 20/120 = 16.7%; मार्च: 35/140 = 25%; अप्रैल: 35/175 = 20%। मार्च और अप्रैल में निरपेक्ष वृद्धि समान है, पर मार्च का छोटा आधार उसे अधिक प्रतिशत देता है।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-117","question":"A firm's income-to-expenditure ratio was 5 : 4 in 2022 and 7 : 5 in 2023. Its income rose by 40% from 2022 to 2023. By what percentage did its expenditure rise?","options":["40%","25%","12.5%","20%"],"answer":1,"explanation":"Take 2022 income = 5k, so 2023 income = 7k (a 40% rise), and the ratios give expenditure 4k and then 5k. Rise = k/4k = 25%.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक फर्म की आय और व्यय का अनुपात 2022 में 5 : 4 था और 2023 में 7 : 5। 2022 से 2023 तक उसकी आय में 40% की वृद्धि हुई। उसके व्यय में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["40%","25%","12.5%","20%"],"explanationHi":"2022 की आय = 5k लें, तो 2023 की आय = 7k (40% की वृद्धि), और अनुपातों से व्यय पहले 4k और फिर 5k होता है। वृद्धि = k/4k = 25%।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-118","question":"Profit % is defined as (Income − Expenditure)/Expenditure × 100. In 2022 a company's expenditure was ₹160 crore and its profit was 25%. In 2023 its income rose by 30% and its profit was 30%. What was its expenditure in 2023?","options":["₹208 crore","₹182 crore","₹200 crore","₹192 crore"],"answer":2,"explanation":"Income 2022 = 160 × 1.25 = 200, so income 2023 = 260. Expenditure 2023 = 260/1.30 = ₹200 crore. ₹182 crore wrongly takes 30% off the income instead of dividing by 1.3.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"लाभ % को (आय − व्यय)/व्यय × 100 के रूप में परिभाषित किया गया है। 2022 में एक कंपनी का व्यय ₹160 करोड़ था और उसका लाभ 25% था। 2023 में उसकी आय में 30% की वृद्धि हुई और उसका लाभ 30% था। 2023 में उसका व्यय कितना था?","optionsHi":["₹208 करोड़","₹182 करोड़","₹200 करोड़","₹192 करोड़"],"explanationHi":"2022 की आय = 160 × 1.25 = 200, अतः 2023 की आय = 260। 2023 का व्यय = 260/1.30 = ₹200 करोड़। ₹182 करोड़ में 1.3 से भाग देने की जगह आय में से 30% घटा दिया गया है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-119","question":"Attendance in a class over a week — Monday: 42, Tuesday: 38, Wednesday: 45, Thursday: 40, Friday: 35. What is the average daily attendance?","options":["41.25","50","33.33","40"],"answer":3,"explanation":"Total = 42 + 38 + 45 + 40 + 35 = 200 over 5 days, so the average is 40. 50 divides by 4, 33.33 divides by 6 as if the week had six school days, and 41.25 wrongly drops Friday's low figure.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक कक्षा में एक सप्ताह की उपस्थिति — सोमवार: 42, मंगलवार: 38, बुधवार: 45, गुरुवार: 40, शुक्रवार: 35। औसत दैनिक उपस्थिति कितनी है?","optionsHi":["41.25","50","33.33","40"],"explanationHi":"कुल = 42 + 38 + 45 + 40 + 35 = 200, 5 दिनों में, अतः औसत 40 है। 50 में 4 से भाग दिया गया है, 33.33 में 6 से भाग दिया गया है मानो सप्ताह में छह स्कूल दिन हों, और 41.25 में शुक्रवार का कम आँकड़ा गलती से छोड़ दिया गया है।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-120","question":"In 2022 a state's budget was ₹1,20,000 crore, of which Education got 18%. In 2023 the budget grew by 15% while the Education allocation grew by 25%. What was Education's share of the 2023 budget (correct to two decimals)?","options":["19.57%","22.5%","20.7%","19.25%"],"answer":0,"explanation":"New share = 18% × 1.25/1.15 = 22.5/1.15 = 19.57%. The budget size cancels out. 22.5% forgets that the whole budget also grew.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"2022 में एक राज्य का बजट ₹1,20,000 करोड़ था, जिसमें से शिक्षा को 18% मिला। 2023 में बजट 15% बढ़ा जबकि शिक्षा का आवंटन 25% बढ़ा। 2023 के बजट में शिक्षा का हिस्सा कितना था (दो दशमलव स्थानों तक सही)?","optionsHi":["19.57%","22.5%","20.7%","19.25%"],"explanationHi":"नया हिस्सा = 18% × 1.25/1.15 = 22.5/1.15 = 19.57%। बजट का आकार कट जाता है। 22.5% में यह भूल गया है कि पूरा बजट भी बढ़ा है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-121","question":"Capacity (lakh tonnes) and capacity utilisation of five steel plants — Plant P: 50, 80%; Plant Q: 40, 90%; Plant R: 45, 60%; Plant S: 25, 84%; Plant T: 15, 70%. What was the production of Plant Q?","options":["40 lakh tonnes","36 lakh tonnes","32 lakh tonnes","44 lakh tonnes"],"answer":1,"explanation":"Production = capacity × utilisation = 40 × 0.9 = 36 lakh tonnes.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"पाँच इस्पात संयंत्रों की क्षमता (लाख टन में) और क्षमता उपयोग — संयंत्र P: 50, 80%; संयंत्र Q: 40, 90%; संयंत्र R: 45, 60%; संयंत्र S: 25, 84%; संयंत्र T: 15, 70%। संयंत्र Q का उत्पादन कितना था?","optionsHi":["40 लाख टन","36 लाख टन","32 लाख टन","44 लाख टन"],"explanationHi":"उत्पादन = क्षमता × उपयोग = 40 × 0.9 = 36 लाख टन।","subtopic":"tables"},
  {"id":"quant-data-interpretation-122","question":"Capacity (lakh tonnes) and capacity utilisation of five steel plants — Plant P: 50, 80%; Plant Q: 40, 90%; Plant R: 45, 60%; Plant S: 25, 84%; Plant T: 15, 70%. What is the overall capacity utilisation of the five plants (correct to two decimals)?","options":["76.8%","80%","76.86%","78.4%"],"answer":2,"explanation":"Production = 40 + 36 + 27 + 21 + 10.5 = 134.5 out of a capacity of 175, i.e. 76.86%. 76.8% is the unweighted average of the five percentages.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"पाँच इस्पात संयंत्रों की क्षमता (लाख टन में) और क्षमता उपयोग — संयंत्र P: 50, 80%; संयंत्र Q: 40, 90%; संयंत्र R: 45, 60%; संयंत्र S: 25, 84%; संयंत्र T: 15, 70%। पाँचों संयंत्रों का समग्र क्षमता उपयोग कितना है (दो दशमलव स्थानों तक सही)?","optionsHi":["76.8%","80%","76.86%","78.4%"],"explanationHi":"उत्पादन = 40 + 36 + 27 + 21 + 10.5 = 134.5, 175 की क्षमता में से, अर्थात् 76.86%। 76.8% पाँचों प्रतिशतों का बिना भार का औसत है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-123","question":"Capacity (lakh tonnes) and capacity utilisation of five steel plants — Plant P: 50, 80%; Plant Q: 40, 90%; Plant R: 45, 60%; Plant S: 25, 84%; Plant T: 15, 70%. Which plant has the largest unused capacity in absolute terms?","options":["Plant P","Plant T","Plant Q","Plant R"],"answer":3,"explanation":"Unused = capacity − production: P 10, Q 4, R 18, S 4, T 4.5 lakh tonnes. R's 40% idle share of a large capacity is the biggest.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"पाँच इस्पात संयंत्रों की क्षमता (लाख टन में) और क्षमता उपयोग — संयंत्र P: 50, 80%; संयंत्र Q: 40, 90%; संयंत्र R: 45, 60%; संयंत्र S: 25, 84%; संयंत्र T: 15, 70%। किस संयंत्र की अप्रयुक्त क्षमता निरपेक्ष रूप में सबसे अधिक है?","optionsHi":["संयंत्र P","संयंत्र T","संयंत्र Q","संयंत्र R"],"explanationHi":"अप्रयुक्त = क्षमता − उत्पादन: P 10, Q 4, R 18, S 4, T 4.5 लाख टन। बड़ी क्षमता में R का 40% निष्क्रिय हिस्सा सबसे बड़ा है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-124","question":"Capacity (lakh tonnes) and capacity utilisation of five steel plants — Plant P: 50, 80%; Plant Q: 40, 90%; Plant R: 45, 60%; Plant S: 25, 84%; Plant T: 15, 70%. Next year Plant R raises its utilisation to 80% while Plant P's falls to 75%, the rest unchanged. By what percentage does total production rise (correct to two decimals)?","options":["4.83%","5%","6.5%","4.6%"],"answer":0,"explanation":"R gains 20% of 45 = 9 and P loses 5% of 50 = 2.5, a net gain of 6.5 on 134.5: 6.5/134.5 = 4.83%. 6.5% confuses lakh tonnes with percent.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"पाँच इस्पात संयंत्रों की क्षमता (लाख टन में) और क्षमता उपयोग — संयंत्र P: 50, 80%; संयंत्र Q: 40, 90%; संयंत्र R: 45, 60%; संयंत्र S: 25, 84%; संयंत्र T: 15, 70%। अगले वर्ष संयंत्र R अपना उपयोग 80% तक बढ़ा लेता है जबकि संयंत्र P का उपयोग 75% तक गिर जाता है, शेष अपरिवर्तित रहते हैं। कुल उत्पादन कितने प्रतिशत बढ़ता है (दो दशमलव स्थानों तक सही)?","optionsHi":["4.83%","5%","6.5%","4.6%"],"explanationHi":"R को 45 का 20% = 9 का लाभ होता है और P को 50 का 5% = 2.5 की हानि, अर्थात् 134.5 पर 6.5 का शुद्ध लाभ: 6.5/134.5 = 4.83%। 6.5% में लाख टन को प्रतिशत समझ लिया गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-125","question":"Capacity (lakh tonnes) and capacity utilisation of five steel plants — Plant P: 50, 80%; Plant Q: 40, 90%; Plant R: 45, 60%; Plant S: 25, 84%; Plant T: 15, 70%. What is the ratio of the combined production of Plants P and S to that of Plants Q and T?","options":["15 : 11","122 : 93","93 : 122","61 : 45"],"answer":1,"explanation":"P + S = 40 + 21 = 61 and Q + T = 36 + 10.5 = 46.5. 61 : 46.5 = 122 : 93. 15 : 11 compares capacities (75 : 55), not production.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"पाँच इस्पात संयंत्रों की क्षमता (लाख टन में) और क्षमता उपयोग — संयंत्र P: 50, 80%; संयंत्र Q: 40, 90%; संयंत्र R: 45, 60%; संयंत्र S: 25, 84%; संयंत्र T: 15, 70%। संयंत्र P और S के संयुक्त उत्पादन तथा संयंत्र Q और T के संयुक्त उत्पादन का अनुपात कितना है?","optionsHi":["15 : 11","122 : 93","93 : 122","61 : 45"],"explanationHi":"P + S = 40 + 21 = 61 और Q + T = 36 + 10.5 = 46.5। 61 : 46.5 = 122 : 93। 15 : 11 क्षमताओं (75 : 55) की तुलना है, उत्पादन की नहीं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-126","question":"Capacity (lakh tonnes) and capacity utilisation of five steel plants — Plant P: 50, 80%; Plant Q: 40, 90%; Plant R: 45, 60%; Plant S: 25, 84%; Plant T: 15, 70%. If every plant's capacity is raised by 20% next year while production stays the same, what will the overall utilisation be (correct to two decimals)?","options":["61.49%","56.86%","64.05%","60%"],"answer":2,"explanation":"New capacity = 175 × 1.2 = 210, so utilisation = 134.5/210 = 64.05% (76.86% ÷ 1.2). Subtracting 20 points (56.86%) is the trap.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"पाँच इस्पात संयंत्रों की क्षमता (लाख टन में) और क्षमता उपयोग — संयंत्र P: 50, 80%; संयंत्र Q: 40, 90%; संयंत्र R: 45, 60%; संयंत्र S: 25, 84%; संयंत्र T: 15, 70%। यदि अगले वर्ष प्रत्येक संयंत्र की क्षमता 20% बढ़ा दी जाए जबकि उत्पादन वही रहे, तो समग्र उपयोग कितना होगा (दो दशमलव स्थानों तक सही)?","optionsHi":["61.49%","56.86%","64.05%","60%"],"explanationHi":"नई क्षमता = 175 × 1.2 = 210, अतः उपयोग = 134.5/210 = 64.05% (76.86% ÷ 1.2)। 20 अंक घटाना (56.86%) जाल है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-127","question":"Two-wheelers sold (thousand units) by a company in the four quarters of a year — Domestic: Q1 45, Q2 60, Q3 75, Q4 90; Export: Q1 15, Q2 20, Q3 18, Q4 30. What share of the total sales in Q4 came from exports?","options":["33.33%","30%","20%","25%"],"answer":3,"explanation":"Q4 total = 90 + 30 = 120, and 30/120 = 25%. 33.33% compares exports with domestic sales instead of the total.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक कंपनी द्वारा एक वर्ष की चार तिमाहियों में बेचे गए दोपहिया वाहन (हज़ार इकाइयाँ) — घरेलू: Q1 45, Q2 60, Q3 75, Q4 90; निर्यात: Q1 15, Q2 20, Q3 18, Q4 30। Q4 की कुल बिक्री में निर्यात का हिस्सा कितना था?","optionsHi":["33.33%","30%","20%","25%"],"explanationHi":"Q4 का कुल = 90 + 30 = 120, और 30/120 = 25%। 33.33% में निर्यात की तुलना कुल से करने की जगह घरेलू बिक्री से की गई है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-128","question":"Two-wheelers sold (thousand units) by a company in the four quarters of a year — Domestic: Q1 45, Q2 60, Q3 75, Q4 90; Export: Q1 15, Q2 20, Q3 18, Q4 30. In which quarter was the share of exports in total sales the lowest?","options":["Q3","Q1","Q2","Q4"],"answer":0,"explanation":"Export shares: Q1 15/60 = 25%, Q2 20/80 = 25%, Q3 18/93 ≈ 19.4%, Q4 30/120 = 25%. Only Q3 dips.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक कंपनी द्वारा एक वर्ष की चार तिमाहियों में बेचे गए दोपहिया वाहन (हज़ार इकाइयाँ) — घरेलू: Q1 45, Q2 60, Q3 75, Q4 90; निर्यात: Q1 15, Q2 20, Q3 18, Q4 30। किस तिमाही में कुल बिक्री में निर्यात का हिस्सा सबसे कम था?","optionsHi":["Q3","Q1","Q2","Q4"],"explanationHi":"निर्यात के हिस्से: Q1 15/60 = 25%, Q2 20/80 = 25%, Q3 18/93 ≈ 19.4%, Q4 30/120 = 25%। केवल Q3 में गिरावट है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-129","question":"Two-wheelers sold (thousand units) by a company in the four quarters of a year — Domestic: Q1 45, Q2 60, Q3 75, Q4 90; Export: Q1 15, Q2 20, Q3 18, Q4 30. By what percentage were total sales in the second half of the year higher than in the first half (correct to two decimals)?","options":["34.27%","52.14%","73%","50%"],"answer":1,"explanation":"First half = 60 + 80 = 140; second half = 93 + 120 = 213. Rise = 73/140 = 52.14%. 34.27% uses 213 as the base.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक कंपनी द्वारा एक वर्ष की चार तिमाहियों में बेचे गए दोपहिया वाहन (हज़ार इकाइयाँ) — घरेलू: Q1 45, Q2 60, Q3 75, Q4 90; निर्यात: Q1 15, Q2 20, Q3 18, Q4 30। वर्ष की दूसरी छमाही में कुल बिक्री पहली छमाही से कितने प्रतिशत अधिक थी (दो दशमलव स्थानों तक सही)?","optionsHi":["34.27%","52.14%","73%","50%"],"explanationHi":"पहली छमाही = 60 + 80 = 140; दूसरी छमाही = 93 + 120 = 213। वृद्धि = 73/140 = 52.14%। 34.27% में आधार 213 लिया गया है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-130","question":"Two-wheelers sold (thousand units) by a company in the four quarters of a year — Domestic: Q1 45, Q2 60, Q3 75, Q4 90; Export: Q1 15, Q2 20, Q3 18, Q4 30. The average price is ₹80,000 per domestic unit and ₹1,00,000 per exported unit. What is the company's sales revenue for the year?","options":["₹2,160 crore","₹3,530 crore","₹2,990 crore","₹299 crore"],"answer":2,"explanation":"Domestic 270 thousand × ₹80,000 = ₹2,160 crore; export 83 thousand × ₹1,00,000 = ₹830 crore. Total ₹2,990 crore (1 crore = 10⁷).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कंपनी द्वारा एक वर्ष की चार तिमाहियों में बेचे गए दोपहिया वाहन (हज़ार इकाइयाँ) — घरेलू: Q1 45, Q2 60, Q3 75, Q4 90; निर्यात: Q1 15, Q2 20, Q3 18, Q4 30। औसत मूल्य ₹80,000 प्रति घरेलू इकाई और ₹1,00,000 प्रति निर्यातित इकाई है। वर्ष के लिए कंपनी का बिक्री राजस्व कितना है?","optionsHi":["₹2,160 करोड़","₹3,530 करोड़","₹2,990 करोड़","₹299 करोड़"],"explanationHi":"घरेलू 270 हज़ार × ₹80,000 = ₹2,160 करोड़; निर्यात 83 हज़ार × ₹1,00,000 = ₹830 करोड़। कुल ₹2,990 करोड़ (1 करोड़ = 10⁷)।","subtopic":"tables"},
  {"id":"quant-data-interpretation-131","question":"Two-wheelers sold (thousand units) by a company in the four quarters of a year — Domestic: Q1 45, Q2 60, Q3 75, Q4 90; Export: Q1 15, Q2 20, Q3 18, Q4 30. Next year domestic sales rise by 10% and export sales fall by 20% in every quarter. By how many thousand units does the annual total change?","options":["Down by 10.4","Up by 27","Down by 16.6","Up by 10.4"],"answer":3,"explanation":"Domestic gains 10% of 270 = 27; exports lose 20% of 83 = 16.6. Net change = +10.4 thousand units.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कंपनी द्वारा एक वर्ष की चार तिमाहियों में बेचे गए दोपहिया वाहन (हज़ार इकाइयाँ) — घरेलू: Q1 45, Q2 60, Q3 75, Q4 90; निर्यात: Q1 15, Q2 20, Q3 18, Q4 30। अगले वर्ष प्रत्येक तिमाही में घरेलू बिक्री 10% बढ़ती है और निर्यात बिक्री 20% घटती है। वार्षिक कुल में कितने हज़ार इकाइयों का परिवर्तन होता है?","optionsHi":["10.4 की कमी","27 की वृद्धि","16.6 की कमी","10.4 की वृद्धि"],"explanationHi":"घरेलू में 270 का 10% = 27 का लाभ होता है; निर्यात में 83 का 20% = 16.6 की हानि होती है। शुद्ध परिवर्तन = +10.4 हज़ार इकाइयाँ।","subtopic":"tables"},
  {"id":"quant-data-interpretation-132","question":"A firm has 2,400 employees, of whom 900 are women. Department-wise share of all employees and of women employees — Production: 35%, 20%; Sales: 25%, 30%; Accounts: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%. How many men work in Sales?","options":["330","270","600","360"],"answer":0,"explanation":"Sales staff = 25% of 2,400 = 600; women in Sales = 30% of 900 = 270. Men = 330.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक फर्म में 2,400 कर्मचारी हैं, जिनमें 900 महिलाएँ हैं। सभी कर्मचारियों और महिला कर्मचारियों का विभागवार हिस्सा — उत्पादन: 35%, 20%; बिक्री: 25%, 30%; लेखा: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%। बिक्री विभाग में कितने पुरुष कार्य करते हैं?","optionsHi":["330","270","600","360"],"explanationHi":"बिक्री कर्मचारी = 2,400 का 25% = 600; बिक्री में महिलाएँ = 900 का 30% = 270। पुरुष = 330।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-133","question":"A firm has 2,400 employees, of whom 900 are women. Department-wise share of all employees and of women employees — Production: 35%, 20%; Sales: 25%, 30%; Accounts: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%. In which department do women make up the highest percentage of the staff?","options":["Accounts","HR","Sales","IT"],"answer":1,"explanation":"Women/staff: Production 180/840 ≈ 21%, Sales 270/600 = 45%, Accounts 180/360 = 50%, HR 135/240 = 56.25%, IT 135/360 = 37.5%. Sales has the most women but HR has the highest share.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक फर्म में 2,400 कर्मचारी हैं, जिनमें 900 महिलाएँ हैं। सभी कर्मचारियों और महिला कर्मचारियों का विभागवार हिस्सा — उत्पादन: 35%, 20%; बिक्री: 25%, 30%; लेखा: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%। किस विभाग में महिलाएँ कर्मचारियों का सबसे अधिक प्रतिशत हैं?","optionsHi":["लेखा","HR","बिक्री","IT"],"explanationHi":"महिलाएँ/कर्मचारी: उत्पादन 180/840 ≈ 21%, बिक्री 270/600 = 45%, लेखा 180/360 = 50%, HR 135/240 = 56.25%, IT 135/360 = 37.5%। बिक्री में महिलाओं की संख्या सबसे अधिक है पर HR में उनका हिस्सा सबसे अधिक है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-134","question":"A firm has 2,400 employees, of whom 900 are women. Department-wise share of all employees and of women employees — Production: 35%, 20%; Sales: 25%, 30%; Accounts: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%. What is the ratio of men in Production to men in IT?","options":["7 : 3","4 : 3","44 : 15","15 : 44"],"answer":2,"explanation":"Men: Production 840 − 180 = 660, IT 360 − 135 = 225. 660 : 225 = 44 : 15. 7 : 3 compares total staff (840 : 360).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक फर्म में 2,400 कर्मचारी हैं, जिनमें 900 महिलाएँ हैं। सभी कर्मचारियों और महिला कर्मचारियों का विभागवार हिस्सा — उत्पादन: 35%, 20%; बिक्री: 25%, 30%; लेखा: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%। उत्पादन के पुरुषों और IT के पुरुषों का अनुपात कितना है?","optionsHi":["7 : 3","4 : 3","44 : 15","15 : 44"],"explanationHi":"पुरुष: उत्पादन 840 − 180 = 660, IT 360 − 135 = 225। 660 : 225 = 44 : 15। 7 : 3 कुल कर्मचारियों (840 : 360) की तुलना है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-135","question":"A firm has 2,400 employees, of whom 900 are women. Department-wise share of all employees and of women employees — Production: 35%, 20%; Sales: 25%, 30%; Accounts: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%. If 20% of the men in Production are transferred to IT, what percentage of IT's staff will then be women (correct to two decimals)?","options":["37.5%","24.39%","30%","27.44%"],"answer":3,"explanation":"20% of 660 = 132 men move, so IT has 360 + 132 = 492 people, of whom 135 are women: 135/492 = 27.44%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक फर्म में 2,400 कर्मचारी हैं, जिनमें 900 महिलाएँ हैं। सभी कर्मचारियों और महिला कर्मचारियों का विभागवार हिस्सा — उत्पादन: 35%, 20%; बिक्री: 25%, 30%; लेखा: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%। यदि उत्पादन के 20% पुरुषों को IT में स्थानांतरित कर दिया जाए, तो तब IT के कर्मचारियों का कितना प्रतिशत महिलाएँ होंगी (दो दशमलव स्थानों तक सही)?","optionsHi":["37.5%","24.39%","30%","27.44%"],"explanationHi":"660 का 20% = 132 पुरुष स्थानांतरित होते हैं, इसलिए IT में 360 + 132 = 492 लोग हो जाते हैं, जिनमें 135 महिलाएँ हैं: 135/492 = 27.44%।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-136","question":"A firm has 2,400 employees, of whom 900 are women. Department-wise share of all employees and of women employees — Production: 35%, 20%; Sales: 25%, 30%; Accounts: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%. Women in Accounts and HR together are what percentage of the men in those two departments (correct to two decimals)?","options":["110.53%","90.48%","52.5%","105%"],"answer":0,"explanation":"Women = 180 + 135 = 315; men = (360 − 180) + (240 − 135) = 285. 315/285 = 110.53%. 90.48% inverts the ratio.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक फर्म में 2,400 कर्मचारी हैं, जिनमें 900 महिलाएँ हैं। सभी कर्मचारियों और महिला कर्मचारियों का विभागवार हिस्सा — उत्पादन: 35%, 20%; बिक्री: 25%, 30%; लेखा: 15%, 20%; HR: 10%, 15%; IT: 15%, 15%। लेखा और HR की महिलाएँ मिलकर उन दोनों विभागों के पुरुषों का कितना प्रतिशत हैं (दो दशमलव स्थानों तक सही)?","optionsHi":["110.53%","90.48%","52.5%","105%"],"explanationHi":"महिलाएँ = 180 + 135 = 315; पुरुष = (360 − 180) + (240 − 135) = 285। 315/285 = 110.53%। 90.48% अनुपात को उलट देता है।","subtopic":"mixed-graphs"},
  {"id":"quant-data-interpretation-137","question":"A bookshop sold 1,500 books in April, of which 40% were exam guides and the rest fiction and non-fiction in the ratio 5 : 4. In May its total sales rose by 20%, exam-guide sales rose by 50% and non-fiction sales fell by 10%. By what percentage did fiction sales change from April to May?","options":["20% increase","8% increase","10% decrease","10% increase"],"answer":1,"explanation":"April: guides 600, fiction 500, non-fiction 400. May: total 1,800, guides 900, non-fiction 360, so fiction = 540, up 40/500 = 8%.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक पुस्तक की दुकान ने अप्रैल में 1,500 पुस्तकें बेचीं, जिनमें 40% परीक्षा गाइड थीं और शेष कथा और अकथा 5 : 4 के अनुपात में थीं। मई में उसकी कुल बिक्री 20% बढ़ी, परीक्षा गाइड की बिक्री 50% बढ़ी और अकथा की बिक्री 10% घटी। अप्रैल से मई तक कथा की बिक्री में कितने प्रतिशत का परिवर्तन हुआ?","optionsHi":["20% वृद्धि","8% वृद्धि","10% कमी","10% वृद्धि"],"explanationHi":"अप्रैल: गाइड 600, कथा 500, अकथा 400। मई: कुल 1,800, गाइड 900, अकथा 360, अतः कथा = 540, यानी 40/500 = 8% की वृद्धि।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-138","question":"A bookshop sold 1,500 books in April, of which 40% were exam guides and the rest fiction and non-fiction in the ratio 5 : 4. In May its total sales rose by 20%, exam-guide sales rose by 50% and non-fiction sales fell by 10%. In May the average prices were ₹300 for fiction, ₹450 for non-fiction and ₹250 for exam guides. What share of May's revenue came from exam guides (correct to two decimals)?","options":["50%","45.45%","40.98%","33.33%"],"answer":2,"explanation":"Guides ₹2,25,000; fiction 540 × 300 = ₹1,62,000; non-fiction 360 × 450 = ₹1,62,000. Share = 2,25,000/5,49,000 = 40.98%. 50% is the share by number of books.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक पुस्तक की दुकान ने अप्रैल में 1,500 पुस्तकें बेचीं, जिनमें 40% परीक्षा गाइड थीं और शेष कथा और अकथा 5 : 4 के अनुपात में थीं। मई में उसकी कुल बिक्री 20% बढ़ी, परीक्षा गाइड की बिक्री 50% बढ़ी और अकथा की बिक्री 10% घटी। मई में औसत मूल्य कथा के लिए ₹300, अकथा के लिए ₹450 और परीक्षा गाइड के लिए ₹250 थे। मई के राजस्व का कितना हिस्सा परीक्षा गाइड से आया (दो दशमलव स्थानों तक सही)?","optionsHi":["50%","45.45%","40.98%","33.33%"],"explanationHi":"गाइड ₹2,25,000; कथा 540 × 300 = ₹1,62,000; अकथा 360 × 450 = ₹1,62,000। हिस्सा = 2,25,000/5,49,000 = 40.98%। 50% पुस्तकों की संख्या के आधार पर हिस्सा है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-139","question":"Fixed deposit rates (% per annum) of four banks for 1-year and 2-year deposits — Bank A: 6, 6.5; Bank B: 6.5, 7; Bank C: 7, 7.25; Bank D: 5.5, 7.5. Interest on 2-year deposits is compounded annually. What interest does ₹50,000 earn in a 2-year deposit with Bank C?","options":["₹7,250","₹7,000","₹7,875","₹7,512.81"],"answer":3,"explanation":"Amount = 50,000 × 1.0725² = 57,512.81, so interest = ₹7,512.81. ₹7,250 is simple interest at 7.25% for 2 years.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"चार बैंकों की 1 वर्ष और 2 वर्ष की सावधि जमा की दरें (% वार्षिक) — बैंक A: 6, 6.5; बैंक B: 6.5, 7; बैंक C: 7, 7.25; बैंक D: 5.5, 7.5। 2 वर्ष की जमा पर ब्याज वार्षिक रूप से संयोजित होता है। बैंक C में 2 वर्ष की जमा में ₹50,000 पर कितना ब्याज मिलता है?","optionsHi":["₹7,250","₹7,000","₹7,875","₹7,512.81"],"explanationHi":"मिश्रधन = 50,000 × 1.0725² = 57,512.81, अतः ब्याज = ₹7,512.81। ₹7,250 7.25% पर 2 वर्ष का साधारण ब्याज है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-140","question":"Fixed deposit rates (% per annum) of four banks for 1-year and 2-year deposits — Bank A: 6, 6.5; Bank B: 6.5, 7; Bank C: 7, 7.25; Bank D: 5.5, 7.5. Interest on 2-year deposits is compounded annually. Ravi puts ₹1,00,000 in Bank B's 1-year deposit and reinvests the whole amount for another year at the same rate. Mohan puts ₹1,00,000 in Bank D's 2-year deposit. How much more does Mohan earn?","options":["₹2,140","₹2,000","₹1,000","₹2,250"],"answer":0,"explanation":"Ravi: 1,00,000 × 1.065² = 1,13,422.50. Mohan: 1,00,000 × 1.075² = 1,15,562.50. Difference = ₹2,140.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"चार बैंकों की 1 वर्ष और 2 वर्ष की सावधि जमा की दरें (% वार्षिक) — बैंक A: 6, 6.5; बैंक B: 6.5, 7; बैंक C: 7, 7.25; बैंक D: 5.5, 7.5। 2 वर्ष की जमा पर ब्याज वार्षिक रूप से संयोजित होता है। रवि ₹1,00,000 को बैंक B की 1 वर्ष की जमा में रखता है और पूरी राशि को उसी दर पर एक और वर्ष के लिए पुनः निवेश करता है। मोहन ₹1,00,000 को बैंक D की 2 वर्ष की जमा में रखता है। मोहन कितना अधिक कमाता है?","optionsHi":["₹2,140","₹2,000","₹1,000","₹2,250"],"explanationHi":"रवि: 1,00,000 × 1.065² = 1,13,422.50। मोहन: 1,00,000 × 1.075² = 1,15,562.50। अंतर = ₹2,140।","subtopic":"tables"},
  {"id":"quant-data-interpretation-141","question":"Agriculture contributes 30% of a state's GDP of ₹6 lakh crore. What is the value of its agricultural output?","options":["₹18 lakh crore","₹1.8 lakh crore","₹2 lakh crore","₹0.18 lakh crore"],"answer":1,"explanation":"30% of ₹6 lakh crore = 0.3 × 6 = ₹1.8 lakh crore. ₹18 lakh crore multiplies by 3 instead of 0.3, and ₹0.18 lakh crore slips a decimal place the other way.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"किसी राज्य के ₹6 लाख करोड़ के GDP में कृषि का योगदान 30% है। उसके कृषि उत्पादन का मूल्य कितना है?","optionsHi":["₹18 लाख करोड़","₹1.8 लाख करोड़","₹2 लाख करोड़","₹0.18 लाख करोड़"],"explanationHi":"₹6 लाख करोड़ का 30% = 0.3 × 6 = ₹1.8 लाख करोड़। ₹18 लाख करोड़ में 0.3 की जगह 3 से गुणा किया गया है, और ₹0.18 लाख करोड़ में दशमलव दूसरी ओर खिसक गया है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-142","question":"Maximum temperatures (°C) of a city from Monday to Friday — 32, 35, 31, 36, 34. What is the range of these readings?","options":["4 °C","36 °C","5 °C","33.6 °C"],"answer":2,"explanation":"Range = highest − lowest = 36 − 31 = 5 °C. 33.6 °C is the mean.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक शहर का सोमवार से शुक्रवार तक का अधिकतम तापमान (°C में) — 32, 35, 31, 36, 34। इन आँकड़ों का परिसर (रेंज) कितना है?","optionsHi":["4 °C","36 °C","5 °C","33.6 °C"],"explanationHi":"परिसर = अधिकतम − न्यूनतम = 36 − 31 = 5 °C। 33.6 °C माध्य है।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-143","question":"Class A has 40 students with boys and girls in the ratio 3 : 5, and Class B has 45 students in the ratio 4 : 5. How many girls are there in the two classes together?","options":["45","55","40","50"],"answer":3,"explanation":"Class A girls = 40 × 5/8 = 25; Class B girls = 45 × 5/9 = 25. Total 50.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"कक्षा A में 40 विद्यार्थी हैं जिनमें लड़के और लड़कियाँ 3 : 5 के अनुपात में हैं, और कक्षा B में 45 विद्यार्थी हैं जिनका अनुपात 4 : 5 है। दोनों कक्षाओं में मिलाकर कितनी लड़कियाँ हैं?","optionsHi":["45","55","40","50"],"explanationHi":"कक्षा A की लड़कियाँ = 40 × 5/8 = 25; कक्षा B की लड़कियाँ = 45 × 5/9 = 25। कुल 50।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-144","question":"A company's average quarterly sales for a year were ₹60 lakh. Sales in Q1, Q2 and Q3 were ₹50 lakh, ₹55 lakh and ₹70 lakh. By what percentage were Q4 sales higher than Q1 sales?","options":["30%","15%","20%","23.08%"],"answer":0,"explanation":"Total = 4 × 60 = 240, so Q4 = 240 − 175 = 65. (65 − 50)/50 = 30%. 23.08% divides by Q4 instead of Q1.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक कंपनी की एक वर्ष की औसत तिमाही बिक्री ₹60 लाख थी। Q1, Q2 और Q3 की बिक्री ₹50 लाख, ₹55 लाख और ₹70 लाख थी। Q4 की बिक्री Q1 की बिक्री से कितने प्रतिशत अधिक थी?","optionsHi":["30%","15%","20%","23.08%"],"explanationHi":"कुल = 4 × 60 = 240, अतः Q4 = 240 − 175 = 65। (65 − 50)/50 = 30%। 23.08% में Q1 की जगह Q4 से भाग दिया गया है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-145","question":"The price of petrol rose from ₹96 to ₹104.64 per litre. What was the percentage increase?","options":["8.64%","9%","8.26%","10%"],"answer":1,"explanation":"Increase = 8.64 on a base of 96: 8.64/96 = 0.09 = 9%. 8.64% forgets to divide by the base, and 8.26% divides by the new price.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"पेट्रोल की कीमत ₹96 से बढ़कर ₹104.64 प्रति लीटर हो गई। प्रतिशत वृद्धि कितनी थी?","optionsHi":["8.64%","9%","8.26%","10%"],"explanationHi":"वृद्धि = 8.64, आधार 96 पर: 8.64/96 = 0.09 = 9%। 8.64% में आधार से भाग देना भूल गया है, और 8.26% में नई कीमत से भाग दिया गया है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-146","question":"Runs scored by a batsman in five matches — 48, 72, 15, 96, 69. In how many matches did he score more than his median score?","options":["3","1","2","4"],"answer":2,"explanation":"Sorted: 15, 48, 69, 72, 96, so the median is 69. Only 72 and 96 are above it. (The mean, 60, would give 3, a common mix-up.)","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक बल्लेबाज़ द्वारा पाँच मैचों में बनाए गए रन — 48, 72, 15, 96, 69। कितने मैचों में उसने अपने माध्यिका स्कोर से अधिक रन बनाए?","optionsHi":["3","1","2","4"],"explanationHi":"क्रमबद्ध: 15, 48, 69, 72, 96, अतः माध्यिका 69 है। केवल 72 और 96 इससे ऊपर हैं। (माध्य, 60, लेने पर 3 आता है, जो एक आम भूल है।)","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-147","question":"A man spends 25% of his monthly salary on rent and 20% on food. Of the rest he saves 40%, which comes to ₹13,200. What is his monthly salary?","options":["₹33,000","₹55,000","₹66,000","₹60,000"],"answer":3,"explanation":"After rent and food 55% is left; savings = 40% of 55% = 22% of salary. Salary = 13,200/0.22 = ₹60,000. ₹33,000 takes 40% of the whole salary.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक व्यक्ति अपने मासिक वेतन का 25% किराये पर और 20% भोजन पर खर्च करता है। शेष में से वह 40% बचाता है, जो ₹13,200 है। उसका मासिक वेतन कितना है?","optionsHi":["₹33,000","₹55,000","₹66,000","₹60,000"],"explanationHi":"किराये और भोजन के बाद 55% बचता है; बचत = 55% का 40% = वेतन का 22%। वेतन = 13,200/0.22 = ₹60,000। ₹33,000 में पूरे वेतन का 40% लिया गया है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-148","question":"Sales of product A rose from ₹120 lakh in 2022 to ₹150 lakh in 2023. Product B sold ₹80 lakh in 2022, and the combined sales of A and B grew by 30%. By what percentage did B's sales grow?","options":["37.5%","30%","35%","25%"],"answer":0,"explanation":"Combined 2023 = 200 × 1.3 = 260, so B's 2023 sales = 260 − 150 = 110. Growth = 30/80 = 37.5%.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"उत्पाद A की बिक्री 2022 के ₹120 लाख से बढ़कर 2023 में ₹150 लाख हो गई। उत्पाद B की बिक्री 2022 में ₹80 लाख थी, और A तथा B की संयुक्त बिक्री में 30% की वृद्धि हुई। B की बिक्री में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["37.5%","30%","35%","25%"],"explanationHi":"2023 की संयुक्त बिक्री = 200 × 1.3 = 260, अतः B की 2023 की बिक्री = 260 − 150 = 110। वृद्धि = 30/80 = 37.5%।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-149","question":"Students and the percentage of girls in three schools — P: 600, 40%; Q: 750, 52%; R: 900, x%. If girls make up 50% of the students of the three schools together, what is x?","options":["58","55","50","52"],"answer":1,"explanation":"Total girls = 50% of 2,250 = 1,125. P has 240 and Q has 390, so R has 495 girls: 495/900 = 55%.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"तीन विद्यालयों में विद्यार्थी और लड़कियों का प्रतिशत — P: 600, 40%; Q: 750, 52%; R: 900, x%। यदि तीनों विद्यालयों के विद्यार्थियों को मिलाकर लड़कियाँ 50% हैं, तो x कितना है?","optionsHi":["58","55","50","52"],"explanationHi":"कुल लड़कियाँ = 2,250 का 50% = 1,125। P में 240 और Q में 390 हैं, अतः R में 495 लड़कियाँ हैं: 495/900 = 55%।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-150","question":"A company's profit was 15% of its revenue in 2022 and 18% of its revenue in 2023. Its revenue grew by 20%. By what percentage did its profit grow?","options":["23%","20%","44%","38%"],"answer":2,"explanation":"Profit factor = 1.2 × 18/15 = 1.2 × 1.2 = 1.44, a 44% rise. Adding 20% and 3 points (23%) is the trap.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक कंपनी का लाभ 2022 में उसके राजस्व का 15% था और 2023 में उसके राजस्व का 18%। उसका राजस्व 20% बढ़ा। उसके लाभ में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["23%","20%","44%","38%"],"explanationHi":"लाभ का गुणक = 1.2 × 18/15 = 1.2 × 1.2 = 1.44, अर्थात् 44% की वृद्धि। 20% और 3 अंक जोड़ना (23%) जाल है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-151","question":"A plant's average yearly production over five years was 4,800 cars. The average of the first three years was 4,500 and that of the last three years was 5,200. How many cars were made in the third year?","options":["4,800","4,500","5,200","5,100"],"answer":3,"explanation":"The third year is counted in both triples: 13,500 + 15,600 − 24,000 = 5,100.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक संयंत्र का पाँच वर्षों का औसत वार्षिक उत्पादन 4,800 कारें था। पहले तीन वर्षों का औसत 4,500 था और अंतिम तीन वर्षों का 5,200। तीसरे वर्ष में कितनी कारें बनीं?","optionsHi":["4,800","4,500","5,200","5,100"],"explanationHi":"तीसरा वर्ष दोनों तिकड़ियों में गिना गया है: 13,500 + 15,600 − 24,000 = 5,100।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-152","question":"A pie chart shows the preferred exams of 7,200 aspirants — SSC 90°, Banking 120°, Railways 72°, State PSC 36° and Defence the rest. How many fewer aspirants chose Defence than Banking?","options":["1,560","1,200","840","1,800"],"answer":0,"explanation":"Defence = 360 − 318 = 42°. Difference = 120° − 42° = 78°, and 78/360 × 7,200 = 1,560 (each degree is 20 aspirants).","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक पाई चार्ट 7,200 अभ्यर्थियों की पसंदीदा परीक्षाएँ दर्शाता है — SSC 90°, बैंकिंग 120°, रेलवे 72°, राज्य लोक सेवा आयोग 36° और शेष रक्षा। रक्षा को बैंकिंग से कितने कम अभ्यर्थियों ने चुना?","optionsHi":["1,560","1,200","840","1,800"],"explanationHi":"रक्षा = 360 − 318 = 42°। अंतर = 120° − 42° = 78°, और 78/360 × 7,200 = 1,560 (प्रत्येक अंश 20 अभ्यर्थियों के बराबर है)।","subtopic":"pie-charts"},
  {"id":"quant-data-interpretation-153","question":"In 2022 factory A produced 1.5 times as many units as factory B. In 2023 A's output rose by 20% and B's by 50%, and together they produced 3,960 units. How many units did A produce in 2022?","options":["1,200","1,800","2,160","1,650"],"answer":1,"explanation":"With B = x: 1.5x × 1.2 + 1.5x = 3.3x = 3,960, so x = 1,200 and A = 1,800. 2,160 is A's 2023 output.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"2022 में कारखाना A ने कारखाना B से 1.5 गुना इकाइयाँ बनाईं। 2023 में A का उत्पादन 20% बढ़ा और B का 50%, और दोनों ने मिलकर 3,960 इकाइयाँ बनाईं। 2022 में A ने कितनी इकाइयाँ बनाईं?","optionsHi":["1,200","1,800","2,160","1,650"],"explanationHi":"B = x लेने पर: 1.5x × 1.2 + 1.5x = 3.3x = 3,960, अतः x = 1,200 और A = 1,800। 2,160 A का 2023 का उत्पादन है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-154","question":"Candidates who appeared in an exam and the percentage who qualified — 2021: 12,000, 15%; 2022: 15,000, 12%; 2023: x, 16%. The number who qualified in 2023 equalled the 2021 and 2022 figures combined. What is x?","options":["20,000","24,000","22,500","18,000"],"answer":2,"explanation":"Qualified 2021 = 1,800 and 2022 = 1,800, total 3,600. x = 3,600/0.16 = 22,500.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक परीक्षा में बैठे अभ्यर्थी और उत्तीर्ण होने वालों का प्रतिशत — 2021: 12,000, 15%; 2022: 15,000, 12%; 2023: x, 16%। 2023 में उत्तीर्ण होने वालों की संख्या 2021 और 2022 के आँकड़ों के योग के बराबर थी। x कितना है?","optionsHi":["20,000","24,000","22,500","18,000"],"explanationHi":"2021 में उत्तीर्ण = 1,800 और 2022 में = 1,800, कुल 3,600। x = 3,600/0.16 = 22,500।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-155","question":"An investor splits ₹6 lakh among equity, debt and gold in the ratio 5 : 3 : 2. After a year equity has returned 12%, debt 7% and gold −5%. What is the overall return on the portfolio?","options":["4.67%","8.2%","6.1%","7.1%"],"answer":3,"explanation":"Weighted return = 0.5 × 12 + 0.3 × 7 + 0.2 × (−5) = 6 + 2.1 − 1 = 7.1%. 4.67% is the plain average of the three returns.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक निवेशक ₹6 लाख को इक्विटी, ऋण और सोने में 5 : 3 : 2 के अनुपात में बाँटता है। एक वर्ष बाद इक्विटी पर 12%, ऋण पर 7% और सोने पर −5% प्रतिफल मिला। पोर्टफोलियो पर समग्र प्रतिफल कितना है?","optionsHi":["4.67%","8.2%","6.1%","7.1%"],"explanationHi":"भारित प्रतिफल = 0.5 × 12 + 0.3 × 7 + 0.2 × (−5) = 6 + 2.1 − 1 = 7.1%। 4.67% तीनों प्रतिफलों का साधारण औसत है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-156","question":"Passengers (lakh) on a rail route by class — 2021, 2022, 2023: Sleeper 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; General 200, 190, 210. Average fares (₹): Sleeper 400, AC-3 1,050, AC-2 1,500, General 150. How many passengers (lakh) travelled on the route in 2023?","options":["444","390","434","454"],"answer":0,"explanation":"2023 is the third figure in each class: 150 + 64 + 20 + 210 = 444 lakh. The fares are not needed; 434 or 454 come from misreading one figure.","difficulty":"easy","source":"SSC CHSL · IBPS Clerk","questionHi":"एक रेल मार्ग पर श्रेणी के अनुसार यात्री (लाख में) — 2021, 2022, 2023: स्लीपर 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; सामान्य 200, 190, 210। औसत किराये (₹): स्लीपर 400, AC-3 1,050, AC-2 1,500, सामान्य 150। 2023 में मार्ग पर कितने यात्रियों (लाख में) ने यात्रा की?","optionsHi":["444","390","434","454"],"explanationHi":"2023 प्रत्येक श्रेणी में तीसरा आँकड़ा है: 150 + 64 + 20 + 210 = 444 लाख। किरायों की आवश्यकता नहीं है; 434 या 454 किसी आँकड़े को गलत पढ़ने से आते हैं।","subtopic":"tables"},
  {"id":"quant-data-interpretation-157","question":"Passengers (lakh) on a rail route by class — 2021, 2022, 2023: Sleeper 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; General 200, 190, 210. Average fares (₹): Sleeper 400, AC-3 1,050, AC-2 1,500, General 150. By what percentage did AC-3 passengers increase from 2021 to 2023?","options":["28%","60%","24%","37.5%"],"answer":1,"explanation":"(64 − 40)/40 = 24/40 = 60%. 28% is the 2022-to-2023 growth and 24 is the absolute rise.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk · RRB NTPC","questionHi":"एक रेल मार्ग पर श्रेणी के अनुसार यात्री (लाख में) — 2021, 2022, 2023: स्लीपर 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; सामान्य 200, 190, 210। औसत किराये (₹): स्लीपर 400, AC-3 1,050, AC-2 1,500, सामान्य 150। 2021 से 2023 तक AC-3 के यात्रियों में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["28%","60%","24%","37.5%"],"explanationHi":"(64 − 40)/40 = 24/40 = 60%। 28% 2022 से 2023 की वृद्धि है और 24 निरपेक्ष वृद्धि है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-158","question":"Passengers (lakh) on a rail route by class — 2021, 2022, 2023: Sleeper 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; General 200, 190, 210. Average fares (₹): Sleeper 400, AC-3 1,050, AC-2 1,500, General 150. What is the ratio of the 2023 revenue from AC-3 to that from Sleeper?","options":["32 : 75","25 : 28","28 : 25","21 : 8"],"answer":2,"explanation":"AC-3: 64 × 1,050 = 67,200; Sleeper: 150 × 400 = 60,000 (both in ₹ lakh). 67,200 : 60,000 = 28 : 25. 32 : 75 compares passengers only.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक रेल मार्ग पर श्रेणी के अनुसार यात्री (लाख में) — 2021, 2022, 2023: स्लीपर 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; सामान्य 200, 190, 210। औसत किराये (₹): स्लीपर 400, AC-3 1,050, AC-2 1,500, सामान्य 150। 2023 में AC-3 से राजस्व और स्लीपर से राजस्व का अनुपात कितना है?","optionsHi":["32 : 75","25 : 28","28 : 25","21 : 8"],"explanationHi":"AC-3: 64 × 1,050 = 67,200; स्लीपर: 150 × 400 = 60,000 (दोनों ₹ लाख में)। 67,200 : 60,000 = 28 : 25। 32 : 75 केवल यात्रियों की तुलना है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-159","question":"Passengers (lakh) on a rail route by class — 2021, 2022, 2023: Sleeper 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; General 200, 190, 210. Average fares (₹): Sleeper 400, AC-3 1,050, AC-2 1,500, General 150. What was the total fare revenue from the route in 2023?","options":["₹1,572 crore","₹18,870 crore","₹1,787 crore","₹1,887 crore"],"answer":3,"explanation":"In ₹ lakh: 60,000 + 67,200 + 30,000 + 31,500 = 1,88,700 lakh = ₹1,887 crore (100 lakh = 1 crore).","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक रेल मार्ग पर श्रेणी के अनुसार यात्री (लाख में) — 2021, 2022, 2023: स्लीपर 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; सामान्य 200, 190, 210। औसत किराये (₹): स्लीपर 400, AC-3 1,050, AC-2 1,500, सामान्य 150। 2023 में मार्ग से कुल किराया राजस्व कितना था?","optionsHi":["₹1,572 करोड़","₹18,870 करोड़","₹1,787 करोड़","₹1,887 करोड़"],"explanationHi":"₹ लाख में: 60,000 + 67,200 + 30,000 + 31,500 = 1,88,700 लाख = ₹1,887 करोड़ (100 लाख = 1 करोड़)।","subtopic":"tables"},
  {"id":"quant-data-interpretation-160","question":"Passengers (lakh) on a rail route by class — 2021, 2022, 2023: Sleeper 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; General 200, 190, 210. Average fares (₹): Sleeper 400, AC-3 1,050, AC-2 1,500, General 150. Which class's share of the total passengers rose by the most percentage points from 2021 to 2023?","options":["AC-3","Sleeper","AC-2","General"],"answer":0,"explanation":"Totals: 375 (2021) and 444 (2023). Shares: Sleeper 32% → 33.8%, AC-3 10.7% → 14.4%, AC-2 4% → 4.5%, General 53.3% → 47.3%. AC-3 gains about 3.7 points, the most.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक रेल मार्ग पर श्रेणी के अनुसार यात्री (लाख में) — 2021, 2022, 2023: स्लीपर 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; सामान्य 200, 190, 210। औसत किराये (₹): स्लीपर 400, AC-3 1,050, AC-2 1,500, सामान्य 150। 2021 से 2023 तक किस श्रेणी का कुल यात्रियों में हिस्सा सबसे अधिक प्रतिशत अंकों से बढ़ा?","optionsHi":["AC-3","स्लीपर","AC-2","सामान्य"],"explanationHi":"कुल: 375 (2021) और 444 (2023)। हिस्से: स्लीपर 32% → 33.8%, AC-3 10.7% → 14.4%, AC-2 4% → 4.5%, सामान्य 53.3% → 47.3%। AC-3 लगभग 3.7 अंक बढ़ता है, जो सबसे अधिक है।","subtopic":"tables"},
  {"id":"quant-data-interpretation-161","question":"Passengers (lakh) on a rail route by class — 2021, 2022, 2023: Sleeper 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; General 200, 190, 210. Average fares (₹): Sleeper 400, AC-3 1,050, AC-2 1,500, General 150. In 2024 every fare rises by 10%. Passenger numbers stay at the 2023 level except General, which falls by 10%. By what percentage does total revenue change from 2023 (correct to two decimals)?","options":["10%","8.16%","6.5%","8.5%"],"answer":1,"explanation":"2023 revenue = ₹1,887 crore, with General contributing ₹315 crore. 2024 = 1.1 × (1,887 − 31.5) = ₹2,041.05 crore, a rise of 154.05/1,887 = 8.16%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक रेल मार्ग पर श्रेणी के अनुसार यात्री (लाख में) — 2021, 2022, 2023: स्लीपर 120, 132, 150; AC-3 40, 50, 64; AC-2 15, 18, 20; सामान्य 200, 190, 210। औसत किराये (₹): स्लीपर 400, AC-3 1,050, AC-2 1,500, सामान्य 150। 2024 में हर किराया 10% बढ़ जाता है। यात्रियों की संख्या 2023 के स्तर पर रहती है, केवल सामान्य श्रेणी को छोड़कर, जिसमें 10% की कमी आती है। 2023 की तुलना में कुल राजस्व कितने प्रतिशत बदलता है (दो दशमलव स्थानों तक सही)?","optionsHi":["10%","8.16%","6.5%","8.5%"],"explanationHi":"2023 का राजस्व = ₹1,887 करोड़, जिसमें सामान्य श्रेणी का योगदान ₹315 करोड़ है। 2024 = 1.1 × (1,887 − 31.5) = ₹2,041.05 करोड़, यानी 154.05/1,887 = 8.16% की वृद्धि।","subtopic":"tables"},
  {"id":"quant-data-interpretation-162","question":"In a survey of 1,200 households, 720 own a two-wheeler, 450 own a car and 180 own both. How many households own neither a two-wheeler nor a car?","options":["30","390","210","180"],"answer":2,"explanation":"Own at least one = 720 + 450 − 180 = 990, so neither = 1,200 − 990 = 210. 30 forgets to subtract the overlap.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"1,200 परिवारों के एक सर्वेक्षण में, 720 के पास दोपहिया वाहन है, 450 के पास कार है और 180 के पास दोनों हैं। कितने परिवारों के पास न तो दोपहिया वाहन है और न ही कार?","optionsHi":["30","390","210","180"],"explanationHi":"कम से कम एक रखने वाले = 720 + 450 − 180 = 990, अतः दोनों में से कोई नहीं = 1,200 − 990 = 210। 30 में उभयनिष्ठ को घटाना भूल गया है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-163","question":"In a survey of 1,200 households, 720 own a two-wheeler, 450 own a car and 180 own both. Among households that own exactly one of the two vehicles, what percentage own only a car?","options":["37.5%","22.5%","50%","33.33%"],"answer":3,"explanation":"Only car = 450 − 180 = 270; only two-wheeler = 720 − 180 = 540. Share = 270/810 = 33.33%. 37.5% uses 450/1,200.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"1,200 परिवारों के एक सर्वेक्षण में, 720 के पास दोपहिया वाहन है, 450 के पास कार है और 180 के पास दोनों हैं। जिन परिवारों के पास दोनों वाहनों में से ठीक एक है, उनमें से कितने प्रतिशत के पास केवल कार है?","optionsHi":["37.5%","22.5%","50%","33.33%"],"explanationHi":"केवल कार = 450 − 180 = 270; केवल दोपहिया = 720 − 180 = 540। हिस्सा = 270/810 = 33.33%। 37.5% में 450/1,200 लिया गया है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-164","question":"A country's export-to-import ratio was 4 : 5 in 2022 and 9 : 10 in 2023. Its imports grew by 20%. By what percentage did its exports grow?","options":["35%","20%","12.5%","28%"],"answer":0,"explanation":"Imports 5k → 6k, so 2023 exports = 0.9 × 6k = 5.4k against 4k in 2022: a 35% rise. 12.5% just compares the two ratios.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक देश का निर्यात-आयात अनुपात 2022 में 4 : 5 था और 2023 में 9 : 10। उसका आयात 20% बढ़ा। उसका निर्यात कितने प्रतिशत बढ़ा?","optionsHi":["35%","20%","12.5%","28%"],"explanationHi":"आयात 5k → 6k, अतः 2023 का निर्यात = 0.9 × 6k = 5.4k, जबकि 2022 में 4k था: 35% की वृद्धि। 12.5% केवल दोनों अनुपातों की तुलना है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-165","question":"The ₹50 lakh cost of a project is split as Labour 30%, Material 45%, Overheads 15% and Contingency 10%. Material cost then rises by 20% while everything else stays the same. What is Labour's new share of the total cost (correct to two decimals)?","options":["30%","27.52%","25%","28.5%"],"answer":1,"explanation":"Material rises by 20% of ₹22.5 lakh = ₹4.5 lakh, making the total ₹54.5 lakh. Labour (₹15 lakh) is now 15/54.5 = 27.52%.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक परियोजना की ₹50 लाख की लागत इस प्रकार बँटी है: श्रम 30%, सामग्री 45%, उपरिव्यय 15% और आकस्मिकता 10%। फिर सामग्री की लागत 20% बढ़ जाती है जबकि बाकी सब वही रहता है। कुल लागत में श्रम का नया हिस्सा कितना है (दो दशमलव स्थानों तक सही)?","optionsHi":["30%","27.52%","25%","28.5%"],"explanationHi":"सामग्री ₹22.5 लाख के 20% = ₹4.5 लाख बढ़ती है, जिससे कुल ₹54.5 लाख हो जाता है। श्रम (₹15 लाख) अब 15/54.5 = 27.52% है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-166","question":"A product's sales rose by 25% in 2022 and fell by 20% in 2023. By what percentage must sales rise in 2024 to be 10% above the 2021 level?","options":["5%","15%","10%","12.5%"],"answer":2,"explanation":"1.25 × 0.8 = 1, so 2023 sales are back exactly at the 2021 level, and a 10% rise is needed. 5% wrongly carries forward 25 − 20 = 5 points.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"एक उत्पाद की बिक्री 2022 में 25% बढ़ी और 2023 में 20% घटी। 2024 में बिक्री कितने प्रतिशत बढ़नी चाहिए ताकि वह 2021 के स्तर से 10% ऊपर हो जाए?","optionsHi":["5%","15%","10%","12.5%"],"explanationHi":"1.25 × 0.8 = 1, अतः 2023 की बिक्री ठीक 2021 के स्तर पर लौट आई है, और 10% की वृद्धि चाहिए। 5% में गलती से 25 − 20 = 5 अंक आगे ले जाए गए हैं।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-167","question":"Hours studied per day by 50 students — 1 hour: 8 students, 2 hours: 12, 3 hours: 15, 4 hours: 10, 5 hours: 5. What is the mean number of hours studied?","options":["3","2.5","3.2","2.84"],"answer":3,"explanation":"Σfx = 8 + 24 + 45 + 40 + 25 = 142, and 142/50 = 2.84 hours. 3 is the plain average of 1 to 5, which ignores the frequencies.","difficulty":"hard","source":"SSC CGL · IBPS PO · SBI PO","questionHi":"50 विद्यार्थियों द्वारा प्रतिदिन पढ़ाई के घंटे — 1 घंटा: 8 विद्यार्थी, 2 घंटे: 12, 3 घंटे: 15, 4 घंटे: 10, 5 घंटे: 5। पढ़ाई के घंटों का माध्य कितना है?","optionsHi":["3","2.5","3.2","2.84"],"explanationHi":"Σfx = 8 + 24 + 45 + 40 + 25 = 142, और 142/50 = 2.84 घंटे। 3, 1 से 5 तक का साधारण औसत है, जिसमें बारंबारताओं की अनदेखी होती है।","subtopic":"bar-graphs"},
  {"id":"quant-data-interpretation-168","question":"A bank gave two-wheeler loans of ₹48 crore to 1,600 customers in 2022. In 2023 the number of customers rose by 25% and the average loan fell by 4%. What was the total lent in 2023?","options":["₹57.6 crore","₹58.8 crore","₹60 crore","₹62.4 crore"],"answer":0,"explanation":"Total = customers × average loan, so the factor is 1.25 × 0.96 = 1.2: 48 × 1.2 = ₹57.6 crore. ₹58.8 crore wrongly adds 25% − 4% = 21%.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक बैंक ने 2022 में 1,600 ग्राहकों को ₹48 करोड़ के दोपहिया वाहन ऋण दिए। 2023 में ग्राहकों की संख्या 25% बढ़ी और औसत ऋण 4% घटा। 2023 में कुल कितना ऋण दिया गया?","optionsHi":["₹57.6 करोड़","₹58.8 करोड़","₹60 करोड़","₹62.4 करोड़"],"explanationHi":"कुल = ग्राहक × औसत ऋण, अतः गुणक 1.25 × 0.96 = 1.2: 48 × 1.2 = ₹57.6 करोड़। ₹58.8 करोड़ में गलती से 25% − 4% = 21% जोड़ा गया है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-169","question":"In a town 60% of the adults are employed, and 35% of the employed adults are women. If women make up half of all adults, what percentage of adult women are employed?","options":["35%","42%","21%","30%"],"answer":1,"explanation":"Employed women = 35% of 60% = 21% of all adults. Women are 50% of adults, so 21/50 = 42% of women are employed. 21% is the share of all adults.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कस्बे में 60% वयस्क नियोजित हैं, और नियोजित वयस्कों में 35% महिलाएँ हैं। यदि महिलाएँ सभी वयस्कों का आधा हैं, तो वयस्क महिलाओं का कितना प्रतिशत नियोजित है?","optionsHi":["35%","42%","21%","30%"],"explanationHi":"नियोजित महिलाएँ = 60% का 35% = सभी वयस्कों का 21%। महिलाएँ वयस्कों का 50% हैं, अतः 21/50 = 42% महिलाएँ नियोजित हैं। 21% सभी वयस्कों में हिस्सा है।","subtopic":"caselets"},
  {"id":"quant-data-interpretation-170","question":"A share closed at ₹250 on Friday. Its closing price then changed by +4% on Monday, −5% on Tuesday and +8% on Wednesday. What was its closing price on Wednesday?","options":["₹267.50","₹265.20","₹266.76","₹270"],"answer":2,"explanation":"250 × 1.04 × 0.95 × 1.08 = ₹266.76. Adding the changes (+7%) gives the trap ₹267.50; successive changes must be multiplied.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक शेयर शुक्रवार को ₹250 पर बंद हुआ। फिर उसका समापन मूल्य सोमवार को +4%, मंगलवार को −5% और बुधवार को +8% बदला। बुधवार को उसका समापन मूल्य क्या था?","optionsHi":["₹267.50","₹265.20","₹266.76","₹270"],"explanationHi":"250 × 1.04 × 0.95 × 1.08 = ₹266.76। परिवर्तनों को जोड़ने (+7%) पर जाल वाला ₹267.50 आता है; क्रमागत परिवर्तनों को गुणा करना चाहिए।","subtopic":"line-graphs"},
  {"id":"quant-data-interpretation-171","question":"Production (thousand tonnes) — Company A: 2019: 120, 2020: 150, 2021: 135, 2022: 210; Company B: 2019: 100, 2020: 150, 2021: 110, 2022: 200. By what percent is A's 2022 production more than B's average annual production over the four years?","options":["33⅓%","50%","5%","40%"],"answer":1,"explanation":"B's average = (100 + 150 + 110 + 200)/4 = 140. A's 2022 output of 210 exceeds it by (210 − 140)/140 = 50%. Comparing with B's 2022 figure (200) would give the trap 5%.","difficulty":"hard","questionHi":"उत्पादन (हज़ार टन) — कंपनी A: 2019: 120, 2020: 150, 2021: 135, 2022: 210; कंपनी B: 2019: 100, 2020: 150, 2021: 110, 2022: 200। A का 2022 का उत्पादन चारों वर्षों में B के औसत वार्षिक उत्पादन से कितने प्रतिशत अधिक है?","optionsHi":["33⅓%","50%","5%","40%"],"explanationHi":"B का औसत = (100 + 150 + 110 + 200)/4 = 140। A का 2022 का उत्पादन 210 इससे (210 − 140)/140 = 50% अधिक है। B के 2022 के आँकड़े (200) से तुलना करने पर गलत 5% आता है।","subtopic":"bar-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-172","question":"Exports (₹ crore) in 2020 and 2021 — Item P: 80, 100; Item Q: 120, 144; Item R: 200, 230. What is the difference, in percentage points, between the highest and the lowest percentage growth among the three items?","options":["5 percentage points","20 percentage points","15 percentage points","10 percentage points"],"answer":3,"explanation":"Growth rates: P = 20/80 = 25%, Q = 24/120 = 20%, R = 30/200 = 15%. Highest minus lowest = 25 − 15 = 10 percentage points.","difficulty":"moderate","questionHi":"2020 और 2021 में निर्यात (₹ करोड़) — वस्तु P: 80, 100; वस्तु Q: 120, 144; वस्तु R: 200, 230। तीनों वस्तुओं में सबसे अधिक और सबसे कम प्रतिशत वृद्धि का अंतर प्रतिशत अंकों में कितना है?","optionsHi":["5 प्रतिशत अंक","20 प्रतिशत अंक","15 प्रतिशत अंक","10 प्रतिशत अंक"],"explanationHi":"वृद्धि दरें: P = 20/80 = 25%, Q = 24/120 = 20%, R = 30/200 = 15%। सबसे अधिक − सबसे कम = 25 − 15 = 10 प्रतिशत अंक।","subtopic":"bar-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-173","question":"Students in five sections — Boys: 40, 50, 45, 60, 55; Girls: 35, 45, 50, 40, 60 (sections 1 to 5). On a rainy day 10% of the boys and 20% of the girls of section 4 were absent. How many students of section 4 were present?","options":["86","80","90","84"],"answer":0,"explanation":"Section 4 has 60 boys and 40 girls. Present: 90% of 60 = 54 boys and 80% of 40 = 32 girls, so 54 + 32 = 86 students.","difficulty":"hard","questionHi":"पाँच अनुभागों में विद्यार्थी — लड़के: 40, 50, 45, 60, 55; लड़कियाँ: 35, 45, 50, 40, 60 (अनुभाग 1 से 5)। एक बरसाती दिन अनुभाग 4 के 10% लड़के और 20% लड़कियाँ अनुपस्थित थे। अनुभाग 4 के कितने विद्यार्थी उपस्थित थे?","optionsHi":["86","80","90","84"],"explanationHi":"अनुभाग 4 में 60 लड़के और 40 लड़कियाँ हैं। उपस्थित: 60 के 90% = 54 लड़के और 40 के 80% = 32 लड़कियाँ, अतः 54 + 32 = 86 विद्यार्थी।","subtopic":"bar-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-174","question":"A firm's revenue (₹ lakh) and its profit percent on expenditure — 2019: 260, 30%; 2020: 330, 10%; 2021: 420, 20%; 2022: 510, 25%. What is the firm's total profit over the four years?","options":["₹322.5 lakh","₹283 lakh","₹262 lakh","₹240 lakh"],"answer":2,"explanation":"Profit is on expenditure, so expenditure = revenue/(1 + p). Expenditures are 200, 300, 350 and 408, giving profits 60, 30, 70 and 102, a total of ₹262 lakh. Taking the percent on revenue gives the trap ₹322.5 lakh.","difficulty":"very-hard","questionHi":"एक फर्म की आय (₹ लाख में) और व्यय पर उसका लाभ प्रतिशत — 2019: 260, 30%; 2020: 330, 10%; 2021: 420, 20%; 2022: 510, 25%। चारों वर्षों में फर्म का कुल लाभ कितना है?","optionsHi":["₹322.5 लाख","₹283 लाख","₹262 लाख","₹240 लाख"],"explanationHi":"लाभ व्यय पर है, अतः व्यय = आय/(1 + p)। व्यय 200, 300, 350 और 408 हैं, जिनसे लाभ 60, 30, 70 और 102 आते हैं, कुल ₹262 लाख। प्रतिशत को आय पर लेने से गलत ₹322.5 लाख आता है।","subtopic":"bar-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-175","question":"Number of students and their average marks in three classes — Class A: 50 students, 60 marks; Class B: 30 students, 70 marks; Class C: 20 students, 90 marks. What is the overall average mark of all the students?","options":["73⅓","70","69","68"],"answer":2,"explanation":"Weight by class size: (50 × 60 + 30 × 70 + 20 × 90)/100 = (3,000 + 2,100 + 1,800)/100 = 69. The simple mean of the three averages, 73⅓, ignores class sizes.","difficulty":"hard","questionHi":"तीन कक्षाओं में विद्यार्थियों की संख्या और उनके औसत अंक — कक्षा A: 50 विद्यार्थी, 60 अंक; कक्षा B: 30 विद्यार्थी, 70 अंक; कक्षा C: 20 विद्यार्थी, 90 अंक। सभी विद्यार्थियों के औसत अंक कितने हैं?","optionsHi":["73⅓","70","69","68"],"explanationHi":"कक्षा के आकार के अनुसार भारित औसत लें: (50 × 60 + 30 × 70 + 20 × 90)/100 = (3,000 + 2,100 + 1,800)/100 = 69। तीनों औसतों का साधारण माध्य 73⅓ कक्षा के आकार को नहीं गिनता।","subtopic":"bar-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-176","question":"Population (lakh) of five cities — City 1: 40, City 2: 55, City 3: 30, City 4: 70, City 5: 60. By what percent is the population of the largest city more than the average population of the two smallest cities?","options":["100%","75%","133⅓%","50%"],"answer":0,"explanation":"The two smallest are 30 and 40, averaging 35. The largest, 70, is (70 − 35)/35 = 100% more than that average.","difficulty":"hard","questionHi":"पाँच नगरों की जनसंख्या (लाख में) — नगर 1: 40, नगर 2: 55, नगर 3: 30, नगर 4: 70, नगर 5: 60। सबसे बड़े नगर की जनसंख्या दो सबसे छोटे नगरों की औसत जनसंख्या से कितने प्रतिशत अधिक है?","optionsHi":["100%","75%","133⅓%","50%"],"explanationHi":"दो सबसे छोटे नगर 30 और 40 हैं, जिनका औसत 35 है। सबसे बड़ा नगर, 70, उस औसत से (70 − 35)/35 = 100% अधिक है।","subtopic":"bar-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-177","question":"Exports and imports (₹ crore) over five years — Exports: 120, 150, 170, 160, 200; Imports: 140, 130, 200, 190, 210. What is the average annual trade balance (exports − imports) over the five years?","options":["Surplus of ₹14 crore","Deficit of ₹70 crore","Deficit of ₹10 crore","Deficit of ₹14 crore"],"answer":3,"explanation":"Total exports = 800 and total imports = 870, so the five-year balance is −70. The average is −70/5 = −14, i.e. a deficit of ₹14 crore a year; ₹70 crore is the total, not the average.","difficulty":"hard","questionHi":"पाँच वर्षों में निर्यात और आयात (₹ करोड़) — निर्यात: 120, 150, 170, 160, 200; आयात: 140, 130, 200, 190, 210। इन पाँच वर्षों में औसत वार्षिक व्यापार संतुलन (निर्यात − आयात) क्या है?","optionsHi":["₹14 करोड़ का अधिशेष","₹70 करोड़ का घाटा","₹10 करोड़ का घाटा","₹14 करोड़ का घाटा"],"explanationHi":"कुल निर्यात = 800 और कुल आयात = 870, अतः पाँच वर्ष का संतुलन −70 है। औसत −70/5 = −14, यानी प्रति वर्ष ₹14 करोड़ का घाटा; ₹70 करोड़ कुल घाटा है, औसत नहीं।","subtopic":"bar-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-178","question":"In an exam 300 boys and 200 girls appeared. 80% of the boys passed and the overall pass percentage was 86%. What percent of the girls passed?","options":["92%","95%","90%","94%"],"answer":1,"explanation":"Total passed = 86% of 500 = 430. Boys passed = 240, so girls passed = 190 out of 200, i.e. 95%. Averaging 80% and 86% would be wrong because the two groups differ in size.","difficulty":"very-hard","questionHi":"एक परीक्षा में 300 लड़के और 200 लड़कियाँ बैठे। 80% लड़के उत्तीर्ण हुए और कुल उत्तीर्ण प्रतिशत 86% रहा। कितने प्रतिशत लड़कियाँ उत्तीर्ण हुईं?","optionsHi":["92%","95%","90%","94%"],"explanationHi":"कुल उत्तीर्ण = 500 का 86% = 430। उत्तीर्ण लड़के = 240, अतः उत्तीर्ण लड़कियाँ = 200 में से 190, यानी 95%। 80% और 86% का औसत लेना गलत है क्योंकि दोनों समूहों का आकार समान नहीं है।","subtopic":"bar-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-179","question":"A town's population was 50,000. Over four successive years it changed by +10%, +20%, −10% and +5%. What was the population at the end of the four years?","options":["62,500","62,370","61,000","63,000"],"answer":1,"explanation":"Multiply the factors: 50,000 × 1.10 × 1.20 × 0.90 × 1.05 = 62,370. Adding the percentages (+25%) would give the trap 62,500.","difficulty":"hard","questionHi":"एक नगर की जनसंख्या 50,000 थी। लगातार चार वर्षों में उसमें क्रमशः +10%, +20%, −10% और +5% का परिवर्तन हुआ। चार वर्षों के अंत में जनसंख्या कितनी थी?","optionsHi":["62,500","62,370","61,000","63,000"],"explanationHi":"गुणकों को गुणा करें: 50,000 × 1.10 × 1.20 × 0.90 × 1.05 = 62,370। प्रतिशतों को जोड़ने (+25%) पर गलत 62,500 आता है।","subtopic":"line-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-180","question":"Revenue (₹ crore) of a company — 2018: 80, 2019: 100, 2020: 90, 2021: 135, 2022: 162. By what percent is the 2022 revenue more than the average revenue of the years 2018 to 2021?","options":["20%","62%","80%","60%"],"answer":3,"explanation":"Average of 2018–2021 = (80 + 100 + 90 + 135)/4 = 101.25. Then (162 − 101.25)/101.25 = 60%. The 20% is only the growth over 2021.","difficulty":"hard","questionHi":"एक कंपनी का राजस्व (₹ करोड़) — 2018: 80, 2019: 100, 2020: 90, 2021: 135, 2022: 162। 2022 का राजस्व 2018 से 2021 तक के वर्षों के औसत राजस्व से कितने प्रतिशत अधिक है?","optionsHi":["20%","62%","80%","60%"],"explanationHi":"2018 से 2021 का औसत = (80 + 100 + 90 + 135)/4 = 101.25। तब (162 − 101.25)/101.25 = 60%। 20% केवल 2021 की तुलना में वृद्धि है।","subtopic":"line-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-181","question":"Visitors (thousand) to a fair in six months — Jan: 40, Feb: 55, Mar: 66, Apr: 60, May: 90, Jun: 72. In how many months was the increase over the previous month more than 15% (counting from February)?","options":["3","2","4","5"],"answer":0,"explanation":"Changes: Feb +15/40 = 37.5%, Mar +11/55 = 20%, Apr −9.1%, May +30/60 = 50%, Jun −20%. The months above 15% are Feb, Mar and May, so 3.","difficulty":"hard","questionHi":"छह महीनों में एक मेले में आगंतुक (हज़ार में) — जनवरी: 40, फरवरी: 55, मार्च: 66, अप्रैल: 60, मई: 90, जून: 72। (फरवरी से गिनते हुए) कितने महीनों में पिछले महीने की तुलना में वृद्धि 15% से अधिक थी?","optionsHi":["3","2","4","5"],"explanationHi":"परिवर्तन: फरवरी +15/40 = 37.5%, मार्च +11/55 = 20%, अप्रैल −9.1%, मई +30/60 = 50%, जून −20%। 15% से अधिक वृद्धि वाले महीने फरवरी, मार्च और मई हैं, अतः 3।","subtopic":"line-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-182","question":"Profit (₹ lakh) of two firms from 2018 to 2022 — Firm X: 20, 28, 35, 30, 45; Firm Y: 25, 24, 40, 36, 42. In which year was the difference between the profits of Y and X the largest as a percentage of X's profit?","options":["2021","2019","2018","2022"],"answer":2,"explanation":"Differences as a percent of X: 2018 = 5/20 = 25%, 2019 = 4/28 = 14.3%, 2020 = 5/35 = 14.3%, 2021 = 6/30 = 20%, 2022 = 3/45 = 6.7%. The largest is 25% in 2018, even though 2021 has the larger absolute gap.","difficulty":"hard","questionHi":"दो फर्मों का 2018 से 2022 तक लाभ (₹ लाख में) — फर्म X: 20, 28, 35, 30, 45; फर्म Y: 25, 24, 40, 36, 42। किस वर्ष Y और X के लाभ का अंतर X के लाभ के प्रतिशत के रूप में सबसे अधिक था?","optionsHi":["2021","2019","2018","2022"],"explanationHi":"X के लाभ के प्रतिशत के रूप में अंतर: 2018 = 5/20 = 25%, 2019 = 4/28 = 14.3%, 2020 = 5/35 = 14.3%, 2021 = 6/30 = 20%, 2022 = 3/45 = 6.7%। सबसे अधिक 2018 में 25% है, यद्यपि 2021 में निरपेक्ष अंतर अधिक है।","subtopic":"line-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-183","question":"A family spends ₹600 every month on onions. The price per kg from January to May was ₹10, ₹15, ₹20, ₹12 and ₹30. What was the average price per kg paid over the five months?","options":["₹17.40","₹16","₹15","₹14"],"answer":2,"explanation":"Quantities bought are 60, 40, 30, 50 and 20 kg, i.e. 200 kg for ₹3,000, so the average price is ₹15 per kg. The simple mean of the prices, ₹17.40, ignores that more kg are bought when the price is low.","difficulty":"very-hard","questionHi":"एक परिवार हर महीने प्याज़ पर ₹600 खर्च करता है। जनवरी से मई तक प्रति kg कीमत ₹10, ₹15, ₹20, ₹12 और ₹30 थी। पाँच महीनों में चुकाई गई औसत कीमत प्रति kg कितनी रही?","optionsHi":["₹17.40","₹16","₹15","₹14"],"explanationHi":"खरीदी गई मात्राएँ 60, 40, 30, 50 और 20 kg हैं, यानी ₹3,000 में 200 kg, अतः औसत कीमत ₹15 प्रति kg है। कीमतों का साधारण माध्य ₹17.40 इस बात को नहीं गिनता कि कीमत कम होने पर अधिक kg खरीदे जाते हैं।","subtopic":"line-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-184","question":"A price index (base 2018 = 100) reads 110 in 2019, 132 in 2020, 118.8 in 2021 and 142.56 in 2022. What is the net percentage change from 2019 to 2022?","options":["29.6% increase","42.56% increase","20% increase","30% increase"],"answer":0,"explanation":"Percentage change = (142.56 − 110)/110 = 32.56/110 = 29.6%. The 42.56 is the change from the base year 2018, not from 2019.","difficulty":"hard","questionHi":"एक मूल्य सूचकांक (आधार वर्ष 2018 = 100) 2019 में 110, 2020 में 132, 2021 में 118.8 और 2022 में 142.56 है। 2019 से 2022 तक कुल प्रतिशत परिवर्तन कितना है?","optionsHi":["29.6% की वृद्धि","42.56% की वृद्धि","20% की वृद्धि","30% की वृद्धि"],"explanationHi":"प्रतिशत परिवर्तन = (142.56 − 110)/110 = 32.56/110 = 29.6%। 42.56 आधार वर्ष 2018 से हुआ परिवर्तन है, 2019 से नहीं।","subtopic":"line-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-185","question":"A city's population (lakh) was 40 in 2010, 48 in 2015 and 60 in 2020. If the growth rate for each five-year period rises by 5 percentage points over the previous period, what will the population be in 2025?","options":["75 lakh","72 lakh","80 lakh","78 lakh"],"answer":3,"explanation":"The growth rates were 20% (2010–15) and 25% (2015–20), so the next is 30%. Population in 2025 = 60 × 1.30 = 78 lakh. Using 25% again gives the trap 75 lakh.","difficulty":"moderate","questionHi":"एक नगर की जनसंख्या (लाख में) 2010 में 40, 2015 में 48 और 2020 में 60 थी। यदि प्रत्येक पाँच वर्ष की अवधि की वृद्धि दर पिछली अवधि से 5 प्रतिशत अंक बढ़ती जाए, तो 2025 में जनसंख्या कितनी होगी?","optionsHi":["75 लाख","72 लाख","80 लाख","78 लाख"],"explanationHi":"वृद्धि दरें 20% (2010–15) और 25% (2015–20) थीं, अतः अगली दर 30% होगी। 2025 में जनसंख्या = 60 × 1.30 = 78 लाख। फिर से 25% लेने पर गलत 75 लाख आता है।","subtopic":"line-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-186","question":"A family's monthly budget is shown in a pie chart with central angles — Food: 90°, Rent: 72°, Education: 54°, Transport: 36° and Savings: the remaining angle. Savings are what percent of the rent?","options":["66⅔%","150%","120%","75%"],"answer":1,"explanation":"Savings angle = 360° − (90° + 72° + 54° + 36°) = 108°. Savings/rent = 108/72 = 150%. The 66⅔% is rent as a percent of savings.","difficulty":"very-hard","questionHi":"एक परिवार का मासिक बजट एक पाई चार्ट में केंद्रीय कोणों के साथ दिखाया गया है — भोजन: 90°, किराया: 72°, शिक्षा: 54°, परिवहन: 36° और बचत: शेष कोण। बचत किराये का कितना प्रतिशत है?","optionsHi":["66⅔%","150%","120%","75%"],"explanationHi":"बचत का कोण = 360° − (90° + 72° + 54° + 36°) = 108°। बचत/किराया = 108/72 = 150%। 66⅔% किराये का बचत से प्रतिशत है।","subtopic":"pie-charts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-187","question":"A pie chart of 3,600 students shows: Arts 25%, Science 30%, Commerce 20%, Law 15% and Engineering 10%. If 40% of the Arts students and 50% of the Science students are girls, how many boys are there in Arts and Science together?","options":["900","1,080","1,980","1,440"],"answer":1,"explanation":"Arts = 900 and Science = 1,080 students. Boys: 60% of 900 = 540 and 50% of 1,080 = 540, so 1,080. The figure 900 is the number of girls.","difficulty":"hard","questionHi":"3,600 विद्यार्थियों के एक पाई चार्ट में दिखाया गया है: कला 25%, विज्ञान 30%, वाणिज्य 20%, विधि 15% और इंजीनियरिंग 10%। यदि कला के 40% विद्यार्थी और विज्ञान के 50% विद्यार्थी लड़कियाँ हैं, तो कला और विज्ञान में कुल मिलाकर कितने लड़के हैं?","optionsHi":["900","1,080","1,980","1,440"],"explanationHi":"कला = 900 और विज्ञान = 1,080 विद्यार्थी हैं। लड़के: 900 के 60% = 540 और 1,080 के 50% = 540, अतः 1,080। आँकड़ा 900 लड़कियों की संख्या है।","subtopic":"pie-charts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-188","question":"In 2020 the total budget was ₹80,000 and the sector for Transport was 15% of it. In 2021 the total budget was ₹90,000 and Transport was 20%. By what percent did spending on Transport increase?","options":["5%","33⅓%","25%","50%"],"answer":3,"explanation":"Transport spending: 15% of 80,000 = ₹12,000 in 2020 and 20% of 90,000 = ₹18,000 in 2021. The increase is 6,000/12,000 = 50%. The 5% is just the change in share points.","difficulty":"hard","questionHi":"2020 में कुल बजट ₹80,000 था और परिवहन का खंड उसका 15% था। 2021 में कुल बजट ₹90,000 था और परिवहन 20% था। परिवहन पर खर्च में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["5%","33⅓%","25%","50%"],"explanationHi":"परिवहन पर खर्च: 2020 में 80,000 का 15% = ₹12,000 और 2021 में 90,000 का 20% = ₹18,000। वृद्धि 6,000/12,000 = 50% है। 5% केवल हिस्सेदारी के अंकों का अंतर है।","subtopic":"pie-charts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-189","question":"In a pie chart, sector A has a central angle of 72°. Sector B is 25% larger than A, sector C is 20% smaller than B, and the rest of the circle is sector D. What percent of the total is sector D?","options":["35%","30%","36%","25%"],"answer":0,"explanation":"B = 72 × 1.25 = 90°, C = 90 × 0.8 = 72°, so D = 360 − (72 + 90 + 72) = 126°. That is 126/360 = 35% of the total.","difficulty":"hard","questionHi":"एक पाई चार्ट में खंड A का केंद्रीय कोण 72° है। खंड B, A से 25% बड़ा है, खंड C, B से 20% छोटा है और वृत्त का शेष भाग खंड D है। खंड D कुल का कितना प्रतिशत है?","optionsHi":["35%","30%","36%","25%"],"explanationHi":"B = 72 × 1.25 = 90°, C = 90 × 0.8 = 72°, अतः D = 360 − (72 + 90 + 72) = 126°। यह कुल का 126/360 = 35% है।","subtopic":"pie-charts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-190","question":"A pie chart of the sales of four firms has central angles A: 144°, B: 108°, C: 72°, D: 36°, with total sales of ₹4,500 crore. If A's sales rise by 10% and B's sales fall by 20%, while C and D stay the same, what is the new total sales?","options":["₹4,500 crore","₹4,545 crore","₹4,410 crore","₹4,320 crore"],"answer":2,"explanation":"Sales are A = 1,800, B = 1,350, C = 900 and D = 450. New A = 1,980 and new B = 1,080, so the total is 1,980 + 1,080 + 900 + 450 = ₹4,410 crore.","difficulty":"moderate","questionHi":"चार फर्मों की बिक्री के एक पाई चार्ट में केंद्रीय कोण A: 144°, B: 108°, C: 72°, D: 36° हैं और कुल बिक्री ₹4,500 करोड़ है। यदि A की बिक्री 10% बढ़ जाए और B की बिक्री 20% घट जाए, जबकि C और D की बिक्री वही रहे, तो नई कुल बिक्री कितनी होगी?","optionsHi":["₹4,500 करोड़","₹4,545 करोड़","₹4,410 करोड़","₹4,320 करोड़"],"explanationHi":"बिक्री A = 1,800, B = 1,350, C = 900 और D = 450 है। नया A = 1,980 और नया B = 1,080, अतः कुल = 1,980 + 1,080 + 900 + 450 = ₹4,410 करोड़।","subtopic":"pie-charts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-191","question":"In a pie chart of a family's expenses, the sector for Rent has a central angle of 54° and represents ₹13,500. How much is represented by a sector with a central angle of 126°?","options":["₹29,400","₹33,000","₹31,500","₹30,000"],"answer":2,"explanation":"₹13,500 per 54° means ₹250 per degree, so the whole circle is ₹90,000 and 126° represents 126 × 250 = ₹31,500.","difficulty":"moderate","questionHi":"एक परिवार के खर्चों के पाई चार्ट में किराये वाले खंड का केंद्रीय कोण 54° है और वह ₹13,500 दर्शाता है। 126° केंद्रीय कोण वाला खंड कितनी राशि दर्शाता है?","optionsHi":["₹29,400","₹33,000","₹31,500","₹30,000"],"explanationHi":"54° के लिए ₹13,500 का अर्थ है प्रति अंश ₹250, अतः पूरा वृत्त ₹90,000 है और 126° का खंड 126 × 250 = ₹31,500 दर्शाता है।","subtopic":"pie-charts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-192","question":"Company X has 12,000 employees and its pie chart shows 25% in IT. Company Y has 15,000 employees and its pie chart shows 28% in IT. What is the ratio of the number of IT employees in X to that in Y?","options":["5 : 7","25 : 28","7 : 5","4 : 5"],"answer":0,"explanation":"IT employees: X = 25% of 12,000 = 3,000 and Y = 28% of 15,000 = 4,200, so the ratio is 3,000 : 4,200 = 5 : 7. The ratio 25 : 28 compares only the percentages.","difficulty":"hard","questionHi":"कंपनी X में 12,000 कर्मचारी हैं और उसके पाई चार्ट में 25% IT विभाग में हैं। कंपनी Y में 15,000 कर्मचारी हैं और उसके पाई चार्ट में 28% IT विभाग में हैं। X के IT कर्मचारियों की संख्या और Y के IT कर्मचारियों की संख्या का अनुपात क्या है?","optionsHi":["5 : 7","25 : 28","7 : 5","4 : 5"],"explanationHi":"IT कर्मचारी: X = 12,000 का 25% = 3,000 और Y = 15,000 का 28% = 4,200, अतः अनुपात 3,000 : 4,200 = 5 : 7। अनुपात 25 : 28 केवल प्रतिशतों की तुलना करता है।","subtopic":"pie-charts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-193","question":"A factory's production (units) from 2018 to 2022 was 400, 450, 500, 480 and 600, and the percent of each year's production that was sold was 80, 90, 70, 75 and 85 respectively. How many units were left unsold over the five years?","options":["515","405","1,945","485"],"answer":3,"explanation":"Unsold each year = production × (100 − sold%): 80, 45, 150, 120 and 90, totalling 485. The figure 1,945 is the number of units sold.","difficulty":"very-hard","questionHi":"एक कारखाने का 2018 से 2022 तक उत्पादन (इकाइयों में) क्रमशः 400, 450, 500, 480 और 600 था और प्रत्येक वर्ष के उत्पादन का बिके हुए भाग का प्रतिशत क्रमशः 80, 90, 70, 75 और 85 था। पाँच वर्षों में कितनी इकाइयाँ बिना बिके रह गईं?","optionsHi":["515","405","1,945","485"],"explanationHi":"प्रत्येक वर्ष बिना बिकी इकाइयाँ = उत्पादन × (100 − बिके का %): 80, 45, 150, 120 और 90, कुल 485। आँकड़ा 1,945 बिकी हुई इकाइयों की संख्या है।","subtopic":"mixed-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-194","question":"Revenue and expenditure (₹ lakh) of a firm — 2020: 450 and 360; 2021: 560 and 420; 2022: 700 and 500. By what percent is the profit percent in 2022 higher than the profit percent in 2020? (Profit percent is on expenditure.)","options":["15%","60%","37.5%","40%"],"answer":1,"explanation":"Profit % in 2020 = 90/360 = 25% and in 2022 = 200/500 = 40%. The relative rise is (40 − 25)/25 = 60%. The 15% is the gap in percentage points.","difficulty":"hard","questionHi":"एक फर्म की आय और व्यय (₹ लाख में) — 2020: 450 और 360; 2021: 560 और 420; 2022: 700 और 500। 2022 का लाभ प्रतिशत 2020 के लाभ प्रतिशत से कितने प्रतिशत अधिक है? (लाभ प्रतिशत व्यय पर है।)","optionsHi":["15%","60%","37.5%","40%"],"explanationHi":"2020 में लाभ % = 90/360 = 25% और 2022 में = 200/500 = 40%। सापेक्ष वृद्धि (40 − 25)/25 = 60%। 15% प्रतिशत अंकों का अंतर है।","subtopic":"mixed-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-195","question":"Candidates appeared (thousand) and the percent qualifying — Exam A: 250, 12%; Exam B: 180, 15%; Exam C: 270, 10%. What is the overall percentage of candidates who qualified across the three exams?","options":["12⅓%","12%","11.5%","13%"],"answer":1,"explanation":"Qualified = 30 + 27 + 27 = 84 thousand out of 700 thousand, i.e. 12%. The simple mean of the three percentages, 12⅓%, ignores the different numbers appearing.","difficulty":"hard","questionHi":"परीक्षा में बैठे अभ्यर्थी (हज़ार में) और उत्तीर्ण प्रतिशत — परीक्षा A: 250, 12%; परीक्षा B: 180, 15%; परीक्षा C: 270, 10%। तीनों परीक्षाओं में कुल मिलाकर उत्तीर्ण अभ्यर्थियों का प्रतिशत कितना है?","optionsHi":["12⅓%","12%","11.5%","13%"],"explanationHi":"उत्तीर्ण = 30 + 27 + 27 = 84 हज़ार, कुल 700 हज़ार में से, यानी 12%। तीनों प्रतिशतों का साधारण माध्य 12⅓% बैठे अभ्यर्थियों की भिन्न संख्याओं को नहीं गिनता।","subtopic":"mixed-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-196","question":"A company's revenue (₹ crore) and number of employees — 2019: 240 and 120; 2020: 270 and 90; 2021: 330 and 110. By what percent did the revenue per employee change from 2019 to 2021?","options":["37.5% increase","33⅓% increase","45% increase","50% increase"],"answer":3,"explanation":"Revenue per employee = 240/120 = ₹2 crore in 2019 and 330/110 = ₹3 crore in 2021, a rise of 1/2 = 50%. The 37.5% is the growth in total revenue alone.","difficulty":"very-hard","questionHi":"एक कंपनी का राजस्व (₹ करोड़) और कर्मचारियों की संख्या — 2019: 240 और 120; 2020: 270 और 90; 2021: 330 और 110। 2019 से 2021 तक प्रति कर्मचारी राजस्व में कितने प्रतिशत का परिवर्तन हुआ?","optionsHi":["37.5% की वृद्धि","33⅓% की वृद्धि","45% की वृद्धि","50% की वृद्धि"],"explanationHi":"प्रति कर्मचारी राजस्व 2019 में 240/120 = ₹2 करोड़ और 2021 में 330/110 = ₹3 करोड़ है, यानी 1/2 = 50% की वृद्धि। 37.5% केवल कुल राजस्व की वृद्धि है।","subtopic":"mixed-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-197","question":"In 2021 three factories P, Q and R made 24,000 units in all, in the shares 40%, 35% and 25%. In 2022 the total output rose by 25%, and the shares became 36% for P, 34% for Q and the rest for R. By what percent did R's output increase?","options":["50%","25%","30%","20%"],"answer":0,"explanation":"R made 25% of 24,000 = 6,000 in 2021. In 2022 the total is 30,000 and R's share is 100 − 36 − 34 = 30%, i.e. 9,000. The increase is 3,000/6,000 = 50%.","difficulty":"very-hard","questionHi":"2021 में तीन कारखानों P, Q और R ने कुल मिलाकर 24,000 इकाइयाँ बनाईं, जिनकी हिस्सेदारी 40%, 35% और 25% थी। 2022 में कुल उत्पादन 25% बढ़ गया और हिस्सेदारी P की 36%, Q की 34% तथा शेष R की हो गई। R के उत्पादन में कितने प्रतिशत की वृद्धि हुई?","optionsHi":["50%","25%","30%","20%"],"explanationHi":"2021 में R ने 24,000 का 25% = 6,000 बनाया। 2022 में कुल 30,000 है और R की हिस्सेदारी 100 − 36 − 34 = 30% है, यानी 9,000। वृद्धि 3,000/6,000 = 50% है।","subtopic":"mixed-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-198","question":"Enrolment and pass percentage in a school — 2019: 1,200 students, 70%; 2020: 1,500 students, 64%; 2021: 1,800 students, 75%. How many students failed over the three years in all?","options":["1,530","1,125","1,350","3,150"],"answer":2,"explanation":"Failures each year: 30% of 1,200 = 360, 36% of 1,500 = 540 and 25% of 1,800 = 450, a total of 1,350. The figure 3,150 is the number who passed.","difficulty":"moderate","questionHi":"एक विद्यालय में नामांकन और उत्तीर्ण प्रतिशत — 2019: 1,200 विद्यार्थी, 70%; 2020: 1,500 विद्यार्थी, 64%; 2021: 1,800 विद्यार्थी, 75%। तीनों वर्षों में कुल कितने विद्यार्थी अनुत्तीर्ण हुए?","optionsHi":["1,530","1,125","1,350","3,150"],"explanationHi":"प्रत्येक वर्ष अनुत्तीर्ण: 1,200 का 30% = 360, 1,500 का 36% = 540 और 1,800 का 25% = 450, कुल 1,350। आँकड़ा 3,150 उत्तीर्ण विद्यार्थियों की संख्या है।","subtopic":"mixed-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-199","question":"Total employees and male : female ratio of a firm — 2019: 5,000 (3 : 2); 2020: 6,000 (7 : 5); 2021: 7,000 (4 : 3). By how many does the number of males in 2021 exceed the number of females in 2020?","options":["1,000","2,000","1,500","500"],"answer":2,"explanation":"Males in 2021 = 4/7 × 7,000 = 4,000. Females in 2020 = 5/12 × 6,000 = 2,500. The difference is 4,000 − 2,500 = 1,500.","difficulty":"moderate","questionHi":"एक फर्म के कुल कर्मचारी और पुरुष : महिला का अनुपात — 2019: 5,000 (3 : 2); 2020: 6,000 (7 : 5); 2021: 7,000 (4 : 3)। 2021 में पुरुषों की संख्या 2020 में महिलाओं की संख्या से कितनी अधिक है?","optionsHi":["1,000","2,000","1,500","500"],"explanationHi":"2021 में पुरुष = 4/7 × 7,000 = 4,000। 2020 में महिलाएँ = 5/12 × 6,000 = 2,500। अंतर 4,000 − 2,500 = 1,500 है।","subtopic":"mixed-graphs","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-200","question":"In a company 70% of the employees are in the technical department and the rest in the non-technical department. The average salary in the technical department is 50% more than in the non-technical department, and the average salary of all employees is ₹67,500. What is the average salary in the technical department?","options":["₹75,000","₹50,000","₹81,000","₹72,000"],"answer":0,"explanation":"Let the non-technical average be x; technical = 1.5x. Overall = 0.7(1.5x) + 0.3x = 1.35x = 67,500, so x = ₹50,000 and the technical average is 1.5 × 50,000 = ₹75,000.","difficulty":"hard","questionHi":"एक कंपनी में 70% कर्मचारी तकनीकी विभाग में हैं और शेष गैर-तकनीकी विभाग में। तकनीकी विभाग का औसत वेतन गैर-तकनीकी विभाग से 50% अधिक है और सभी कर्मचारियों का औसत वेतन ₹67,500 है। तकनीकी विभाग का औसत वेतन कितना है?","optionsHi":["₹75,000","₹50,000","₹81,000","₹72,000"],"explanationHi":"गैर-तकनीकी औसत x मानें; तकनीकी = 1.5x। कुल औसत = 0.7(1.5x) + 0.3x = 1.35x = 67,500, अतः x = ₹50,000 और तकनीकी औसत 1.5 × 50,000 = ₹75,000।","subtopic":"caselets","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-201","question":"A's income is 20% more than B's, and B's income is 25% less than C's. If the three together earn ₹1,06,000, what is A's income?","options":["₹30,000","₹40,000","₹32,000","₹36,000"],"answer":3,"explanation":"Let C = 100: B = 75 and A = 1.2 × 75 = 90, so the total is 265 parts = ₹1,06,000 and one part is ₹400. A = 90 × 400 = ₹36,000 (B = 30,000 and C = 40,000).","difficulty":"hard","questionHi":"A की आय B की आय से 20% अधिक है और B की आय C की आय से 25% कम है। यदि तीनों की कुल आय ₹1,06,000 है, तो A की आय कितनी है?","optionsHi":["₹30,000","₹40,000","₹32,000","₹36,000"],"explanationHi":"C = 100 लें: B = 75 और A = 1.2 × 75 = 90, अतः कुल 265 भाग = ₹1,06,000 और एक भाग ₹400 है। A = 90 × 400 = ₹36,000 (B = 30,000 और C = 40,000)।","subtopic":"caselets","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-202","question":"A town has 20,000 people, of whom 55% are males. 60% of the males and 40% of the females are literate. How many people in the town are literate?","options":["9,900","10,200","10,000","11,000"],"answer":1,"explanation":"Males = 11,000 and females = 9,000. Literate males = 6,600 and literate females = 3,600, so 6,600 + 3,600 = 10,200. The 10,000 comes from averaging 60% and 40% as 50%.","difficulty":"hard","questionHi":"एक नगर में 20,000 लोग हैं, जिनमें 55% पुरुष हैं। 60% पुरुष और 40% महिलाएँ साक्षर हैं। नगर में कितने लोग साक्षर हैं?","optionsHi":["9,900","10,200","10,000","11,000"],"explanationHi":"पुरुष = 11,000 और महिलाएँ = 9,000। साक्षर पुरुष = 6,600 और साक्षर महिलाएँ = 3,600, अतः 6,600 + 3,600 = 10,200। 60% और 40% का औसत 50% लेने पर 10,000 आता है, जो गलत है।","subtopic":"caselets","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-203","question":"A bank has ₹8,000 crore of loans: 40% home loans, 25% car loans and the rest personal loans. The default rates are 2% on home loans, 4% on car loans and 10% on personal loans. What is the total amount defaulted?","options":["₹480 crore","₹424 crore","₹400 crore","₹336 crore"],"answer":1,"explanation":"Home = 3,200 × 2% = 64; car = 2,000 × 4% = 80; personal = 35% × 8,000 = 2,800 × 10% = 280. The total is 64 + 80 + 280 = ₹424 crore.","difficulty":"hard","questionHi":"एक बैंक के पास ₹8,000 करोड़ के ऋण हैं: 40% आवास ऋण, 25% कार ऋण और शेष व्यक्तिगत ऋण। चूक की दरें आवास ऋण पर 2%, कार ऋण पर 4% और व्यक्तिगत ऋण पर 10% हैं। चूक की गई कुल राशि कितनी है?","optionsHi":["₹480 करोड़","₹424 करोड़","₹400 करोड़","₹336 करोड़"],"explanationHi":"आवास = 3,200 × 2% = 64; कार = 2,000 × 4% = 80; व्यक्तिगत = 8,000 का 35% = 2,800 × 10% = 280। कुल 64 + 80 + 280 = ₹424 करोड़।","subtopic":"caselets","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-204","question":"In a survey of 600 people, 360 read newspaper A, 300 read newspaper B and 120 read neither. Among those who read exactly one of the two newspapers, what percent read only B?","options":["50%","25%","33⅓%","40%"],"answer":3,"explanation":"At least one = 600 − 120 = 480, so both = 360 + 300 − 480 = 180. Only A = 180 and only B = 120, so only B is 120/300 = 40% of those reading exactly one.","difficulty":"very-hard","questionHi":"600 लोगों के एक सर्वेक्षण में 360 लोग समाचार-पत्र A पढ़ते हैं, 300 लोग समाचार-पत्र B पढ़ते हैं और 120 लोग कोई भी नहीं पढ़ते। दोनों में से केवल एक समाचार-पत्र पढ़ने वालों में कितने प्रतिशत केवल B पढ़ते हैं?","optionsHi":["50%","25%","33⅓%","40%"],"explanationHi":"कम से कम एक = 600 − 120 = 480, अतः दोनों = 360 + 300 − 480 = 180। केवल A = 180 और केवल B = 120, इसलिए ठीक एक पढ़ने वालों में केवल B 120/300 = 40% हैं।","subtopic":"caselets","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-205","question":"State X: area 80 thousand km², density 450 per km²; State Y: area 120 thousand km², density 300 per km²; State Z: area 100 thousand km², density 540 per km². What is the combined population density of the three states per km²?","options":["420","430","400","410"],"answer":0,"explanation":"Population (thousand) = 80 × 450 + 120 × 300 + 100 × 540 = 36,000 + 36,000 + 54,000 = 126,000 over 300 thousand km², so the density is 420 per km². The simple mean of the densities, 430, ignores the areas.","difficulty":"hard","questionHi":"राज्य X: क्षेत्रफल 80 हज़ार km², घनत्व 450 प्रति km²; राज्य Y: क्षेत्रफल 120 हज़ार km², घनत्व 300 प्रति km²; राज्य Z: क्षेत्रफल 100 हज़ार km², घनत्व 540 प्रति km²। तीनों राज्यों का संयुक्त जनसंख्या घनत्व प्रति km² कितना है?","optionsHi":["420","430","400","410"],"explanationHi":"जनसंख्या (हज़ार में) = 80 × 450 + 120 × 300 + 100 × 540 = 36,000 + 36,000 + 54,000 = 126,000, क्षेत्रफल 300 हज़ार km² पर, अतः घनत्व 420 प्रति km²। घनत्वों का साधारण माध्य 430 क्षेत्रफल को नहीं गिनता।","subtopic":"tables","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-206","question":"Marks of four candidates in three papers (out of 100) — A: 80, 70, 60; B: 60, 80, 70; C: 90, 50, 65; D: 70, 60, 75. The papers carry weights 2 : 3 : 5. What is the difference between the highest and the lowest weighted score?","options":["5","6","5.5","4.5"],"answer":2,"explanation":"Weighted scores = (2a + 3b + 5c)/10: A = 67, B = 71, C = 65.5 and D = 69.5. The difference between the highest (B, 71) and the lowest (C, 65.5) is 5.5.","difficulty":"hard","questionHi":"चार अभ्यर्थियों के तीन प्रश्न-पत्रों में अंक (100 में से) — A: 80, 70, 60; B: 60, 80, 70; C: 90, 50, 65; D: 70, 60, 75। प्रश्न-पत्रों का भारांक 2 : 3 : 5 है। सबसे अधिक और सबसे कम भारित अंकों का अंतर कितना है?","optionsHi":["5","6","5.5","4.5"],"explanationHi":"भारित अंक = (2a + 3b + 5c)/10: A = 67, B = 71, C = 65.5 और D = 69.5। सबसे अधिक (B, 71) और सबसे कम (C, 65.5) का अंतर 5.5 है।","subtopic":"tables","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-207","question":"Three items — Item 1: cost price ₹800, marked price ₹1,200, discount 25%; Item 2: cost price ₹1,600, marked price ₹1,600, no discount; Item 3: cost price ₹600, marked price ₹1,000, discount 25%. What is the overall profit percent on all three items together?","options":["12.5%","10%","8⅓%","9⅓%"],"answer":2,"explanation":"Selling prices are 900, 1,600 and 750, totalling ₹3,250 against a cost of ₹3,000, so the profit is 250/3,000 = 8⅓%. The simple mean of the item profit percents, (12.5 + 0 + 25)/3 = 12.5%, ignores the different costs.","difficulty":"very-hard","questionHi":"तीन वस्तुएँ — वस्तु 1: क्रय मूल्य ₹800, अंकित मूल्य ₹1,200, छूट 25%; वस्तु 2: क्रय मूल्य ₹1,600, अंकित मूल्य ₹1,600, कोई छूट नहीं; वस्तु 3: क्रय मूल्य ₹600, अंकित मूल्य ₹1,000, छूट 25%। तीनों वस्तुओं पर मिलाकर कुल लाभ प्रतिशत कितना है?","optionsHi":["12.5%","10%","8⅓%","9⅓%"],"explanationHi":"विक्रय मूल्य 900, 1,600 और 750 हैं, कुल ₹3,250, जबकि लागत ₹3,000 है, अतः लाभ 250/3,000 = 8⅓%। वस्तुओं के लाभ प्रतिशतों का साधारण माध्य (12.5 + 0 + 25)/3 = 12.5% भिन्न लागतों को नहीं गिनता।","subtopic":"tables","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-data-interpretation-208","question":"Employees and average monthly salary — Department A: 20 employees, ₹40,000; Department B: 30 employees, ₹50,000; Department C: 50 employees, ₹60,000. If 20 employees of Department C whose average salary is ₹70,000 leave, what is the new average salary of the remaining employees?","options":["₹48,750","₹53,000","₹50,000","₹48,500"],"answer":0,"explanation":"Total salary = 20 × 40,000 + 30 × 50,000 + 50 × 60,000 = ₹53 lakh. Leavers take 20 × 70,000 = ₹14 lakh, leaving ₹39 lakh for 80 employees, i.e. ₹48,750. The ₹53,000 is the old average.","difficulty":"hard","questionHi":"कर्मचारी और औसत मासिक वेतन — विभाग A: 20 कर्मचारी, ₹40,000; विभाग B: 30 कर्मचारी, ₹50,000; विभाग C: 50 कर्मचारी, ₹60,000। यदि विभाग C के 20 कर्मचारी, जिनका औसत वेतन ₹70,000 है, चले जाएँ, तो शेष कर्मचारियों का नया औसत वेतन कितना होगा?","optionsHi":["₹48,750","₹53,000","₹50,000","₹48,500"],"explanationHi":"कुल वेतन = 20 × 40,000 + 30 × 50,000 + 50 × 60,000 = ₹53 लाख। जाने वाले कर्मचारी 20 × 70,000 = ₹14 लाख ले जाते हैं, अतः 80 कर्मचारियों के लिए ₹39 लाख बचते हैं, यानी ₹48,750। ₹53,000 पुराना औसत है।","subtopic":"tables","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
